INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191RM7VD3096N1HHQR33CGG', 'adr', 'accepted', 'The repository vendors dpm v0.7.0 as its starting commit and takes no dependency — package, git, or copy-script — on the marketplace repository, with fixes flowing between the two by hand when worth it.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191RNNDK285PEV27X5E1CNR', 'adr', 'accepted', 'The bundled MCP server stays the tool surface and the plugin''s job is registration rather than reimplementation, keeping the typed contract and its conformance tests intact.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191RQKT7NBX0VX40QSB72WC', 'adr', 'accepted', 'The port is authored in TypeScript restricted to erasable syntax and ships sources rather than artefacts, with the Node floor raised from 22.5 to 24 so native type-stripping and a stable `node:sqlite` arrive together.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191RRP9GTJY53WP9RCDNW9X', 'adr', 'accepted', 'Schema, ULID identity, number sequences, the document supertype, coverage and the one-way projection are inherited without modification, and this specification re-decides nothing below the host boundary.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191RY452PMYKB35R7NDD60M', 'adr', 'accepted', 'The plugin registers skills from its own package rather than asking users to copy directories into the project, and skill IDs are prefixed `dpm-` because v2 skill IDs are a flat last-source-wins namespace where names like `review` and `status` invite silent collisions.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191S0HPM9P3PXXJGRH3M34K', 'adr', 'accepted', 'Skill descriptions rewritten as model-facing language are the primary invocation path, with the prefixed slash entry alongside them, and FR11''s explicit commands stand as the named contingency if catalog ergonomics disappoint in practice.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191S1ZQYSAY12930K9A3HNC', 'adr', 'accepted', 'Setup returns a cleanup that disposes registrations, and no transform closes over mutable state a replay would observe differently — the server command, skill list and command list are computed before the transform registers.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M191S3JWSJVCT8FC6YHPS3AR', 'adr', 'accepted', 'Support for weaker models is a registration-time choice selected by plugin option against the same server and the same database, and the model-facing surface it varies is skill prose, the advertised tool surface, and the text of tool refusals — everything below those three is deterministic code no model reads.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M1BRZF6RZET0X87F8HBD1VWM', 'adr', 'accepted', 'A typed MCP tool returns a named shared document and every skill body opens by calling it, so the conventions reach the model identically on both hosts, through the one boundary that is already host-agnostic, and `resolveSupportingPaths` is deleted rather than duplicated.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M1BS1PKT28DGEWHFDZE889PT', 'adr', 'accepted', 'The package keeps a single entry point and detects which host loaded it in one named predicate that carries its own test and a control, with two registrars beneath it sharing the inputs computed before either runs.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M1BS1S883B15Q557G93HBFNS', 'adr', 'accepted', 'Skill registration under v1 goes through `Config.skills.paths` despite its absence from the SDK types and the published schema, confined to one module, labelled as unsupported where a maintainer will read it, and guarded by a registration-time check that turns the host silently discarding it into a loud failure.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M1BS1W0Z2W3APKKB2XQJRVDV', 'adr', 'accepted', 'The twenty-three skill directories and their front-matter names are renamed to `dpm-*` and the v2 registrar stops prepending a prefix the name now carries, so one identity serves both hosts, one permission rule matches on both, and one set of bodies can name its cross-references truthfully.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M1BS1XJ6GP8VN4D8PQAGXXZM', 'adr', 'accepted', 'The v1 SDK is installed as an aliased devDependency alongside the v2 one, so both registrars are type-checked against the real published types of the host they target and `dependencies` stays empty.');
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SAM6Y0TNQFMCKVP5PYXG', '01M191RM7VD3096N1HHQR33CGG', 'Clean fork with hand-carried fixes', 1, 'Neither codebase constrains the other. Each is native to its host and free to take that host''s idiom, and the cost — two codebases, fixes moved by hand — is paid in maintenance rather than in design compromise.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SCJ3TVBYRQB9H6CQ10PD', '01M191RM7VD3096N1HHQR33CGG', 'Shared dpm-core package', 0, 'Rejected. The extraction cost lands immediately and in full, while the benefit only materialises if both hosts stay API-compatible with the core — which OpenCode v2''s beta churn makes unlikely within the year. It also forks the invariant part of the system in order to serve the variable part.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SFSCA29S5JW00CYRJPXY', '01M191RNNDK285PEV27X5E1CNR', 'Keep the bundled MCP server; the plugin registers it', 1, 'The MCP server is the most tested seam in dpm — 133 test files point at it — and the typed contract with its conformance tests carries over wholesale. The server also keeps working for any other MCP-speaking host. Shipping a proven child process beats shipping an unproven native surface.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SHAXKPYCG07XS2JN3HCJ', '01M191RNNDK285PEV27X5E1CNR', 'Native plugin tools via the host''s tool transform', 0, 'Rejected for this iteration, not on principle. It would eliminate the child process, but it discards the conformance suite and replaces a tested boundary with a beta API. It remains open as a future migration, and the plugin is the obvious seam to do it behind — which is why this decision is recorded as reversible rather than settled.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SR8NV7XB6DK4BYNT3VT6', '01M191RQKT7NBX0VX40QSB72WC', 'Erasable TypeScript on Node 24, sources shipped', 1, 'OpenCode loads a plugin''s TypeScript entry directly, and Node 24 type-strips erasable TypeScript natively — so types are available to authors with no artefact to build, publish or keep in sync. Raising the floor to 24 buys stable native execution and a stable `node:sqlite` in one move, and a new repository has no installed base to protect.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SV08QV6AHRD0BGKG8ZP8', '01M191RQKT7NBX0VX40QSB72WC', 'TypeScript with a build step', 0, 'Rejected. It lifts the syntax restrictions but introduces a compile between source and behaviour, an artefact that can drift from its source, and a publish step that can ship a stale build. It also breaks the property that each executable runs directly with `node`.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191SXHNSHYDVR82V0MRQMKZ', '01M191RQKT7NBX0VX40QSB72WC', 'Stay on plain JavaScript', 0, 'Rejected. It is the smallest change and forgoes the type checking that a port of this size most benefits from, in a codebase whose typed tool contract is the thing being preserved. The host''s own examples are TypeScript, so this would also diverge from v2 idiom for no gain.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191T12NJ3HZPJR96222A1MQ', '01M191RRP9GTJY53WP9RCDNW9X', 'Inherit the data model unchanged', 1, 'The port''s risk is concentrated entirely at the host boundary, and changing anything beneath it would mix two kinds of failure in one release — a registration bug and a schema bug looking identical from the outside. Holding the model constant also means the corpus, the dump and the guard''s byte-comparison all keep working as evidence that the port is correct.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191T6Y7JS3YN2J7SFRW7FQ9', '01M191RRP9GTJY53WP9RCDNW9X', 'Revisit the model while porting', 0, 'Rejected. A port is the moment every accumulated reservation about a schema asks to be addressed, and taking any of them turns a mechanical change with a byte-comparable outcome into a redesign with none. Anything worth changing beneath the boundary is worth its own decision afterwards.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TAJW0QWP3AVAMRZ83PA9', '01M191RY452PMYKB35R7NDD60M', 'Register from the package with prefixed IDs', 1, 'One install, one version, and an upgrade that replaces everything atomically. The `dpm-` prefix is the cheap defence against a flat last-source-wins namespace, where a generic ID like `review` or `status` is silently overridden by whatever registers after it — a failure that presents as a skill behaving oddly rather than as a collision.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TCM2PBNEVGX0R64K96G1', '01M191RY452PMYKB35R7NDD60M', 'Users copy skill directories into the project', 0, 'Rejected. It puts twenty-three directories under the user''s control with no version attached, so an upgrade becomes a merge the user performs, partial upgrades are the normal state, and the question of which version of a skill is running has no answer.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TEBSPSTD9H29NYFPFGTX', '01M191RY452PMYKB35R7NDD60M', 'Register from the package with unprefixed IDs', 0, 'Rejected. It reads better in the catalog and loses to any other source that registers a skill of the same name. The cost of the prefix is cosmetic; the cost of the collision is a skill that silently is not the one that was installed.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TNBTD0FY7R1S92SQN7V4', '01M191S0HPM9P3PXXJGRH3M34K', 'Skill-first, with explicit commands as a named contingency', 1, 'The host advertises any skill carrying a description to the model and lists it in the slash catalog, so skill-first is the path the platform already provides and needs no machinery. Naming FR11 as the contingency inside this decision is what keeps the fallback attached to the risk rather than to somebody''s memory.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TTK0J0G7D8EXCBZ4BZBD', '01M191S0HPM9P3PXXJGRH3M34K', 'Reproduce slash ergonomics as the primary path', 0, 'Rejected as the primary path, and retained as FR11. It preserves the precision that existing users have muscle memory for, but it builds a parallel invocation surface that the host does not need and that has to be maintained against a beta command API. Building it first would also mean never learning whether the catalog was sufficient.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TVR928NZE24MF6CCYRYF', '01M191S1ZQYSAY12930K9A3HNC', 'Compute registrations before the transform, dispose on cleanup', 1, 'The host replays transforms on reload, so a transform that reads mutable state observes something different on the replay than it did on the first pass — a bug that appears only after an edit and looks like flakiness. Computing the server command, skill list and command list up front makes replay identical by construction rather than by care.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191TXWQTKQN3Q377PQNEKH3', '01M191S1ZQYSAY12930K9A3HNC', 'Compute registrations lazily inside the transform', 0, 'Rejected. It is the natural way to write the code and the reason the failure is worth deciding against in advance: it works on first load, survives testing, and diverges only on reload — which is exactly the path a developer exercises most and a test suite exercises least.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191V5K3EBQ7R2X4V20EV388', '01M191S3JWSJVCT8FC6YHPS3AR', 'A registration-time profile against one server and one database', 1, 'Only the model-facing surface needs to vary, so only it should. Selecting a different skill set and a trimmed tool advertisement at registration keeps the schema, projection, dump and guard byte-identical across profiles — which is what lets a corpus planned under one continue under the other with no migration. The boundary includes tool refusal text, because a refusal is read by the model and acted on, which is the whole test of being model-facing.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191V7ZXTKA0TJJZQ168YFBP', '01M191S3JWSJVCT8FC6YHPS3AR', 'A parallel repository for constrained models', 0, 'Rejected. It would fork the invariant part of the system — schema, identity, projection, dump, guard — in order to vary the variable part, and the two copies would then have to be kept byte-identical by discipline rather than by construction. It also splits the corpus, so a project could not move between them.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M191VA43N30R0GA8EPY65CT8', '01M191S3JWSJVCT8FC6YHPS3AR', 'A profile whose boundary stops at skill prose and tool schemas', 0, 'Rejected, and this is the correction the review produced. Drawing the boundary above refusal text makes the decision internally inconsistent the moment a profile wants to rewrite an error message, and leaves the deferred lite specification inheriting a constraint it cannot satisfy without reopening this decision.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BRZS0G3PHK32197NEHC1P6', '01M1BRZF6RZET0X87F8HBD1VWM', 'Served by the MCP server', 1, 'A typed tool returns the named shared document; each body opens with a tool call instead of a path read. It is the only route whose answer is the same on both hosts, because a tool call crosses the boundary ADR 01-02 already established as host-agnostic. It depends on no permission fact: the server reads its own package in its own process, which it is already doing for everything else. Its failure is loud — a failed tool call returns an error the session sees — where a denied file read returns nothing and the skill proceeds without its conventions, which is the omission FR4 exists to prevent. And it closes a defect already open: under v2 the substituted absolute path is auto-rejected as `external_directory`, recorded on retro 04, so the conventions are not being read on the supported host today either. Twenty-four references to two files, one line each, and `resolveSupportingPaths` is removed rather than joined by a second mechanism.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BRZWGFB13QT7E1ZYB3GH8W', '01M1BRZF6RZET0X87F8HBD1VWM', 'Resolve from the skill''s own location', 0, 'Keep it a file read and rewrite the reference so the model resolves it from the `location` the host hands it. This is the pattern OpenCode''s own documentation recommends — it does not expand `@` references, and tells authors to instruct the model to read referenced files with its own tool — so the mechanism is sound and the body still names a real path a human can follow. What it cannot answer from here is whether either host permits a read of a path outside the project. v2 does not: `permission requested: external_directory (…/shared/*); auto-rejecting`. v1''s behaviour is unestablished. So this route costs a probe now and a per-host permission entry in the install instructions afterwards, and it leaves the v2 rejection open rather than closing it.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BRZZZ4XK5EG8Q94DCJF9EB', '01M1BRZF6RZET0X87F8HBD1VWM', 'Materialise resolved copies into plugin storage', 0, 'The plugin writes resolved bodies into storage it owns and points discovery there — closest in spirit to what the v2 registrar does today. It creates a second copy of all twenty-three bodies that can disagree with the first, moves each skill''s `location` off the installed package against FR3, and makes registration a thing that writes to disk, which the v2 entry today explicitly does not do. It also does not escape the underlying problem: plugin storage is outside the project too, so the same permission question applies.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS03B90PR42Y3ESWEAP71C', '01M1BRZF6RZET0X87F8HBD1VWM', 'Append the conventions to the host''s instructions', 0, 'v1''s `config` hook can append a path to `Config.instructions`, which is documented, glob-capable and the route OpenCode''s own documentation names first. It fails on two counts. It injects fifteen kilobytes into every session whether a dpm skill is running or not, so every user pays for the conventions on every turn to serve the runs that need them. And v2 exposes no established equivalent, so it would be a v1-only mechanism — a per-host fork of the thing that is supposed to be shared, against NFR1.', 3);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS05JBS9HAEFXMPX3J3382', '01M1BRZF6RZET0X87F8HBD1VWM', 'Inline the conventions into every body', 0, 'Fifteen kilobytes copied into each of twenty-three bodies, with no mechanism at all and therefore nothing to break. Spec 01 named and rejected this as its fallback, and it is recorded here so the decision shows what it was weighed against rather than what it happened to pick. Twenty-three copies of one document is twenty-three places for it to drift, and nothing would notice.', 4);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS26WGGF460ZW7HMM6DBX2', '01M1BS1PKT28DGEWHFDZE889PT', 'One entry, detection in a tested predicate', 1, 'The package exports one entry. It asks the context which host it is — v2 carries `mcp.transform` and `skill.transform`, v1 carries neither and takes a `config` hook — and hands off to one of two registrars that share the server command and the skill list computed before either runs, which is ADR 01-07 unchanged. The user installs the same way on both hosts and chooses nothing, which is FR1. The weakness is that the detection is a shape test on an object neither host promises to keep stable; the answer is to confine it to one named predicate with its own test and a control that fails when both branches would match or neither would, so a host change breaks a test rather than silently taking the wrong path.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS29MXR5W745EBTSYTHPP5', '01M1BS1PKT28DGEWHFDZE889PT', 'Two exported entries, selected by each host''s loading convention', 0, 'Export one registrar per host and let each host pick up the one it knows about. Attractive because nothing has to guess. It rests on a fact nobody here has established — how v1 treats a plugin module exporting more than one function, and whether it would call both — and getting that wrong means the v2 registrar runs under v1, or both run, with no obvious symptom. It also splits the install instructions, since each host would name a different entry.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS2D0ZY93N6C519RBD44VP', '01M1BS1PKT28DGEWHFDZE889PT', 'Two published packages', 0, 'A package per host, sharing the core by dependency. Unambiguous at load time and wrong everywhere else: two release trains, two version numbers, two guard symlink stories, and a shared core that has to be published to be consumed — which reintroduces the npm publication FR1 of spec 01 deliberately defers.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS2HRTPDZ1Y11AHBW1WD96', '01M1BS1S883B15Q557G93HBFNS', 'Use it, fenced and alarmed', 1, 'One module sets `Config.skills.paths`, carrying a comment that says plainly it is undocumented and what to do when it stops working, and registration then checks that the path took — that the host actually holds dpm''s skills — refusing loudly rather than leaving the user with a plugin that connected its server and advertised nothing. The check is the whole point: a configuration key the host normalises away is accepted in silence, and the symptom is twenty-three skills quietly absent, which reads as dpm being broken rather than as the host having moved.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS2MTD2VPQ8MF0GRS6JS7D', '01M1BS1S883B15Q557G93HBFNS', 'Copy into a documented discovery root', 0, 'The six documented roots are all under the project or the user''s home. Using one means copying twenty-three directories out of the package and keeping them in step with every upgrade — which ENVX3 prohibits for the project roots and which reintroduces, for the home roots, exactly the copy-and-drift problem ADR 01-05 exists to prevent. It would also put skills where the user''s other tooling can edit them, so the package and the installed copy could disagree with nothing to notice.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS2QNYVFH139N7XFA1MSM5', '01M1BS1S883B15Q557G93HBFNS', 'Wait for OpenCode to document it', 0, 'Raise it upstream and defer v1 support until the key is in the schema. Correct in principle and indefinite in practice: the reason v1 matters is that v2 cannot reach the models this project is developed against, so deferring is choosing to keep dpm unusable for an unbounded period on the strength of a documentation preference. Raising it upstream is worth doing anyway, and does not have to gate the work.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS31G1896W6TVBRE805SFH', '01M1BS1W0Z2W3APKKB2XQJRVDV', 'Rename directories and front-matter names to dpm-*', 1, '`skills/spec/SKILL.md` with `name: spec` becomes `skills/dpm-spec/SKILL.md` with `name: dpm-spec`, twenty-three times, and the v2 registrar stops prepending `dpm-` to a name that now carries it — so the v2 id and the v1 name are the same string. Both halves are required: OpenCode''s documentation says the front-matter name must match the directory containing `SKILL.md`, so this is not twenty-three front-matter edits, it is twenty-three directory renames as well, and every path constant in the suite moves with them.

What makes it worth that is that nothing else keeps one set of bodies true on both hosts. dpm''s names are `spec`, `do`, `review`, `status`, `publish`, `clean` — as generic as names get, and v1 lets the later registration win with a log line nobody reads. Leaving them unprefixed means the skill is `dpm-spec` under v2 and `spec` under v1, so every cross-reference between bodies would have to name both forms, the invocation prose would be host-conditional, and the permission rule would differ per host. The prefix carried by the skill itself collapses all of that to one identity.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS36BKR6S19RCQHDH5Z462', '01M1BS1W0Z2W3APKKB2XQJRVDV', 'Leave the names, add a presence check', 0, 'Keep `name: spec` and have the v1 registrar verify after registration that all twenty-three skills are present and resolve to locations inside dpm''s own package, failing loudly when one has been displaced. This satisfies FR5''s "not silent" at a fraction of the cost, and it is the cheaper answer to the narrow question. It does not answer the wider one: the skill still has two names, so the bodies cannot describe their own invocation without branching on the host, and FR7''s permission rule stays host-specific. It also detects a collision rather than preventing one, and the user''s remedy would be to rename somebody else''s skill.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS398ZN2J316DVS8Y2VV2P', '01M1BS1W0Z2W3APKKB2XQJRVDV', 'Leave the names and document the risk', 0, 'Change nothing and put a paragraph in the README. Recorded because it is the zero-cost option and because it is what happens by default if nobody decides. It fails FR5 on its own terms — a displacement stays silent — and it is the option most likely to be discovered by a user whose own `review` skill quietly replaced dpm''s mid-run.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS3DEJNSSBS9K830P65J3S', '01M1BS1XJ6GP8VN4D8PQAGXXZM', 'npm alias in devDependencies', 1, '`"@opencode-ai/plugin-v1": "npm:@opencode-ai/plugin@1.18.25"` beside the existing beta pin, with the v1 registrar importing types from the alias. Both registrars are then checked against the real published types of the host they target, which is the entire value of taking the SDK at all. It stays in `devDependencies`, both imports remain type-only, and `dependencies` stays empty — NFR2 holds without a special case.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS3GVS1JSED1HPD0H467VT', '01M1BS1XJ6GP8VN4D8PQAGXXZM', 'Hand-declare the v1 types locally', 0, 'Write a small local declaration for the handful of v1 shapes dpm touches. No second install, and full control. It is also a second reading of the host, maintained by hand, which is the failure retro 02 recorded six times in a single epic — four separate readings of the import graph, only one of them correct. A hand-written type that drifts from the host does not fail; it type-checks, and the mismatch surfaces at runtime on a user''s machine.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M1BS3JRHYWT7KWVK5Z0ZJF36', '01M1BS1XJ6GP8VN4D8PQAGXXZM', 'Type-check against v2 only', 0, 'Keep one SDK and write the v1 registrar structurally, unchecked. The cheapest thing to set up and the one that forfeits the check on the half of the code that is new and least understood, which is the opposite of where the type checking should be concentrated.', 2);
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SAM6Y0TNQFMCKVP5PYXG', 'cost', 'Ongoing rather than up-front: every fix worth having in both places is applied twice, indefinitely.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SAM6Y0TNQFMCKVP5PYXG', 'reversibility', 'Low. Once the two codebases diverge, extracting a shared core later means reconciling two histories rather than one. Accepted knowingly — divergence is the point.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SFSCA29S5JW00CYRJPXY', 'complexity', 'A child process per session that native tools would not need, plus its startup and connection failure modes.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SFSCA29S5JW00CYRJPXY', 'reversibility', 'High. The plugin is the seam, so migrating to native tools later changes registration and leaves skills and database untouched. This is why the decision is safe to take on incomplete information about v2.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SR8NV7XB6DK4BYNT3VT6', 'complexity', 'Shifted rather than removed: no build pipeline, but a permanent syntax restriction and an import-extension discipline that every file must observe and CI must police.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191SR8NV7XB6DK4BYNT3VT6', 'reversibility', 'Moderate. Adding a build step later is mechanical; lowering the Node floor afterwards is not, because code written against 24 spreads.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191T12NJ3HZPJR96222A1MQ', 'reversibility', 'High, and deliberately deferred rather than closed. Any change beneath the boundary can be made after the port, against a system whose behaviour is known good.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191TAJW0QWP3AVAMRZ83PA9', 'reversibility', 'Low for the IDs specifically. Renaming a skill ID after release breaks anything that invokes it by name, so the prefix is effectively permanent from the first publish.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191TNBTD0FY7R1S92SQN7V4', 'cost', 'Borne by existing users rather than by the build: muscle memory for the old triggers stops working, and the replacement is less precise until FR11 is funded.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191TNBTD0FY7R1S92SQN7V4', 'reversibility', 'High. FR11 adds explicit commands alongside the catalog without withdrawing anything, so the contingency is additive rather than a reversal.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191TVR928NZE24MF6CCYRYF', 'complexity', 'Negligible, and lower than the alternative: computing up front is fewer moving parts than reasoning about what a replay observes.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191V5K3EBQ7R2X4V20EV388', 'cost', 'Near zero now — the skill and command lists are already computed before registration under the idempotency decision, so the seam is a parameter on work already being done.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M191V5K3EBQ7R2X4V20EV388', 'reversibility', 'High. Nothing behind the seam is built in this iteration, so the profile mechanism can be widened, narrowed or removed while the deferred specification is still unwritten.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZS0G3PHK32197NEHC1P6', 'complexity', 'Lowest of the five. One mechanism serving both hosts, no per-host branch, no permission story, no second copy. The only thing added is a tool in a package that already has 183 of them.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZS0G3PHK32197NEHC1P6', 'cost', 'Twenty-four one-line edits across twenty-three bodies, one new tool, and the deletion of `resolveSupportingPaths` and its tests. Net removal of code. The recurring cost is one tool result per skill run — the same context a file read would have cost.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZS0G3PHK32197NEHC1P6', 'legibility to a human reader', 'The weakest axis for this option, and the reason it is not free. A body that says "call a tool for your conventions" is one indirection further from someone who opens `SKILL.md` in an editor and wants to follow the reference. Mitigated by the tool naming the document and the document still sitting in the package, but not eliminated.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZS0G3PHK32197NEHC1P6', 'reversibility', 'High. The shared files stay in the package unchanged; reverting means putting the path back in twenty-four lines. Nothing is migrated and no user state depends on it.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZWGFB13QT7E1ZYB3GH8W', 'complexity', 'Low in the code and high in the contract. Nothing complicated is written, but the thing that makes it work lives in the user''s permission configuration, which is the one place dpm cannot test and cannot fix.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZWGFB13QT7E1ZYB3GH8W', 'cost', 'Cheapest to write and the most expensive to be sure of: a probe against v1 before it can be chosen, then a permission entry in the install instructions for each host, then the v2 rejection still to close separately.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZWGFB13QT7E1ZYB3GH8W', 'failure mode', 'Silent. A denied read returns nothing and the skill carries on without its conventions, indistinguishable from a skill that had none. This is the decisive axis and it is the one FR4 was written against.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZZZ4XK5EG8Q94DCJF9EB', 'complexity', 'Highest of the five. Registration acquires a side effect on disk, `location` stops meaning the installed package, and the copy and the original can disagree without anything noticing.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZZZ4XK5EG8Q94DCJF9EB', 'cost', 'A materialisation step at registration, a storage location to own, and a staleness question to answer on every plugin upgrade.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BRZZZ4XK5EG8Q94DCJF9EB', 'reversibility', 'Moderate. Reverting means deleting materialised trees on every machine that ever ran it, which is the kind of cleanup that gets half done.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS03B90PR42Y3ESWEAP71C', 'cost', 'Almost nothing to build, and fifteen kilobytes of context on every turn of every session for every user, whether dpm is being used or not.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS03B90PR42Y3ESWEAP71C', 'host parity', 'Fails outright. Documented on v1, with no established v2 equivalent, so it forks the shared surface along the host boundary — which is what NFR1 forbids.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS05JBS9HAEFXMPX3J3382', 'cost', 'Fifteen kilobytes times twenty-three bodies, paid in the package and again in every session that loads a skill.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS05JBS9HAEFXMPX3J3382', 'maintainability', 'Twenty-three copies of one document, each free to drift, with no check that could tell. It is the option with no mechanism, and therefore the option with no way to be wrong loudly.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS26WGGF460ZW7HMM6DBX2', 'cost', 'One predicate, one branch, and a second registrar module. The install instructions stay identical for both hosts, which is where most of the saving is.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS26WGGF460ZW7HMM6DBX2', 'failure mode', 'The risk is a host changing shape so that both branches match or neither does. The control in the predicate''s test is what converts that from a silent wrong path into a failing build.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS29MXR5W745EBTSYTHPP5', 'cost', 'Low to write, and it costs a probe first: how v1 loads a module exporting more than one plugin function is unestablished, and the decision cannot be made without it.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS29MXR5W745EBTSYTHPP5', 'failure mode', 'Both registrars running under one host, or the wrong one running, with no obvious symptom — the server would still connect and the skills would still appear.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS2D0ZY93N6C519RBD44VP', 'cost', 'Highest by a wide margin: two release trains, two version numbers, two guard stories, and a shared core that must be published to be consumed.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS2HRTPDZ1Y11AHBW1WD96', 'cost', 'One module and one check. The recurring cost is watching an undocumented key across v1 point releases, which the check makes visible rather than free.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS2HRTPDZ1Y11AHBW1WD96', 'reversibility', 'High, and deliberately so: confining it to one module means that if OpenCode replaces the key, one file changes.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS2MTD2VPQ8MF0GRS6JS7D', 'cost', 'A copy step, an upgrade-sync problem, and a prohibition to relax. ENVX3 forbids the project roots outright.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS2QNYVFH139N7XFA1MSM5', 'cost', 'Nothing to build and an unbounded wait, during which dpm stays unusable against the models this project is developed with. That is the cost, and it is the largest one here.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS31G1896W6TVBRE805SFH', 'complexity', 'Large but flat. It is one edit repeated, with no branching and no new mechanism, and it removes the id-prefixing step rather than adding to it. A rename''s blast radius is every predicate that filters on the old name, which retro 01 recorded as the thing the narrow rewrite misses.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS31G1896W6TVBRE805SFH', 'cost', 'The largest single change in this specification: twenty-three directory renames, twenty-three front-matter edits, the id derivation in `src/plugin/skills.ts`, the corpus test''s twenty-three-name transcription, every cross-reference between bodies, the README, and every path constant in the suite that names a skill directory.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS31G1896W6TVBRE805SFH', 'reversibility', 'Low once released. The skill names are what a user types and what their permission rules match, so reverting breaks configurations that were written against the new names.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS36BKR6S19RCQHDH5Z462', 'cost', 'A check and a README paragraph, and then a permanent second identity: host-conditional invocation prose in twenty-three bodies and a per-host permission rule.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS36BKR6S19RCQHDH5Z462', 'failure mode', 'Loud, which is what FR5 asks for — but the remedy it offers the user is to rename somebody else''s skill, because dpm has claimed a generic name and will not give it up.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS398ZN2J316DVS8Y2VV2P', 'failure mode', 'Silent displacement mid-run, which is the outcome FR5 names and forbids.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS3DEJNSSBS9K830P65J3S', 'cost', 'One manifest line and one import specifier. Both SDKs stay in `devDependencies` and neither reaches a user''s install.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS3DEJNSSBS9K830P65J3S', 'reversibility', 'High. Removing the alias removes the check; nothing at runtime depends on it, because both imports are erased before anything is evaluated.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS3GVS1JSED1HPD0H467VT', 'failure mode', 'A hand-written type that has drifted from the host does not fail the build — it passes it, and the mismatch surfaces at runtime on a user''s machine.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M1BS3JRHYWT7KWVK5Z0ZJF36', 'cost', 'Nothing to set up, and it forfeits type checking on the newest and least understood half of the code.');
INSERT INTO "quick" ("document_id", "document_kind", "closed_at") VALUES ('01M1HFRMWHFBPVC0KMT7CBXXC6', 'quick', '2026-09-02T16:55:00.000Z');
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M1HFRT2M8N8KRAJN72GYX118', '01M1HFRMWHFBPVC0KMT7CBXXC6', 'A story''s `**Blocked by**` line names the ends that hold it up — the edges where the story is the *target* — so the rendered epic agrees with `readiness.ts`''s stated contract that an edge reads source-blocks-target. [integration]', 1, '`templates.test.js` — "a story''s Blocked by line agrees with the readiness query". The oracle is `list_story ready: true`, not a second walk of `dependency`: every story in the corpus is pending, so ready is exactly "nothing holds it". Driven red first, where story 1 rendered `Story 2` while the query called it ready.', 0);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M1HFRW5VGZE0T6QJDX9ARWAJ', '01M1HFRMWHFBPVC0KMT7CBXXC6', 'A story blocked by a whole epic renders that epic''s identifier under `**Blocked by**`. The source-keyed reading could never show it, so this is a second defect the same fix closes rather than a restatement of the first. [unit]', 1, '`templates.test.js` — "a story blocked by a whole epic names that epic". Red first: the pairing has no `source_story_id` to be found by, so the source-keyed read returned the sibling edge instead and rendered `Story 2`.', 1);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M1HFRXRRB0C3SEGWM9DE9D8N', '01M1HFRMWHFBPVC0KMT7CBXXC6', 'must NOT: no story''s `**Blocked by**` line names something that story blocks. Control — the check is driven against the pre-fix renderer and must report the inverted names before it is trusted to report none. [integration]', 1, '`templates.test.js` — "must NOT — a story names what it blocks under **Blocked by**". Split into a test of its own precisely so it executes: as a second assertion on the cross-epic test it was shadowed by that test''s first failure, and a must-NOT nothing ran is not a control. Red first, reporting `01-01 Story 1` on the blocking story''s own file.', 2);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191H7HSQA83WM93W0J944HF', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR1', 'functional', 'must', NULL, NULL, 'Single-command install. `opencode2 plugin add github:ninthspace/opencode-dpm` — optionally with `#<ref>` to pin a release — yields a working DPM: the MCP server registered and connected, all skills advertised, and nothing further for the user to copy into the project.', 0, '2026-08-30T21:58:00.000Z', '5abff7bdf91c56f6f61a0c8c6ccf5136cf6c0ddeea173a0027092996d736c9bc');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HA9AJ98W4FGB37DC3P1Y', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR2', 'functional', 'must', NULL, NULL, 'The MCP server is the tool surface. The plugin registers the bundled server via `ctx.mcp.transform`, setting a local server entry whose command runs the packaged executable. Skills continue to write exclusively through typed MCP tools: no skill contains SQL and nothing parses prose. Tool behaviour and schemas carry over from v0.7.0 unchanged.', 1, '2026-08-31T06:14:46.000Z', '6adb82ee2b2396f763a6d1fde1665f39c86ba146b08c9151210fe0028177cf5b');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HD4T54B4H7JB9M9Z8DF9', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR3', 'functional', 'must', NULL, NULL, 'Skills registered from the package. All twenty-three skills port and are registered via `ctx.skill.transform`, with `location` pointing into the installed package so directory-based skills keep their supporting files. Skill prose is revised wherever it names host mechanics: tool names take v2''s effective naming, and the invocation story replaces Claude Code''s slash-command triggers.', 2, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HEEXRNX7Z6Z46ATS49FW', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR4', 'functional', 'must', NULL, NULL, 'Persistence parity. Fresh-clone restore from `.dpm/dpm.sql`, deterministic dump on publish, the empty-database restore asymmetry, read-only server mode, and the Node-floor refusal all carry over with their existing behaviour.', 3, '2026-08-31T06:14:46.000Z', 'eff6415c31fc2cd057422558fc1209a54e25fd737f91d7286584233d384e1621');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HM8EE473JDD426R9FQRE', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR5', 'functional', 'must', NULL, NULL, 'The five executables port. `dpm-mcp`, `dpm-guard`, `dpm-publish`, `dpm-import` and `dpm-merge` keep their responsibilities, become TypeScript sources, and remain runnable directly with `node` and no loader.', 4, '2026-08-30T14:25:00Z', '136f3186995022ec49eb5e3f996bd7012f5782dacfadffbb8d906395453429c9');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HPCXWPEDVYD8ZCRGZNJQ', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR6', 'functional', 'must', NULL, NULL, 'Pre-commit guard unchanged in kind. It remains a git hook that regenerates and compares, fixes nothing, and refuses with the four-case explanation. The install instruction is updated for where OpenCode places plugin packages, and the missing-symlink warning on server start carries over.', 5, '2026-08-30T20:00:00Z', '916996b326e14efdc3266c7cb7e18d60f9d1e622ca5ca6d3d3994964805ef193');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HRH294FESBRF5JK3CZGQ', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR7', 'functional', 'must', NULL, NULL, 'Test suite ports. The `node --test` suite — 133 test files at v0.7.0, including the corpus snapshot tests — runs against the TypeScript sources in CI, under plain `node` with no loader.', 6, '2026-08-30T14:25:00Z', '6dc2f2e7ec96dd4330e92a10c50071cdbc72026417d08badc045099c11b66b2f');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HSY4Z56KCR1HWSDVA1VE', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR8', 'functional', 'should', NULL, NULL, 'Permission-aware behaviour. Skills behave correctly under `ask` and `deny` rules for the `skill` action, and the README documents the recommended permission entries.', 7, '2026-08-30T20:00:00Z', 'ae450272d806f7f3b1fc27350052451b1f8c4664e487efb771ca560401337137');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191HZ1QER0TFPZ2DQQ4NYJX', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR9', 'functional', 'should', NULL, NULL, 'Session scratch via plugin storage. Anything that was per-session scratch keyed by an environment variable in Claude Code uses `ctx.storage` where a database session row is not already the answer. No transient files land in the project tree.', 8, '2026-08-30T20:00:00Z', '84a9dbcf1cdda7a9265315499566f21debdc11c76b1810dbb205464106fa272f');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191J1W9E36VGT6DC7ZVKP94', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR10', 'functional', 'should', NULL, NULL, 'README for a v2 audience. Install, first run, guard symlink, and "when the guard refuses" are rewritten for `opencode2`. The CPM MIGRATION.md does not carry over.', 9, '2026-08-30T20:00:00Z', '542fd90ad02adde3121df5d740d982e7b741f13ebb9fc9ebb10084651c9237b7');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191J2Z2EH3B2G3FVJ63EQ3N', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR11', 'functional', 'could', NULL, NULL, 'Slash-catalog commands. Register `ctx.command.transform` entries that prompt the session into a named skill, restoring something close to the previous slash-command ergonomics if skill-as-slash proves insufficient in practice.', 10, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191J4PJ7KEV66YH1B1QC4BM', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR12', 'functional', 'could', NULL, NULL, 'HTTP skill catalog. Publish the skills as a v2 HTTP catalog for teams that want the skills without the plugin. Low value while the tools require the plugin anyway.', 11, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191JCC04JEVXVWFMS1V9RMJ', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR13', 'functional', 'wont', 'deferred', NULL, 'Lite profile for constrained local open-weight models — a reduced model-facing surface selected by plugin option, with skills rewritten as terse imperative checklists, tool descriptions and schemas hard-trimmed, conventions inlined rather than read at startup, a measured context budget, and single-sentence tool refusals that name the field and state the correction. Deferred to a specification of its own: it is an iteration on what this specification builds rather than part of it. The architectural seam that makes it selectable at registration time is decided here and is not deferred.', 12, '2026-08-30T16:05:00Z', 'f908b5b8fb2edb81e8b8c1a4ac232225628c510cf28fb27335722c45c7f16ea8');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191JEBN8VV1VNPNKYKFC5H9', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR14', 'functional', 'wont', 'out_of_scope', NULL, 'Claude Code compatibility in this repository. The marketplace repository remains the home of the Claude Code plugin.', 13, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191JFTXHMWR1WZGPAJACE1Q', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR15', 'functional', 'wont', 'out_of_scope', NULL, 'OpenCode v1 support.', 14, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191JHFA19EW0XW6SZK17WN1', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR16', 'functional', 'wont', 'out_of_scope', NULL, 'CPM migration tooling. Anyone on CPM migrates via the existing Claude Code dpm first.', 15, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191JJS4KT4HTH40S8YVHNPJ', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'FR17', 'functional', 'wont', 'out_of_scope', NULL, 'CLI and TUI plugin work — `cli.json` plugins, theme integration, keybinding integration.', 16, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191KQV386EDYK9Z9H12D2N5', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'NFR1', 'non_functional', 'must', NULL, NULL, 'Zero runtime dependencies. `node:sqlite` stays; no native modules and no install-time compilation. The only package the plugin needs is `@opencode-ai/plugin`, and it is needed for its types alone — `Plugin.define` is the identity function `define(plugin) { return plugin }`, so importing it at runtime would pull eight transitive packages in to call a function that returns its argument. The SDK is therefore taken as a type-only import, sits under `devDependencies`, and `dependencies` stays empty.', 17, '2026-08-31T06:14:46.000Z', 'dd019f4219948b5c4e4fe00c4a9917b087baf7df5cfc2d17ce14d02fc1464b77');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191KSQTS6M41QHYTJX0WAM6', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'NFR2', 'non_functional', 'must', NULL, NULL, 'No build step. TypeScript throughout, restricted to erasable syntax so Node runs the sources directly. `tsc --noEmit` is a type check in CI, not a compile, and no build artefact is produced or published.', 18, '2026-08-30T14:25:00Z', 'ce3ddd69dac05402cf115fe75a6390195f8400d73fc64ea3d2aebe2ffe83a569');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191KW1TEYZR0S56SCE5GZDC', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'NFR3', 'non_functional', 'must', NULL, NULL, 'Beta churn tolerance. The plugin pins `@opencode-ai/plugin@beta` and the README states plainly that OpenCode v2 is beta and that entrypoints may move under it. API breakage is expected maintenance rather than a defect.', 19, '2026-08-30T20:00:00Z', '683b3df150438e8f11a588d46f71ca1bae9ccf95aece44156de56aa5d7bb4575');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191KY76N9B04YVJK69YMCGW', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'NFR4', 'non_functional', 'must', NULL, NULL, 'Determinism. Dump output, projection output, and ULID and number allocation behaviour remain byte-stable across the port. The guard''s regenerate-and-compare depends on it.', 20, '2026-08-30T14:25:00Z', 'c8c2578bdfc428fa6a7247208fb7e26bdb55d6237c012503c0aa889d9b1b88dd');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191M0X2D61B6XGBY2SPA0MA', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'NFR5', 'non_functional', 'must', NULL, NULL, 'Import-extension discipline. Every internal import specifier carries an explicit `.ts` extension, as native type-stripping requires specifiers to resolve exactly as written, and `tsconfig.json` sets `allowImportingTsExtensions` so the type check accepts them. Enforced by a dedicated CI sweep that imports every module under `src/` and `bin/` with plain `node`. The sweep exists separately from the test suite because the suite only exercises modules some test imports, and a bad specifier in a module nothing imports would otherwise reach a release unobserved.', 21, '2026-08-31T06:14:46.000Z', '1aff7a4917e15736ea9a09f7ebd0241bae7252518059343407af70a766ae4762');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191NVWV9CP15DT44439W9NZ', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR1', 'environmental_requirement', 'must', NULL, NULL, 'Development: Node 24 or later on the contributor''s machine. Checkable by `node --version` reporting 24.0.0 or above. This is the floor that buys native type-stripping and a stable `node:sqlite` in one move.', 22, '2026-08-30T14:25:00Z', 'c67b5c733dfed337c343c1de6beb4185b3066a93886eed67b78f667396ac23bb');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191NX38ANZRH042J1KQ91S0', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR2', 'environmental_requirement', 'must', NULL, NULL, 'Development: `node --test` is the test runner. Checkable by the test script being `node --test` and no third-party test runner appearing in `devDependencies`.', 23, '2026-08-30T14:25:00Z', 'afcd109c687684e89175e5ac81ae5ca48318882aa56170d0dee3636bbefc38a6');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191NZRB4NJ2A07WES55GFTT', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR3', 'environmental_requirement', 'must', NULL, NULL, 'Development: TypeScript available for type checking. Checkable by `tsc --noEmit` running from `devDependencies` and exiting zero.', 24, '2026-08-30T14:25:00Z', '984802fea2c0e65c98c40e85f6f99163030228199e9f81be19e03074e4cab795');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191P15MPZRFA7HH2Z91K8XP', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR4', 'environmental_requirement', 'must', NULL, NULL, 'Development: an OpenCode v2 beta CLI on the contributor''s machine. Checkable by `opencode2 --version` reporting a `0.0.0-beta-*` build matching the `beta` dist-tag of `@opencode-ai/plugin`, so the CLI and the SDK the plugin is typed against are the same build. Without it neither the effective tool naming nor the skill-registration behaviour can be verified, and both gate the skill port.', 25, '2026-08-30T16:05:00Z', '391410948c8da36eb0637c2f191884434ea2dfc23b5b196c0d0d628b76dfee2f');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191P6ZQ9026CAE9NPHA7VXK', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR5', 'environmental_requirement', 'must', NULL, NULL, 'Development: a scratch OpenCode project to register into. Checkable by installing the plugin into a throwaway project and observing its MCP server reach connected state with the skills advertised.', 26, '2026-08-30T16:05:00Z', 'ae329e06fe9eaf4ab8ea46bca643373d94d68fac3770378f9f2fbb6acca2059a');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191P8TH87TEYAPJ9V0F4P3S', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR6', 'environmental_requirement', 'must', NULL, NULL, 'Development: git with hook support. Checkable by `git --version` reporting 2.9 or above and a hook installed at `.git/hooks/pre-commit` firing on commit.', 27, '2026-08-30T20:00:00Z', '43722ab406fe1e5a65cdc43dce3f61a20504ea44137991b068b9e829430aa0e2');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PB5ZT101VW751N9HTCER', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR7', 'environmental_requirement', 'must', NULL, NULL, 'Development: CI that runs the suite. Checkable by a CI job running the full `node --test` suite on Node 24 under plain `node`, plus the type check and the module sweep, on every push.', 28, '2026-08-30T14:25:00Z', 'fab4cb19a95696463d234604bc754a7a8343babc8722a1989b757d5a422a71c5');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PDECZ9F46H7Q6J8XNSDP', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX1', 'environmental_restriction', 'must', NULL, NULL, 'Development: native compilation must not be required. Checkable by a clean install completing with no node-gyp invocation, no C or C++ toolchain and no Python present.', 29, '2026-08-31T06:14:46.000Z', 'e03c626015d42d746c7ab04c5e58e2bf1e392d647c74a0fe9aa62f5b7ae745b3');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PJJS5APQC7DK4P73CR1G', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX2', 'environmental_restriction', 'must', NULL, NULL, 'Development: a loader or transpiler must not be required. Checkable by the test command and each executable''s invocation passing no `--loader`, no `--import`, and no transpiler flag — the sources run on what Node 24 does by default.', 30, '2026-08-30T14:25:00Z', 'b129020857834dd62d559f4231d9e7780b9fbeb16931e73909f876d706b42d17');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PMSEVEWV2QZPCTQB0KQ7', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX3', 'environmental_restriction', 'must', NULL, NULL, 'Development: Claude Code must not be required. Checkable by the full suite passing on a machine with no Claude Code installed and no `CLAUDE_`-prefixed environment variables set.', 31, '2026-08-30T14:25:00Z', 'eb45cf6525a725e53b56e47c9c5e62ae44d4b9887b9ab3a6d9748d4659586b33');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PQA3QF3YC847X5Y9CD4F', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR8', 'environmental_requirement', 'must', NULL, NULL, 'Production: Node 24 or later on the host running OpenCode. Checkable by the runtime the host invokes reporting 24.0.0 or above, and by each executable refusing with an explanatory message when it is below.', 32, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191PRJD860MEPCETCTG156D', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR9', 'environmental_requirement', 'must', NULL, NULL, 'Production: OpenCode v2 as the host application. Checkable by the plugin loading under a 2.x host and its MCP server, skills and any commands appearing in that host''s registries.', 33, '2026-08-30T16:05:00Z', '3adb8783618e0837c17b333f6b8ef472f7ce240fe49eb10a6492599f352a8eec');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191Q160A0AWMXH0WTD2P0GF', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR10', 'environmental_requirement', 'must', NULL, NULL, 'Production: a git repository in the user''s project. Checkable by the guard hook installing at the repository''s hook path and refusing a commit whose projection is stale.', 34, '2026-08-30T20:00:00Z', '9495255be0f86d80fec6422457de2d5f6a4a8309d8167d485dbc66a05e90f412');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191Q35NNXEWQK0HNQGBD5PY', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR11', 'environmental_requirement', 'must', NULL, NULL, 'Production: filesystem write access to `.dpm/` inside the project. Checkable by the database and the dump being created and rewritten there on a first run in a fresh project.', 35, '2026-08-31T06:14:46.000Z', '32f75edf13c857ec32272230260dea74e603021e2e15252e3c878155219e6163');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191Q578097ZDAS8SA8MGHY1', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX4', 'environmental_restriction', 'must', NULL, NULL, 'Production: network access must not be required at runtime. Checkable by a full plan-and-publish cycle completing with networking disabled.', 36, '2026-08-30T21:10:00.000Z', '420c6167c3e570d30746b1c4545c26c03095fb1912b329d8af1b383a8d5c759b');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191Q6FFNXB7AR19TRT6RCSE', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX5', 'environmental_restriction', 'must', NULL, NULL, 'Production: a database service must not be required. Checkable by persistence needing only files under `.dpm/`, with no port bound and no external service contacted.', 37, '2026-08-30T21:10:00.000Z', '7537ab201c340431c6a42c7667911d6fa1cadd9d4cc48b83603d015066b46023');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M191Q82N7NWEGDG30HYFKX8S', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVX6', 'environmental_restriction', 'must', NULL, NULL, 'Production: Claude Code artefacts must not be required. Checkable by the plugin running correctly in a project containing no `.claude/` directory and no CPM or dpm marketplace installation.', 38, '2026-08-30T21:10:00.000Z', 'fc4f77c0fc883907bd697ec4abc1e4fd8361db81ff75a8f06cb82050eff4547d');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M192BM6P7KCFK6EJBPF417RR', '01M191BE7MHM077FE9YM09B2ZK', 'spec', 'ENVR12', 'environmental_requirement', 'must', NULL, NULL, 'Development: a disposable isolated environment — a container or equivalent — that can be started with no language toolchain present and with networking disabled. Captured after the testing tags were assigned, because two integration criteria need it: the clean-install check under ENVX1 and the offline plan-and-publish cycle under ENVX4. Both are development tooling, so neither is a target claim; without this entry each would be satisfied by inspection rather than by running.', 39, '2026-08-30T14:25:00Z', '79663adcaa4c3da1e08bfb106060dbb58e2c3cffea89fa46ea66b88a6b35e9a4');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNA64G8R17416TT8JB50J3', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR1', 'functional', 'must', NULL, NULL, 'Registration under OpenCode v1. The package registers itself with a v1 host: the MCP server registered and connected, all twenty-three skills advertised, and nothing further for the user to copy into the project. A single documented install route, and the user does not choose a registrar — the one appropriate to the host runs for the host that loaded it.', 0, '2026-09-02T09:45:00Z', 'f21ef78b5f95158afd06d522d3010dc66125d7629f6e97c8d349026d1f007fa0');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNA8VH5EFC9KYCZJHZSSTG', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR2', 'functional', 'must', NULL, NULL, 'The MCP server remains the tool surface under v1. Registration goes through v1''s `config` hook, setting a local server entry whose command runs the packaged executable — the same `{type:"local", command, environment?}` shape the v2 registrar already builds. Tool names, schemas and behaviour are identical under both hosts, and no host-specific tool exists.', 1, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNABQBYGFEQY397MNZHK96', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR3', 'functional', 'must', NULL, NULL, 'Skills registered from the package, not copied. The package''s skills directory is made discoverable to the host by the `skills` configuration key the user sets at install, and each skill resolves with its `location` inside the installed package so directory-based skills keep their supporting files. ADR 01-05''s first half — registered rather than copied — holds unchanged under v1; only the mechanism that implements it differs. There is no v1 skills registrar: v1''s plugin `Hooks` has no skill member and its configuration layer strips the `plugins` key a second entry would have needed, so the mechanism is a documented configuration entry rather than code dpm runs.', 2, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAF4SK9RY6GEWY1B755T1', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR4', 'functional', 'must', NULL, NULL, 'Every skill''s conventions reference resolves under a host that reads skill bodies verbatim. All twenty-three bodies open by reading `dpm/shared/skill-conventions.md`. v1 reads `SKILL.md` off disk and the plugin never sees the text, so `resolveSupportingPaths` — the registration-time rewrite that makes this work under v2 — has nowhere to run. The requirement is satisfied when a real session reads the file, not when a path exists: the failure this guards against is an omission rather than an error, and an omission passes every check that only asks whether something is present.', 3, '2026-09-02T09:45:00Z', '18f06da223d3231a5f19381dc6d7cf6f5c5f63cedab00a71fdfec595b6f544f3');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAJDWSKAWRJ2SJMMX8KBH', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR5', 'functional', 'must', NULL, NULL, 'dpm''s skills survive v1''s flat name keyspace, and a collision is not silent. v1 keys skills on the front-matter `name`, logs `duplicate skill name`, and lets the later registration win. The `dpm-` id prefix that ADR 01-05 relies on under v2 has no effect there. Whatever replaces it must make a clash visible rather than quietly serving another source''s `review`, `status` or `do` in place of dpm''s.', 4, '2026-09-01T00:00:00Z', '22f69ef60ef6a8d351b921c1521b8e81617ae0e45e554072d84970097f0144d5');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAMK908YZGSX62CN3XYA8', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR6', 'functional', 'must', NULL, NULL, 'Both hosts documented. README install, first run, guard symlink and "when the guard refuses" cover v1 and v2, with the plugin-package location correct for each host rather than one location presented as the location.', 5, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAQEHN5PVRC0H8K2RBAGD', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR7', 'functional', 'should', NULL, NULL, 'Permission guidance matches what each host evaluates. v1''s permission engine evaluates the `skill` key against the front-matter `name` — which carries the `dpm-` prefix, so a `dpm-*` pattern matches every dpm skill and nothing else. The recommended entries are stated per host, against what that host actually matches on.', 6, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNASYFZ7EN67Z2DWJXEPR8', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR8', 'functional', 'should', NULL, NULL, 'Verified end to end under v1 against real models. A session starts a dpm skill by its documented invocation, the skill reads its conventions, a dpm tool writes a row, and the guard accepts the resulting commit. This is the walk spec 01''s three `[manual]` FR3 rows could not reach, and it is written as a requirement rather than left to the test approach because the port has twice been proved wrong by the act of installing it and using it.', 7, '2026-09-02T09:45:00Z', '83c8ca03e7a024d51f55380eb6ce94b4f445393d13e403437e530c4215c692c7');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAW4G7KNVE9ESSNE4ZD1V', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR9', 'functional', 'could', NULL, NULL, 'Explicit slash commands under v1. v1 carries a command surface, and registering named entries that prompt the session into a skill would restore something close to the pre-port ergonomics. Spec 01''s FR11 named this as the contingency under v2 and it was never needed there.', 8, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNAZ2769AGJZ7S35CEBCVC', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR10', 'functional', 'could', NULL, NULL, 'Argument passthrough. `$ARGUMENTS` was removed from all twenty-three bodies as a Claude Code slash-command mechanism the host filled before the model saw the text. If v1 supplies an equivalent, skills that took arguments could take them again — but only behind a form that degrades to nothing under v2, so that one set of bodies goes on serving both hosts.', 9, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNB0YXB119QCHF6CZWC6Y5', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR11', 'functional', 'wont', 'out_of_scope', NULL, 'Dropping v2. This is a second registrar, not a retarget; both hosts stay supported from one codebase.', 10, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNB2ZER8P6T4NGM2SARJWS', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR12', 'functional', 'wont', 'out_of_scope', NULL, 'mtplx''s provider and plugin configuration. It is the reason v1 matters and it is the user''s own setup; dpm neither supplies it nor documents it.', 11, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNB5YAJJT4EFWXA3MES4ZN', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR13', 'functional', 'wont', 'deferred', NULL, '`ralph`. Its withdrawal from registration is decided in principle and held on its existing record against epic 01-03, with a withdrawal radius of twelve assertions across eight test files. v1 restoring a slash-command surface does not reopen it here — the stop-hook contract it is built on was never shipped by any host.', 12, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BNB7Y87AADPMPYEA7D86C1', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'FR14', 'functional', 'wont', 'out_of_scope', NULL, 'v1''s remote skill registry, `config.skills.urls`. A distribution route rather than a host-support one, and one that would put the skills somewhere the guard and the MCP server cannot reach.', 13, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPMGZXZB58QP8GVR9M2MGG', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'NFR1', 'non_functional', 'must', NULL, NULL, 'One codebase, no per-host fork. Skill bodies, tool schemas, the MCP server, the guard and the database are shared verbatim between hosts, and host-specific code is confined to the registration layer — 427 of 15,867 lines at the point this specification was written. Checkable by the host-support change touching only that layer, and by no skill body and no tool module branching on which host is running.', 14, '2026-09-02T09:45:00Z', '65f4fa997929b569a3977fc8e233c0b0f46047d61d7991fe7af8080ac4ef914c');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPMMEE2N7EZ0219E8B842D', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'NFR2', 'non_functional', 'must', NULL, NULL, 'Zero runtime dependencies survives a second SDK. `dependencies` stays empty. Both host SDKs are needed for types alone and neither may reach a user''s install — a complication rather than a formality here, because v1 and v2 publish the same package name at different versions and the package manifest can hold one entry per name. Checkable by `dependencies` being `{}` after the work, and by the existing module sweep proving nothing under `src/` imports a package at runtime.', 15, '2026-09-02T09:45:00Z', '266c8e0d9de4d68db5513f1eec3106ae50748dab3577c79797dea70664981800');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPMQ9D1KJKY0VY1AZYM90N', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'NFR3', 'non_functional', 'must', NULL, NULL, 'The undocumented dependency is declared, isolated, and fails loudly. `Config.skills.paths` is absent from the published SDK types and from the live `opencode.ai/config.json` schema, so building on it is building on something OpenCode has not committed to. dpm may build on it, but from exactly one place, named as unsupported where a maintainer will read it, and with a check that fails when it stops working — because the failure mode of a configuration key the host silently normalises away is twenty-three skills quietly not registering, which reads to a user as dpm being broken rather than as the host having moved.', 16, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPMSYRRB26CR1ZXMC9RDVP', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'NFR4', 'non_functional', 'must', NULL, NULL, 'Host-independent artefacts. The same project worked under either host produces the same rows, the same dump and the same projection. Nothing written under `.dpm/` records or depends on which host wrote it, and the guard''s regenerate-and-compare cannot tell the difference. A project moved between hosts mid-epic notices nothing.', 17, '2026-09-02T09:45:00Z', 'acbc8204bb4c4218833ca88f233c9bffc06f33024eed3c037dc5a830a2acd5d2');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPMVC37ZS5Y48G0BBZZ8BV', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'NFR5', 'non_functional', 'must', NULL, NULL, 'No build step, unchanged. Erasable-syntax TypeScript run natively by Node. The second registrar adds no compile, no loader and no published artefact, and `tsc --noEmit` remains a type check rather than a build.', 18, '2026-09-02T09:45:00Z', 'a6f775aab430d7694cba21568573d58781fc2ac707f144f320e891123ceb5916');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPX4ZF8H7WRGFF4PBMX94Q', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVR1', 'environmental_requirement', 'must', NULL, NULL, 'Development: an OpenCode v1 CLI on the contributor''s machine, at a version matching the v1 SDK the plugin is typed against. Checkable by `opencode --version` reporting a 1.x build matching the version the v1 types are taken from — 1.18.25 at the time of writing — so that the CLI and the types the registrar is checked against are the same release.', 19, '2026-09-02T09:45:00Z', '1905c69ff6ce06eaeb8125cc3f21afb73f0795bd155813f5924d8bb32d2e8e8d');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPX8BFXTSJRXFTKV9P55B3', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVR2', 'environmental_requirement', 'must', NULL, NULL, 'Development: the OpenCode v2 beta CLI retained alongside the v1 one. Checkable by `opencode2 --version` reporting a `0.0.0-beta-*` build matching the v2 SDK. Spec 01''s ENVR4 required a v2 CLI; this entry changes it to a requirement for both at once, because parity across two hosts is the deliverable and a regression under v2 introduced while adding v1 is otherwise invisible on this machine.', 20, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXACEZ517SZJ400F2K0NB', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVR3', 'environmental_requirement', 'must', NULL, NULL, 'Development: a scratch project per host to register into. Checkable by installing the plugin into a throwaway project under each host and observing its MCP server reach connected state with the skills advertised.', 21, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXDWW9MQY456SB236G1GJ', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVR4', 'environmental_requirement', 'must', NULL, NULL, 'Development: a model provider the v1 host can reach and complete a turn against. Checkable by a v1 session completing a turn. Without this entry FR8''s end-to-end walk is unverifiable by anybody, and the specification would be one whose central claim can only be asserted. The configuration of that provider is the contributor''s own and is explicitly not dpm''s to supply — FR12 — but its availability is an environment condition and belongs here.', 22, '2026-09-02T09:45:00Z', '48284f9576ecd29cd8c4dca747964d55011a2e5e9d37964f74338b5826f02446');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXGHZJ57G96J8AW4E32N9', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVX1', 'environmental_restriction', 'must', NULL, NULL, 'Development: neither host CLI may be required to run the test suite. Checkable by the full `node --test` suite passing on a machine with neither `opencode` nor `opencode2` on `PATH`. The suite tests a package, not a host, and a suite that needs either binary is one CI cannot run and one a contributor cannot reproduce.', 23, '2026-09-02T09:45:00Z', 'e6a6a17038aec316b4d162f766372e45328d6c460d395a7e0539e22ed125d0fd');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXJKERWAVETZX2ZZ88E4H', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVR5', 'environmental_requirement', 'must', NULL, NULL, 'Production: OpenCode v1 (1.x) or OpenCode v2 as the host application. Checkable by the plugin loading under a 1.x host and its MCP server and skills appearing in that host''s registries. This is the entry that replaces spec 01''s ENVR9, which names v2 as the production host in the singular.', 24, '2026-09-02T09:45:00Z', '0ce615a78e9942e2a97f5a7a637694cea9da8bfb75f16d7365a151c1a6bc3f4a');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXNB0GNW8W9426QCEEGCK', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVX2', 'environmental_restriction', 'must', NULL, NULL, 'Production: a host hook that rewrites skill content must not be required. Checkable by a session reading the shared conventions file on a host that reads `SKILL.md` verbatim off disk and offers no content transform. v2 supplies such a hook and v1 does not, so a design that assumes one is a design that runs on one host.', 25, '2026-09-02T09:45:00Z', 'cf2d1fa25c3e5bf1b2d032e44cc7219f63de1d5792d8067fe0aeeeadbe5149d4');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXR5RNKBVJVV6CYKAHDYB', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVX3', 'environmental_restriction', 'must', NULL, NULL, 'Production: copying skill files into the user''s project tree must not be required. Checkable by a fresh project holding no skill files and no skills directory after install and a first run. Copying resolved bodies into the project is the easiest thing that would appear to work and it is the thing ADR 01-05 exists to prevent, so the prohibition is recorded rather than left to be remembered.', 26, '2026-09-02T09:45:00Z', '56306a28f3e51dee3585fe4a6b0a8b12798b5237098ef418ecff1c024dc7dc05');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M1BPXT221DSV0NFH1J7J9PFZ', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', 'ENVX4', 'environmental_restriction', 'must', NULL, NULL, 'Production: the plugin must not write to the user''s OpenCode configuration. Checkable by no write to those files being attributable to dpm across a plugin load — not by the files being byte-identical, because 1.18.25 inserts a `"$schema"` member into `opencode.json` on load and a byte comparison cannot tell that write from one of dpm''s. Registration is a description handed to the host, not an edit to the user''s file. The host''s own writes are excluded from this, whether they arrive on load or from `plugin add` writing to the global configuration: those are the host''s write and the user''s choice, not the plugin''s.', 27, NULL, NULL);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M192246A1T14WS7PA7AJCH0K', '01M191NVWV9CP15DT44439W9NZ', '`node --version` on the contributor''s machine reports 24.0.0 or above, and the repository''s `engines.node` field declares the same floor.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19225J1JXVAP79MBMA0T183', '01M191NX38ANZRH042J1KQ91S0', 'The package''s test script is `node --test`, and no third-party test runner appears in `devDependencies`.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19227AKDBP3C29P69X0TH0X', '01M191NZRB4NJ2A07WES55GFTT', '`tsc --noEmit` runs from `devDependencies` against the whole codebase and exits zero.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19228MGB8PMGWHYTS6YPRMV', '01M191P15MPZRFA7HH2Z91K8XP', '`opencode2 --version` on the contributor''s machine reports a 2.x beta release.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922A09E252N2CQMQ9SMD4T', '01M191P6ZQ9026CAE9NPHA7VXK', 'The plugin installs into a throwaway OpenCode project, its MCP server reaches connected state, and all skills appear as advertised.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922ENG2PVVQ419YY86BN7D', '01M191P8TH87TEYAPJ9V0F4P3S', '`git --version` reports 2.9 or above, and a hook installed at `.git/hooks/pre-commit` in a temporary repository fires on commit.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922GYEAKGMEN6EAQ3HVCA2', '01M191PB5ZT101VW751N9HTCER', 'A CI job runs the full `node --test` suite, the `tsc --noEmit` type check and the module sweep on Node 24 under plain `node`, on every push, and the run is observable in the repository''s CI history.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922K8JC4CFFPG16FB9J6G1', '01M191PDECZ9F46H7Q6J8XNSDP', 'A clean install in an environment with no C or C++ toolchain and no Python completes successfully, with no node-gyp invocation in its output.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922MT9794XEWTJMTDY5PF2', '01M191PJJS5APQC7DK4P73CR1G', 'The test script and every executable''s documented invocation pass no `--loader`, no `--import` and no transpiler flag.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922PEEJNZVKJP0DPGSTB66', '01M191PMSEVEWV2QZPCTQB0KQ7', 'The full suite passes in an environment with no Claude Code installed and no `CLAUDE_`-prefixed environment variables set.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922XCHTTN964ST62BAE1N4', '01M191PQA3QF3YC847X5Y9CD4F', 'Each of the five executables, run on a runtime below 24, refuses with a message naming the required version rather than failing on a syntax or module error.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1922Z0BKDKRC5W3SH12E3G5', '01M191PQA3QF3YC847X5Y9CD4F', 'The runtime the host invokes on the user''s machine reports 24.0.0 or above.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19231DBSRE71FM1SD4361E2', '01M191PRJD860MEPCETCTG156D', 'Under an OpenCode 2.x host, the plugin loads and its MCP server, skills and any registered commands appear in that host''s registries.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19232Q0V6TMAXY81QEG65KA', '01M191Q160A0AWMXH0WTD2P0GF', 'In a temporary git repository, the guard hook installs at the repository''s hook path and refuses a commit whose projection is stale, with the explanatory output intact.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M192342BFNFCTP48W8P12VDX', '01M191Q35NNXEWQK0HNQGBD5PY', 'On a first run in a fresh project, the database and the dump are created under `.dpm/` and rewritten on a subsequent publish.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19238Y8VAAX3H7RCV2VD7VC', '01M191Q578097ZDAS8SA8MGHY1', 'A full plan-and-publish cycle completes with networking disabled, making no outbound connection attempt.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1923AYW2TW1SZS41SPC6DXT', '01M191Q6FFNXB7AR19TRT6RCSE', 'Persistence uses only files under `.dpm/`: no port is bound and no external service is contacted during a full plan-and-publish cycle.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1923C647H6H6P77TS87TA6T', '01M191Q82N7NWEGDG30HYFKX8S', 'The plugin runs correctly in a project containing no `.claude/` directory and no CPM or dpm marketplace installation.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925DT3YT68WN4S3JQDDNJ4', '01M191H7HSQA83WM93W0J944HF', 'Installing into a fresh project by the documented command leaves the MCP server connected and all twenty-three skills advertised, with no further user action.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925F1TPJ2C7N5KG77VA7KW', '01M191H7HSQA83WM93W0J944HF', 'The published package''s manifest declares the plugin entry, and the server command path resolves to an existing file inside the installed package tree.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925GD8WSWBFTKDZ77RBNN9', '01M191H7HSQA83WM93W0J944HF', 'Installation requires the user to copy a file, hand-edit project configuration, or run a post-install step.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925HKB321KH5GYKJ18GV66', '01M191HA9AJ98W4FGB37DC3P1Y', 'The advertised tool set and every tool schema match v0.7.0''s, compared against a stored snapshot of the tool surface.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925JVD30WDE2BKC1R89PTW', '01M191HA9AJ98W4FGB37DC3P1Y', 'A skill body contains a SQL statement — a `SELECT`, `INSERT`, `UPDATE` or `DELETE` paired with `FROM`, `INTO` or `SET`.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925T21XWNQKCQ5JQZGC1BQ', '01M191HD4T54B4H7JB9M9Z8DF9', 'All twenty-three skills appear in the host''s skill registry after install, every ID carrying the `dpm-` prefix.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925VBZ6HVHW7YM10DXTYAB', '01M191HD4T54B4H7JB9M9Z8DF9', 'The registration list computed before the transform contains twenty-three entries and every ID is `dpm-` prefixed.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925WPSKPEKZBZAVPG1NX8D', '01M191HD4T54B4H7JB9M9Z8DF9', 'A registered skill''s supporting files resolve from the package location, so a skill that reads the shared conventions file at startup finds it. This is the milestone-2 go/no-go: a negative answer forces inlining and is recorded as an explicit decision.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1925XZDNX00KC0PWVFJEGME', '01M191HD4T54B4H7JB9M9Z8DF9', 'A skill body names a Claude Code mechanism — `mcp__plugin_`, `/dpm:`, `CLAUDE_PLUGIN_ROOT`, or `.claude/`.', 'must_not', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19278XJ1ZWAT7QQNB8VD6JR', '01M191HEEXRNX7Z6Z46ATS49FW', 'A fresh-clone restore from `.dpm/dpm.sql` reproduces the database, and a subsequent dump is byte-identical to the committed one.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927AEBCMMWTF79VZQFPXB5', '01M191HEEXRNX7Z6Z46ATS49FW', 'Restore into an empty database and restore into a populated one behave as v0.7.0 defines, with the asymmetry between them preserved.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927C3832Y44PDDT8JQ8J9K', '01M191HEEXRNX7Z6Z46ATS49FW', 'Read-only server mode refuses every write tool and serves every read tool.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927DC6H3PS5J5MATDRFN4J', '01M191HEEXRNX7Z6Z46ATS49FW', 'A restore silently discards rows that were present in the dump.', 'must_not', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927EV2XCDE12PA52XKRN7N', '01M191HM8EE473JDD426R9FQRE', 'Each of the five executables runs directly with `node` and no loader flag, and performs the responsibility it held at v0.7.0.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927G9AQ5PAX0VQT9FK6MP3', '01M191HM8EE473JDD426R9FQRE', 'An executable requires a build artefact to exist before it will run.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927NXWG758PB5ZNTB9Q17E', '01M191HPCXWPEDVYD8ZCRGZNJQ', 'The guard regenerates the projection, compares it against what is on disk, and exits non-zero on a mismatch.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927Q557CC98VE5APC7APRC', '01M191HPCXWPEDVYD8ZCRGZNJQ', 'Each of the four refusal cases produces its own explanation, distinguishable from the other three.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927RDCFNTMVQDZYPFEEYP3', '01M191HPCXWPEDVYD8ZCRGZNJQ', 'Starting the server in a repository with no hook symlink installed emits the missing-symlink warning.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927T84YMHSHFV0DN9N3Q2Y', '01M191HPCXWPEDVYD8ZCRGZNJQ', 'The guard writes to the working tree or repairs any discrepancy it finds.', 'must_not', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927VYB8KATR3STWQWW8CVH', '01M191HRH294FESBRF5JK3CZGQ', 'The full suite runs under plain `node` on Node 24 and passes, corpus snapshot tests included.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1927XETSA96M06G0PH38Z2E', '01M191HRH294FESBRF5JK3CZGQ', 'A test requires a loader, a transpiler, or a network connection in order to pass.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19297C1B7YAYKMV3F472SA2', '01M191KQV386EDYK9Z9H12D2N5', 'The package''s `dependencies` contains exactly one entry, `@opencode-ai/plugin`.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M19298WQ6K8ENQ4X07PQ02VQ', '01M191KQV386EDYK9Z9H12D2N5', 'A `.node` binary, or a compile step, appears anywhere in the production install tree.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929A5N05WT13S002XG3XC6', '01M191KSQTS6M41QHYTJX0WAM6', '`tsc --noEmit` exits zero over the whole codebase, and the package declares no build script.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929BMS4WBHN3EPSFSHHT0W', '01M191KSQTS6M41QHYTJX0WAM6', 'The published package contains a build output directory, or its `files` or `exports` fields point at one.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929CVZSKJ4KZNVQNGK8SXE', '01M191KW1TEYZR0S56SCE5GZDC', 'The plugin dependency is pinned to the `beta` tag, and the README states that OpenCode v2 is beta and that entrypoints may move under it.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929J0Z830C1F7QXNV485DM', '01M191KY76N9B04YVJK69YMCGW', 'Dumping the same database twice produces byte-identical output, and regenerating the projection twice produces byte-identical output.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929KF472K1WF0P4CYJQAQV', '01M191KY76N9B04YVJK69YMCGW', 'The corpus snapshot tests pass against the ported sources without their fixtures being regenerated.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929MPFZ4JFNJJMT5E6M2QW', '01M191KY76N9B04YVJK69YMCGW', 'Dump or projection output varies with wall-clock time, filesystem ordering, or hash-map iteration order.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929PVBYPW0G5CR8FD4W9G0', '01M191M0X2D61B6XGBY2SPA0MA', 'The module sweep imports every file under `src/` and `bin/` with plain `node`, and every import resolves.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929R8861QF6H07975FPBBE', '01M191M0X2D61B6XGBY2SPA0MA', '`tsconfig.json` sets `allowImportingTsExtensions`, and `tsc --noEmit` accepts the extensioned specifiers.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1929SQZSYT7BZ4PV5947ZM9', '01M191M0X2D61B6XGBY2SPA0MA', 'Control: introducing a deliberately extension-less internal import makes the module sweep fail. Without this the sweep can pass because it is not looking, which is the blind spot NFR5 exists to close.', 'control', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M192BT25GGS2K5ECP77AEQ1E', '01M192BM6P7KCFK6EJBPF417RR', 'A disposable isolated environment is available in CI, and both the clean-install check and the networking-disabled cycle run inside it rather than being asserted by inspection.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRHFHNWAP4A21748ZKTG4', '01M1BNA64G8R17416TT8JB50J3', 'Given a stub host context, the v1 registrar produces a configuration whose `mcp.dpm` command array is the one the shared server builder returns, and whose `skills.paths` contains the package''s own skills directory.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRK03TENYWMVE0QY34WD7', '01M1BNA64G8R17416TT8JB50J3', 'With the package installed into a fresh v1 project, the host holds the dpm MCP server in a connected state and all twenty-three skills, each resolving to a location inside the installed package. Automation is infeasible: it needs a running host, and ENVX1 keeps host binaries out of the suite.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRMZHDNEY8TAYZTT43H2P', '01M1BNA64G8R17416TT8JB50J3', 'Registration requires the user to name a host, choose between entries, or set an option. Control: a planted second required argument on the exported entry, which the check reports by name rather than by count.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRPGFK3SMT9WXG3S8MHQV', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'The local-server entry the v1 registrar builds is identical to the one the v2 registrar builds — the same command array and the same environment — because both are the return value of one function rather than two constructions that agree today.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRRBR601A2R6WKPQ2EKSX', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'Any tool is advertised under one host and not the other. Control: a planted host-conditional tool, which the check names rather than merely counting a mismatch.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRT3C07NXAV903P8C0KE7', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'Under a running v1 host, a dpm tool call writes a row and that row is readable from `.dpm/dpm.db` afterwards.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRVP18JKNWV1872RDYTMB', '01M1BNABQBYGFEQY397MNZHK96', 'Discovery over the directory the v1 registrar contributes finds exactly twenty-three `SKILL.md` files, all resolving under the installed package.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRX86JC30691M212YNVS0', '01M1BNABQBYGFEQY397MNZHK96', 'Under a running v1 host, the skill listing returns dpm''s skills with `location` inside the installed package.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVRYQB389CPQF38VHGJVAN', '01M1BNABQBYGFEQY397MNZHK96', 'Registration writes anything into the user''s project tree. Control: the project tree hashed before and after a plugin load, with a planted write proving the comparison fires rather than an unchanged hash proving nothing was watching.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVTPVGSNDTT8DJ43W6VDEM', '01M1BNAF4SK9RY6GEWY1B755T1', 'Every one of the twenty-three bodies reaches the shared conventions through the tool, and none names a filesystem path to `shared/`. Control: a planted body carrying the old path form, which the check reports by name rather than by count.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVTSV0K8S8DKGXMHTH86BS', '01M1BNAF4SK9RY6GEWY1B755T1', 'The tool returns the byte content of the package''s `shared/skill-conventions.md` for the name it is given, and refuses an unknown name rather than returning empty. The refusal is the property FR4 turns on: a mechanism that answers an unknown name with nothing reproduces, inside the tool boundary, exactly the silent omission the file read produced outside it.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVTVF4V773PVZDWAZ1G1DZ', '01M1BNAF4SK9RY6GEWY1B755T1', 'In a real v1 session, a dpm skill starts and performs a step that only the conventions prescribe — a session row created with `skill` and `phase` set, per the shared Session Startup procedure — observable in the database rather than inferred from the transcript. "The model read its conventions" is not directly observable, so the criterion asks for a consequence nothing else produces.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVTX369JX8B68D9FXWS68Y', '01M1BNAF4SK9RY6GEWY1B755T1', 'A second copy of either shared document exists anywhere in the tree. Control: a planted duplicate, reported by path.', 'must_not', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVV0ED7H62XTR6RQHXMN4W', '01M1BNAJDWSKAWRJ2SJMMX8KBH', 'Every skill''s front-matter `name` equals the name of the directory containing its `SKILL.md`, and begins with `dpm-`. Controls: a planted skill whose name and directory disagree, and one carrying no prefix — each reported by name.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVV1WFSHQQ3A4JV6Y12QT1', '01M1BNAJDWSKAWRJ2SJMMX8KBH', 'The skill id the v2 registrar produces equals the front-matter name exactly — no prefix added and none doubled. Control: a planted unprefixed name, which the check reports rather than silently repairing.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BVV3K76CXQT5TX82S6H0CH', '01M1BNAJDWSKAWRJ2SJMMX8KBH', 'Under a running v1 host, all twenty-three dpm names appear in the skill listing distinct from every other registered skill, and the host log carries no `duplicate skill name` line for any of them. Control: a scratch skill deliberately named `dpm-status`, confirming the log does report a duplicate — so a clean log means the observation was capable of firing rather than that nothing was watching.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWD808X9MESYBMTY88309V', '01M1BNAMK908YZGSX62CN3XYA8', 'For each of install, first run, guard symlink and "when the guard refuses", the README gives both the v1 and the v2 form. Control: a planted section carrying only one host''s form, reported by heading.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWD9KJ6KGYQ3036AE19MJG', '01M1BNAMK908YZGSX62CN3XYA8', 'Following the README''s v1 instructions verbatim produces a working install, a guard symlink that resolves, and a refusal on a deliberately stale projection.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWDB5YPE452Y3G9EEZBW94', '01M1BNAMK908YZGSX62CN3XYA8', 'The README names one host''s binary where the sentence is true of either. Control: a planted `opencode2` in a host-neutral sentence, reported by line.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWDCQK5SZ1G9CG7Y7BJ3G7', '01M1BNAQEHN5PVRC0H8K2RBAGD', 'The permission rule the README recommends matches all twenty-three skill identities on both hosts — one `dpm-*` form once the skills carry their own prefix. Control: a planted rule matching none, reported as a failure rather than passing over an empty match set, which is the shape that passes by doing nothing.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWDETHBQ2XKYYWVJS32YRJ', '01M1BNAQEHN5PVRC0H8K2RBAGD', 'Under a running v1 host, a `deny` rule written as the README recommends blocks a dpm skill, and the same session without the rule runs it. The two directions are each other''s control: a block that would have happened anyway proves nothing.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWDGPWZMTXA7HD5J086NJR', '01M1BNASYFZ7EN67Z2DWJXEPR8', 'A v1 session starts a dpm skill by the documented invocation, the skill obtains its conventions, a dpm tool writes a row, and `dpm-guard` accepts the resulting commit. The evidence is the row, the regenerated projection and the commit. Deliberately one criterion rather than four: splitting it would let three pass while the thing it exists to prove — that the whole path works in one session — did not happen.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWF8CSKJ0ZMQ5HSSPBP7K5', '01M1BPMGZXZB58QP8GVR9M2MGG', 'The host-detection predicate''s identifier appears only in the registration layer and its own test. Control: a planted use elsewhere under `src/`, reported by file.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFA18ZW23W9CM5CCZ57EP', '01M1BPMGZXZB58QP8GVR9M2MGG', 'Both registrars are given the same skill list and the same server entry, each from one call rather than from two constructions that happen to agree.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFBF7EJG5309NNZC3CB7H', '01M1BPMGZXZB58QP8GVR9M2MGG', 'A skill body names a host. Control: a planted host name in a body, reported by skill.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFCZHKT9QYEP8YZRY3MJ6', '01M1BPMMEE2N7EZ0219E8B842D', '`dependencies` is empty and both SDK entries sit under `devDependencies`. Control: a planted runtime entry.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFEG6ZSZR4PW77T4P5TWE', '01M1BPMMEE2N7EZ0219E8B842D', 'Nothing under `src/` imports a package at runtime — the existing module sweep, extended to recognise the aliased SDK specifier. Control: a planted value import of either SDK, which the sweep names.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFG54MRF8ZRSFAFG06FHS', '01M1BPMQ9D1KJKY0VY1AZYM90N', '`skills.paths` is written from exactly one module, and that module carries a marker naming the key as undocumented and saying what to do when it stops working. Control: a planted second write site, reported by file.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFHYFKQCB2NQN7354E177', '01M1BPMQ9D1KJKY0VY1AZYM90N', 'The post-registration check reports failure when given a host configuration that does not hold dpm''s skills path, and passes when it does. The passing direction is the control: a check that always fails would satisfy the first half alone.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFKGPCEPP3GCQ63N96QVX', '01M1BPMSYRRB26CR1ZXMC9RDVP', 'Nothing in the dump or the projection records which host wrote it. Control: a planted host identifier in a row, found by the sweep.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFN4KR0D5AHJQDACFFVDV', '01M1BPMSYRRB26CR1ZXMC9RDVP', 'A database written through the v1 server produces a byte-identical dump when read through the v2 server, and the guard accepts both. Reachable without models on either host — it needs the two server processes, not two sessions, so it is not blocked on the thing this specification exists to fix.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFPNF77PX61PA4S1M094C', '01M1BPMVC37ZS5Y48G0BBZZ8BV', 'No build script and no published artefact; `tsc --noEmit` remains a check. Control: a planted build script.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M1BWFR7JACAW1C91CMJF4TZ2', '01M1BPMVC37ZS5Y48G0BBZZ8BV', 'Any invocation passes a loader or transpiler flag. Control: a planted `--import`, reported by the invocation that carries it.', 'must_not', 1);
