INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1951ZDWW46AVDM0W2HYWW9K', '01M1951DJH04XXS5ZN0Z3GBDSB', 'The filesystem location where OpenCode places a git-installed plugin package is confirmed against a real install and recorded as a section on this epic.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19520QN2C18CNA5H7Y4V9F0', '01M1951DJH04XXS5ZN0Z3GBDSB', 'The documented symlink instruction, followed in a fresh project, resolves to an existing file.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M195222V3F5N030BXG5G96Z5', '01M1951FE5F4G1PTK9BF5WNW7Q', 'Anything that was per-session scratch keyed by an environment variable uses `ctx.storage` where a database session row is not already the answer.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19523F9VFN8WFH9F47189DE', '01M1951FE5F4G1PTK9BF5WNW7Q', 'On a first run in a fresh project, the database and the dump are created under `.dpm/` and rewritten on a subsequent publish.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19524XRETPQRAV06SN1DYN1', '01M1951FE5F4G1PTK9BF5WNW7Q', 'A transient file lands in the project tree.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19526A8XJ1WYP8ZFANDN47R', '01M1951GSMQ3JY8MJAX204ZEY0', 'Install, first run, guard symlink, and "when the guard refuses" are rewritten for `opencode2`.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19527MPE5AZ88PQKQDDBRZY', '01M1951GSMQ3JY8MJAX204ZEY0', 'Every command the README gives runs as written in a fresh project.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1952916VPEHNVF62ZRPZJT9', '01M1951GSMQ3JY8MJAX204ZEY0', 'The README states that OpenCode v2 is beta and that entrypoints may move under it.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1952AA2WKSFC1BYDMBX56B9', '01M1951GSMQ3JY8MJAX204ZEY0', 'The repository contains a CPM `MIGRATION.md`.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1952BP02Z605Y9J2DDTJN2A', '01M1951J6PTV1WPNCCCF58J3TD', 'Skills behave correctly under `ask` and `deny` rules for the `skill` action.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1952D3979C6V01MTJ0QQAVA', '01M1951J6PTV1WPNCCCF58J3TD', 'The README documents the recommended permission entries.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1952EHHSB6MCM5HC6WVF27C', '01M1951J6PTV1WPNCCCF58J3TD', 'A skill denied by a `deny` rule for the `skill` action performs its work anyway through another route.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1957YVRSJYH47D6Q7T8P9D4', '01M1957QGCTGTTW0VJP7JHDG74', 'The package is distributable at version 0.1.0: the manifest declares 0.1.0, nothing marks it private, and `npm pack` produces the tarball an installer builds from this repository.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19580542A1BB87XVK0Z4PAN', '01M1957QGCTGTTW0VJP7JHDG74', 'The packed tarball contains the plugin entry, all twenty-three skill directories, `shared/`, and the five executables.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19581F5PNNE5NRYM3WB9AP0', '01M1957QGCTGTTW0VJP7JHDG74', 'The packed tarball omits a file a registered skill needs at runtime.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19582S6ABCHQ857XN2YRTYV', '01M1957RXJ674PDNMB53CEGBT1', 'Installing into a fresh project by the documented command — `opencode2 plugin add github:ninthspace/opencode-dpm` — leaves the MCP server connected and all twenty-three skills advertised, with no further user action.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1958422X7G47SMQ39TMXG8P', '01M1957RXJ674PDNMB53CEGBT1', 'One skill runs end to end from the installed package, in a clean environment.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19585MT85VK08FVW7BECR4C', '01M1957RXJ674PDNMB53CEGBT1', 'The install is verified from the working tree rather than from the package the installer built.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19586ZSAR67SXCYCPMJ809T', '01M1957TECZSEEFTKG9DNVT7S7', 'A full plan-and-publish cycle completes with networking disabled, making no outbound connection attempt.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M19588P1E29S4HC9CCKXZBW0', '01M1957TECZSEEFTKG9DNVT7S7', 'Persistence uses only files under `.dpm/`: no port is bound and no external service is contacted during a full plan-and-publish cycle.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1958A0KK1F5NKHD6FV933JV', '01M1957TECZSEEFTKG9DNVT7S7', 'The plugin runs correctly in a project containing no `.claude/` directory and no CPM or dpm marketplace installation.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9A66TKMR13JW2R441CH7W', '01M1C99TTCYG60Z4A27SBXH9CR', '`@opencode-ai/plugin-v1` resolves to `@opencode-ai/plugin@1.18.25` through an npm alias declared in `devDependencies`, and `tsc --noEmit` exits zero with both SDK versions in the type graph.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9A7TTS4RK3XYKPV82WE0K', '01M1C99TTCYG60Z4A27SBXH9CR', '`dependencies` in `package.json` is empty and both SDK entries sit under `devDependencies`. Control: a planted runtime entry fails the check.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9AAV7NAPCS4MV7PXGTJN8', '01M1C99TTCYG60Z4A27SBXH9CR', 'Nothing under `src/` imports a package at runtime, with the module sweep extended to recognise the aliased specifier as an SDK import. Control: a planted value import of either SDK fails the sweep.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9ACB97XGYQHNYSAAC5KRW', '01M1C99TTCYG60Z4A27SBXH9CR', 'Any invocation passes a loader flag, a transpiler flag, or any other runtime argument beyond the entry path. Control: a planted `--import` in a package script fails the check.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9ADWFZAXYM4NRMJJN1EYQ', '01M1C99TTCYG60Z4A27SBXH9CR', 'There is no build script and no compiled artefact; `tsc --noEmit` remains a check rather than a step that produces output. Control: a planted build script fails the check.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9B3FR9TCS7YFXNV02SN1Q', '01M1C99W8SPDHE5RTF76GGVRKP', 'A single named predicate classifies the host from the plugin context it is given, and the exported entry hands off to one of two registrars on its result.', 'must', 0, '2026-08-31T21:20:00.000Z', 'Overtaken by Chris''s decision on 2026-08-31 to target OpenCode v1 alone ("given we can''t currently work with a v2 of opencode, let''s concentrate on v1"), taken at an explicit gate that named this story''s verified work as the cost. With one host there is no host to classify: `src/plugin/host.ts` and its `hostOf` predicate are deleted, and so is the two-registrar dispatch this criterion measured. What replaced it is two modules, one per v1 protocol, both loaded unconditionally — nothing classifies anything at run time. The criterion is not merely unmet, it names a mechanism that no longer exists.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9B51VC1D91R1ZRCPGS88X', '01M1C99W8SPDHE5RTF76GGVRKP', 'The predicate''s test fails when given a context both branches would match and when given one neither would, so a classification that has stopped discriminating is caught rather than silently defaulting.', 'control', 1, '2026-08-31T21:20:00.000Z', 'Superseded with 01M1C9B3FR9TCS7YFXNV02SN1Q, whose predicate it was the control on. A control on a classification that no longer happens has nothing to be a control on.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9B6J1PTGJ3P0P6XKCX68Z', '01M1C99W8SPDHE5RTF76GGVRKP', 'Both registrars are given the same skill list and the same server entry, each computed by one call, rather than by two constructions that happen to agree.', 'must', 2, '2026-08-31T21:20:00.000Z', 'Superseded by the v1-only retarget. There are no registrars to give one thing to: dpm now ships two plugin modules, one per v1 protocol, and they register different things — the tools module a server entry, the skills module a skill list. The claim worth keeping from this criterion is narrower and survives in `src/plugin/registration.ts`, where both modules resolve the same package root through `packageRoot`, and it is verified by story 3''s criterion on the registered entry being the one `localServer` builds.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9B81E9XT1ND7TT6ZGFWC5', '01M1C99W8SPDHE5RTF76GGVRKP', 'The predicate''s identifier appears only in the registration layer and its own test. Control: a planted use elsewhere under `src/` fails the check.', 'must', 3, '2026-08-31T21:20:00.000Z', 'Superseded with the predicate it names. `hostOf` is deleted, so a rule about where its identifier may appear has no subject. NFR1''s underlying claim — that host-specific code is confined to the registration layer — is not lost: it moves to story 3''s must-NOT sweep, which reads the same corpus with the same planted control and now carries the NFR1 binding.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9B9G2ZS5ND1ZC3SBBHFM2', '01M1C99W8SPDHE5RTF76GGVRKP', 'Registration requires the user to name a host, choose between entry points, or set an option. Control: a planted second required argument on the exported entry fails the check.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9C16CF1HKKNM8TZ304BF9', '01M1C99XSZNHY02M8TZRVMPWQT', 'Given a stub v1 plugin context, the v1 registrar''s `config` hook sets `mcp.dpm` to a local-server entry whose command runs the packaged executable.', 'must', 0, '2026-08-31T19:03:00.000Z', 'The mechanism is unreachable from the shape v2 requires. Probes against opencode 1.18.25: v1''s `config` hook arrives on the `Hooks` returned by the callable `server` export, and v1 only reaches that export when the module has NO default export — with a default present it calls `default.setup(context)` and ignores `server` entirely. v2 requires a default export object and never calls a callable one. Chris chose skills-without-tools under v1 on 2026-08-31, reaffirming it after FR2''s text was put in front of him. Replaced by the criterion that the v1 registrar registers no server and says so loudly.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9C2JVQ99QVD2B54G1FQFB', '01M1C99XSZNHY02M8TZRVMPWQT', 'The local-server entry the v1 registrar builds is identical to the one the v2 registrar builds — same command array, same environment.', 'must', 1, '2026-08-31T19:03:00.000Z', 'Superseded with 01M1C9C16CF1HKKNM8TZ304BF9: with no server registered under v1 there is no second local-server entry to compare against. The claim it was protecting — that one computation feeds both registrars rather than two that happen to agree — is not lost; story 2''s `registrationInputs` makes it structural, and criterion 01M1C9B6J1PTGJ3P0P6XKCX68Z verifies it.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9C433GZSJYWA47WA53SNF', '01M1C99XSZNHY02M8TZRVMPWQT', 'Any tool is advertised under one host and not the other. Control: a planted host-conditional tool registration fails the check.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9C5HZP5N85P74YW23HXGK', '01M1C99XSZNHY02M8TZRVMPWQT', 'The plugin writes to the user''s OpenCode configuration file. Control: the configuration files are hashed across a plugin load and compared, with a planted write proving the comparison fires. Amended by the spec 02 pivot of 2026-09-03: where the hashes differ, the difference is attributed before the criterion is judged. 1.18.25 inserts a `"$schema"` member into `opencode.json` on load, and a bare hash comparison reports the host''s own write as dpm''s — so the comparison locates a write and does not, on its own, say whose it was.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9CPMG8Q81F4YRHTF1A43X', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'The v1 registrar appends the package''s own skills directory to `config.skills.paths`, and discovery over that directory finds exactly twenty-three `SKILL.md` files, every one resolving to a path inside the installed package.', 'must', 0, '2026-08-31T21:45:00.000Z', '`config.skills.paths` is not the route, and does not need to be. Probing v1 1.18.25 found `skill.transform` on the object-route context, whose draft takes `{type:''embedded'', skill}` sources carrying the computed skill rather than a path to it — a typed, published API where `skills.paths` is absent from both the SDK types and the live schema. The replacement criterion measures the same outcome, twenty-three skills each resolving inside the installed package, against the mechanism actually used.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9CR08ZB1164JA14S99FEF', '01M1C99ZKVV6FGAB9QS4YA5JPJ', '`skills.paths` is written from exactly one module, and that module carries a marker naming the key as undocumented by OpenCode and saying what to do when it stops working. Control: a planted second write site fails the check.', 'must', 1, '2026-08-31T21:45:00.000Z', 'There is no undocumented key to fence. NFR3 required `config.skills.paths` to be written from exactly one module and marked as unsupported; the embedded-source route means it is written from none. The requirement''s premise dissolved rather than being satisfied, which is reported at the epic roll-up rather than claimed as coverage.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9CSDYS6MC1QEWMRNPCHGZ', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'The post-registration check reports failure when given a host configuration that does not hold dpm''s skills path, and passes when given one that does.', 'must', 2, '2026-08-31T21:45:00.000Z', 'The post-registration check existed because a configuration key the host silently normalises away registers nothing while appearing to work. `skill.transform` fails at the call instead: the draft''s `source` decodes what it is given and throws on a shape it does not accept, which is how the embedded variant was established in the first place. There is no silent-no-op failure mode left for a check to detect.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9CV9B0DERZSPT0EM397EM', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'Registration writes anything into the user''s project tree. Control: the project tree is hashed before and after a plugin load and compared, with a planted write proving the comparison fires.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9DF7A3F1VBR95AW7MR06A', '01M1C9A10T12G36GD9PC17DTYX', 'One plugin load under a stub v1 context produces a configuration holding both `mcp.dpm` and dpm''s `skills.paths` entry, built from the same computed inputs rather than from two independent constructions.', 'must', 0, '2026-08-31T23:00:00.000Z', 'Names `skills.paths`, which is not the route. v1 registers skills through `skill.transform`''s embedded sources, and the two registrations come from two modules rather than one load. Replaced by the criterion that asserts both entries resolving from one package root.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9DGTHEHZZ0BDT3XH4Z504', '01M1C9A10T12G36GD9PC17DTYX', 'The same exported entry loaded under a stub v2 context produces the v2 registrations and writes no `config` at all.', 'must', 1, '2026-08-31T23:00:00.000Z', 'Measures behaviour under a v2 context. v2 was dropped from this epic by explicit decision, so there is no second host to compare against. Replaced by the criterion that the registered MCP command is one a v1 host can actually spawn — the defect this story''s integration check found.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9NTWSFCSRTC5ZZ8JPER19', '01M1C9NH4G73B75EAPFTR1E46T', 'Each of the twenty-three skill directories is named `dpm-<skill>` and holds a `SKILL.md` whose front-matter `name` is that same string, so that a skill declares one identity in both places a reader looks for it and story 2 can take the registered name straight off disk.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9NWDR2ZMBTZYZKQY0YAGC', '01M1C9NH4G73B75EAPFTR1E46T', 'Every front-matter `name` matches `^[a-z0-9]+(-[a-z0-9]+)*$`. Control: a planted name carrying an underscore or a capital fails the check.', 'must', 1, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9NXXH96Y1NVCGBHR2R0KR', '01M1C9NH4G73B75EAPFTR1E46T', 'The rename changes only the directory name, the front-matter `name`, cross-references between bodies, and the code that indexes a skill by its directory name; the existing skill-body check passes unchanged over all twenty-three.', 'must', 2, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9NZKPVF6VZRS3GBTPGM1F', '01M1C9NH4G73B75EAPFTR1E46T', 'Two skills share a front-matter name. Control: a planted duplicate name fails the check.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P1H5WBA1PK784S500X4F', '01M1C9NJN1KWKMHZ6T6BV2VWWY', 'Registration registers each skill under the `name` its front matter carries, applying no prefix of its own at registration time.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P30R4MHSA34WCS59Z2JY', '01M1C9NJN1KWKMHZ6T6BV2VWWY', 'The registered name for each skill is the same string as before the change, so ADR 01-05''s namespace defence holds by a different route and with the same result.', 'must', 1, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P4FGEMJRPJ09TBDBP2ZG', '01M1C9NJN1KWKMHZ6T6BV2VWWY', '`ID_PREFIX` and any other registration-time prefixing constant is gone from `src/plugin/`. Control: a planted re-introduction fails the check.', 'must', 2, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P62HZJAAHF9GJ6QK5T8W', '01M1C9NM656AR8N6H2ESMCD6P6', '`tests/support/skills.js` yields the twenty-three prefixed names, every test file that reaches a skill through the helper passes untouched, and the files holding a hand-kept list of skill names are updated to the new ones.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P7HS7JNEJTZQ5W8G0N8D', '01M1C9NM656AR8N6H2ESMCD6P6', '`tests/corpus.test.js`''s transcribed name list holds the twenty-three prefixed names and still fails when the tree and the list disagree. Control: a planted extra skill directory fails it.', 'must', 1, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9P98GHR8C87049FQ41EP8', '01M1C9NM656AR8N6H2ESMCD6P6', 'No test is lost or skipped to the rename: every test file the suite shipped before this epic is still in the suite, still unskipped, and still declaring cases — read file by file rather than against a suite total. A passing count is not the measure: it reports the state of the working tree''s index as much as the suite''s, and a rename that has not been staged moves it without a test having been lost.', 'must', 2, NULL, NULL, '01M1BS1W0Z2W3APKKB2XQJRVDV');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9PAS3ZEX9AKKG0A7NQASM', '01M1C9NP5XWKJ06Y9X8512V9TR', 'After registration under v1, a check reports every dpm skill whose registered entry does not resolve to a path inside the installed package, naming each one.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9PC9XAWBE63YF67SD1QZB', '01M1C9NP5XWKJ06Y9X8512V9TR', 'The check fails when given a host registry in which another source has claimed one of dpm''s names, and passes when every dpm name resolves to dpm''s own directory.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9PDQPSJK3BG0VBTFV5DXR', '01M1C9NP5XWKJ06Y9X8512V9TR', 'dpm''s registration silently overwrites, or is silently overwritten by, another source''s skill of the same name. Control: a planted foreign skill under one of dpm''s names fires the report.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XHFTSNM4FARVCT62FV2C', '01M1C9X82WCTH2ZTSP9QSPBW1H', 'The tool returns the byte content of the package''s `shared/skill-conventions.md` for the name it is given, and refuses an unknown name rather than returning empty.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XKF5B5RYA0R8433S2433', '01M1C9X82WCTH2ZTSP9QSPBW1H', '`status-model.md` is served by the same tool under the same name-to-document mechanism, so the shared surface is one tool rather than one tool and one special case.', 'must', 1, NULL, NULL, '01M1BRZF6RZET0X87F8HBD1VWM');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XMW70J1YN4JBBRS8PTS9', '01M1C9X82WCTH2ZTSP9QSPBW1H', 'The tool''s answer is identical under both hosts: it reads from the installed package and takes nothing from the host context.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XPEDPGA9TSTYS9B0JZTH', '01M1C9X82WCTH2ZTSP9QSPBW1H', 'A second copy of either shared document exists anywhere in the tree. Control: a planted duplicate, reported by path.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XQWERGAZ1YTEWHSGAQRF', '01M1C9X9NSXNCN0ANYYHGF8PWT', 'Every one of the twenty-three bodies reaches the shared conventions through the tool, and none names a filesystem path to `shared/`. Control: a planted body carrying the old path form, which the check reports by name rather than by count.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XSDT54Q6W162STB39D4K', '01M1C9X9NSXNCN0ANYYHGF8PWT', 'The single reference to `status-model.md` reaches it through the same tool.', 'must', 1, NULL, NULL, '01M1BRZF6RZET0X87F8HBD1VWM');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XV03HFWZ6PFFQQCECTKA', '01M1C9X9NSXNCN0ANYYHGF8PWT', 'A skill body names a host. Control: a planted host name in a body, reported by skill.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XWK0EYWTXBH9RGEJHV48', '01M1C9XB5NBSBPCDXXAP0H8KKR', '`resolveSupportingPaths` and the `SHARED_REFERENCE` rewrite are gone from `src/plugin/`. Control: a planted reintroduction fails the check.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XY3D821PTM8AP7KR1FMR', '01M1C9XB5NBSBPCDXXAP0H8KKR', 'A skill body as the v2 registrar presents it is byte-identical to the file on disk.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9XZMDS6HVQG5QGNRTPSD8', '01M1C9XB5NBSBPCDXXAP0H8KKR', 'No code path under `src/` transforms skill content at registration time, under either host. Control: a planted transform fails the check.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9Y16KAK4XFNW5W1KKM1FT', '01M1C9XCMX24NRBKESSPQ369QV', 'Taking each of the twenty-three bodies, extracting the reference it carries, and calling the tool with that name returns the conventions text — for all twenty-three.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1C9Y3005BFWVW6D1RFY6WEJ', '01M1C9XCMX24NRBKESSPQ369QV', 'The same round trip performed through the callable route — the `server` export, which is v1''s only handle on the MCP registry — returns bytes identical to the one performed through the object route, the `{id, setup}` default export whose `skill.transform` is v1''s only handle on the skill registry and which `tests/support/host-contexts.js` records as the v2-shaped API v1 bundles alongside it. Amended from "a v1 stub context" and "a v2 stub context": there is one recorded host context, taken off OpenCode 1.18.25, and v2 exists in this port only in the type graph, which is erased before evaluation. The two protocol routes are the real axis dpm ships a separate module for, and the divergence they can produce — two entries resolving different trees — is the one epic 02-01 story 5 was written to catch.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CA47HB76P2MMC5DKXCH5CT', '01M1CA41FG02G8MZT4AP76Z341', 'The README''s account is correct for the host DPM supports and complete: for install, first run, guard symlink and "when the guard refuses", the instruction a reader actually follows; for Status, the host, the specs built out and the unfinished items as they now stand. Control: a planted section with its instruction removed and a planted Status naming a host DPM does not run under, each reported by heading. Amended from "gives both the v1 and the v2 form": the delivered README states there is no other host DPM runs under, so the per-host pair has no second member and the form was a mechanism for the property rather than the property. Status is named here because Chris folded it into this story at the epic''s change moment — it carries the port''s most visible stale claims and is the section a reader reaches when deciding whether to trust the thing.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CA4960YYC007SZK6C5TJ7M', '01M1CA41FG02G8MZT4AP76Z341', 'Where DPM lives on disk is stated as what it now is — a clone whose path the reader chose — and no cached-package path is presented as the location. Control: a planted package-cache sentence, reported by line. Amended from "stated per host, so neither host''s path is presented as the location": there is one host, and since epic 02-01 there is no packaged install either, so the failure to guard against is not two locations competing for the definite article but a retired one surviving. Retro 04''s lesson applies in its stronger form — find the instructions that DERIVE something from the install location''s shape, not only those that print it.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CA4AS46KMS7W359SAXF2G4', '01M1CA41FG02G8MZT4AP76Z341', 'The README names a host binary or a host version DPM does not run under — `opencode2`, or a v2 claim about the port, its behaviour or what it was built against. Control: a planted `opencode2` and a planted "ported to OpenCode v2", each reported by line. Amended from "names one host''s binary where the sentence is true of either": with one supported host there is no sentence true of either, and the live failure is the opposite one — a second host''s name surviving the pivot that removed it. The sweep is over the README and over prose, not over the tree: `opencode2` is correct history in four test doc comments and in the protected v0.7.0 dump fixture, and a whole-tree reading would be red for reasons that are all right.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CA4CBZ3SAQFNS7NGZ1AENN', '01M1CA434SC66WN2SQV8MWBZGD', 'The permission rule the README recommends matches all twenty-three skill identities as the host''s permission engine sees them — one `dpm-*` form, which works because ADR 02-04 put the prefix in the front-matter `name` the engine reads rather than in a registered id it does not. Matched against the transcribed list of published ids rather than against whatever the tree discovers, with the discovered set held equal to that list separately, so the two disagreeing is itself a failure. Control: a planted rule matching none, reported as a failure rather than passing over an empty match set, which is the shape that passes by doing nothing. Amended from "on both hosts": there is one host, and the clause was the reason the rule needed defending rather than the thing being defended.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CA4E2EEVBV0KVJCZ6G901G', '01M1CA434SC66WN2SQV8MWBZGD', 'The README states what the permission engine matches the `skill` action against — the front-matter `name` — so a reader can tell why the `dpm-*` rule works instead of taking it on trust, and the section carries no sentence contradicted by what DPM now does. Amended from "per host … v1 the front-matter name, v2 the registered id, so a reader can tell why one rule works on both": with one host there is no "both" for a reader to reconcile, and the sentence''s job moves from reconciling two engines to explaining one. The second clause is the amendment''s substance rather than a flourish — epic 02-03 removed the `external_directory` rule and left the two paragraphs that framed it, so the section now opens by telling a reader to set a rule it later says is unnecessary.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2FH4ZTATE8D7YZTT4HVM', '01M1CB27C7DJJ88XTNPGP3A4QM', 'Nothing in the dump or the projection records which host wrote it. Control: a planted host identifier in a row, found by the sweep.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2HDJHFFXSEDT2RED52Y4', '01M1CB27C7DJJ88XTNPGP3A4QM', 'A database written through the v1 server produces a byte-identical dump when read through the v2 server, and the guard accepts both.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2K2P0ZP0ZRDBSJZQJJ2H', '01M1CB27C7DJJ88XTNPGP3A4QM', 'The full `node --test` suite passes on a machine with neither `opencode` nor `opencode2` on `PATH`.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2MPETR6W2Q36RWFEW8EM', '01M1CB28ZZ9ESQY6FR4BSNJDSH', '`opencode --version` reports a 1.x build matching the version the v1 types are taken from, so the CLI and the types the registrar is checked against are the same release.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2P6HF8E1EZ4KZ4MKFT11', '01M1CB28ZZ9ESQY6FR4BSNJDSH', '`opencode2 --version` reports a `0.0.0-beta-*` build matching the v2 SDK.', 'must', 1, '2026-09-02T06:46:03Z', 'Retired at epic 02-05''s change moment. It pinned the second host''s build against the v2 SDK, and epic 02-01 dropped that host by decision — see its status_note. The property it was a mechanism for, that the CLI run and the SDK types checked against are the same release, is already carried whole by this story''s first criterion for the host DPM does target. Amending it to the v1 property would have produced a duplicate of that criterion rather than a second measure.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2R0JASXP4KJGYF7C6W9N', '01M1CB28ZZ9ESQY6FR4BSNJDSH', 'The plugin installed into a throwaway project outside this checkout, under the 1.x host, has its MCP server reach connected state with the skills advertised. Amended from "under each host" at epic 02-05''s change moment: epic 02-01 dropped the second host by decision and epic 02-04''s README must-NOT forbids naming it, so an install verified under a host DPM refuses to document would be verifying a promise nobody made. The throwaway project is what distinguishes this from the registries criterion below — it is the README''s install path walked from cold, in a directory that is not the one the port is developed in.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2SHGYE7J0BM2A5ZDPEVS', '01M1CB28ZZ9ESQY6FR4BSNJDSH', 'A v1 session completes a turn against the contributor''s model provider.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2V2YBQMQXSTAPH01RXJW', '01M1CB28ZZ9ESQY6FR4BSNJDSH', 'The plugin loads under a 1.x host and its MCP server and skills appear in that host''s registries.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2WS1XBHX79CZNJ3GEVGC', '01M1CB2AHDAQ1JRMMJYB23QH4P', 'A v1 session starts a dpm skill by the documented invocation, the skill obtains its conventions, a dpm tool writes a row, and `dpm-guard` accepts the resulting commit. The evidence is the row, the regenerated projection and the commit.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2YA8GZ9AMGN2QC0RB1ZD', '01M1CB2AHDAQ1JRMMJYB23QH4P', 'In a real v1 session, a dpm skill starts and performs a step that only the conventions prescribe — a session row created with `skill` and `phase` set, per the shared Session Startup procedure — observable in the database rather than inferred from the transcript.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB2ZXCXEFDR17T02677HE4', '01M1CB2AHDAQ1JRMMJYB23QH4P', 'Following the README''s v1 instructions verbatim produces a working install, a guard symlink that resolves, and a refusal on a deliberately stale projection.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CB31GD5SQGHSKQCM0M1C6D', '01M1CB2AHDAQ1JRMMJYB23QH4P', 'Under a running v1 host, a `deny` rule written as the README recommends blocks a dpm skill, and the same session without the rule runs it. The two directions are each other''s control: a block that would have happened anyway proves nothing.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CK9WT9N5R1Y16ENHSSHRXV', '01M1C99XSZNHY02M8TZRVMPWQT', 'Loading under v1 emits one warning naming the `mcp` block the user must add to their own configuration and the path to the packaged executable it should run. Control: the same load under v2 emits nothing, so the warning is proof of the v1 branch rather than of a logger that always fires.', 'must', 4, '2026-08-31T21:20:00.000Z', 'The warning has nothing left to warn about. It was added when story 3 was re-scoped to skills-without-tools, to stop a v1 load silently repeating epic 01-05''s shape of twenty-three skills naming tools that are not there. The v1-only retarget removed the constraint that forced that trade: dpm ships two modules, the tools module registers the MCP server through the `config` hook, and a v1 load now has its tools. A notice saying otherwise would be false.', NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQ93BFKVR851NGT9PEMRFD', '01M1C99XSZNHY02M8TZRVMPWQT', 'v1''s `config` hook sets `mcp.dpm` to a local-server entry of type `local` whose command runs the packaged executable, and the user''s own `mcp` entries survive the registration unchanged. Control: a load against an empty `mcp` block shows the reading would notice a user entry that had been dropped.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQ95CZBBSXYVYFPXCPDTQ0', '01M1C99XSZNHY02M8TZRVMPWQT', 'The entry the hook registers is the one `localServer` builds — same type, same command array — rather than a second construction of the path that agrees today. Each load is handed its own copy, so a host mutating what it was given cannot change what the next load reads.', 'must', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQ9702QK3TB7TVB98YBDYC', '01M1C99XSZNHY02M8TZRVMPWQT', 'The tools module exports a callable `server` and no default, and the skills module exports a default object and no callable `server`, so the two v1 protocols stay in two files. Control: the absence is read off the module namespace rather than through a default import, which would be a parse error rather than a failing assertion.', 'must', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQFJYA7ANXR45Q3Q0WYR00', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'The skills module registers all twenty-three skills as `embedded` sources through `skill.transform`, each carrying a non-empty body and a `location` inside the installed package. Control: the source list is driven against a draft offering `source` and `list` and not `add`, so a registration written against the v2 API fails rather than passing against a double more generous than the host.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQFMY37V5QHRJ2FAS68GCY', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'Every registered skill''s `name` carries the `dpm-` prefix, because `name` is the only field v1 keeps of an embedded skill and so is the whole of its keyspace. Control: the reading recognises an unprefixed name, so the empty result is a finding rather than a filter over nothing.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQFQNT1SK75RRFAX20A0KR', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'Registering over a name another embedded source already claimed reports that name rather than shadowing it silently. Control: a draft holding no clashing name produces no report, so the notice is proof of a clash rather than of a logger that always fires. The report states its own reach: a clash behind a `directory` or `url` source is not visible at this point and the prefix is the whole of the defence there.', 'must', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CQFT8PHQEP732X6ZSSW63Y', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 'Every `dpm/shared/*.md` reference in every registered body has been rewritten to an absolute path that exists on disk, so a session reading a skill''s conventions reaches the file rather than a path that resolves against nothing. Control: a body naming a shared file that is not in the package is refused at registration rather than registered with a broken path.', 'must', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CTJKPFR5GRZZJM7FD6C01W', '01M1C9A10T12G36GD9PC17DTYX', 'One load of both plugin entries against the recorded v1 context produces a configuration holding `mcp.dpm` and a skill registry holding twenty-three embedded sources, with the server command and every skill location resolved from the same package root rather than from two independent constructions.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CTJS1KB95H0N3ZHKGR9VWQ', '01M1C9A10T12G36GD9PC17DTYX', 'The MCP command the config hook registers is one a v1 host can actually spawn: it names a runtime that carries `node:sqlite`, so the server starts and answers rather than dying on a missing built-in module while the host waits for it.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CTJY8K6D6CDDZ4F5EMAJPX', '01M1C9A10T12G36GD9PC17DTYX', 'The reading that accepts the registered command would reject the one it replaced: handed a bun runtime, the same check refuses rather than passing, so "the command is startable" is a property being measured rather than an assertion nothing could contradict.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1CVBM6EWWWXD0JS3D31B8B7', '01M1C9A10T12G36GD9PC17DTYX', 'The README documents the install this epic actually delivers — both entry files named, the clone route given, and the reason the packaged route is not offered stated where a reader meets it — and every runnable block it gives is executed by the suite rather than transcribed into it.', 'must', 5, NULL, NULL, NULL);
