INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19HFSJC3XVKSDPAB80QHQTB', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M19367X8Q1XF3043C63VQ4ZR', 'codebase-discoveries', 'applied', 'tests/support/skills.js dies at load because it reads .claude-plugin/plugin.json in a module-level constant. Stories 1 and 3 both work near the manifest it was reaching for, so exploration starts by finding every module that reads a manifest at load rather than in a function — those decide whether a suite can start at all, and one of them hides however many assertions it holds.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19HFZH6P023CFWRXGACC4ZW', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M19367X8Q1XF3043C63VQ4ZR', 'testing-gaps', 'applied', 'Every textual sweep over import statements asserts something subtly different after a change to what an import means. This epic adds the project''s first runtime dependency, @opencode-ai/plugin, and unsanctionedDependencies, auditImports and the module sweep''s bare-specifier rule all currently forbid exactly that. Story 4''s work is deciding which narrow and which stay; the lesson says fix the reading rather than the source, and make each caller assert the new exclusion against literal strings so the walk''s silence is never the only evidence.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19HG4YZQC6M4EMCWYRTJZSP', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M19367X8Q1XF3043C63VQ4ZR', 'testing-gaps', 'applied', 'A path resolving out of the checkout produces checks that pass while asserting about a directory that is nobody''s. ENVR5 asks for a scratch OpenCode project to register into, which is outside the checkout by construction, so any check about it anchors on evidence that project produces — a server reaching connected, skills appearing in the host''s registry — rather than on a path this repository computes.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19HGAGQV0MDJ7H9PFAY60C0', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M19367X8Q1XF3043C63VQ4ZR', 'patterns-worth-reusing', 'applied', 'Every claimed absence is paired with something that would catch its presence. Story 4''s ENVX1 clause — no node-gyp, no C toolchain, no Python during a clean install — is an absence, and the disposable isolated environment epic 01-01 story 7 built is exactly its intended consumer. This story runs the check inside that job rather than asserting it by inspection, which is what ENVR12 was captured for.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19HGGPM9C2JQAHB9ES9YH5J', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M19367X8Q1XF3043C63VQ4ZR', 'complexity-underestimates', 'not_applicable', 'The nvm-versus-.nvmrc lesson and the SQLite row-typing lesson both belong to a bulk conversion of a hundred modules. This epic writes one small plugin entry against a typed SDK, so neither the version-manager trap nor the untyped-row decision arises. Re-judged next run rather than dismissed.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PSY00HX53ETHY2HJV6XD4', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'codebase-discoveries', 'applied', 'tests/support/skills.js dies at import because CALLABLE reads .claude-plugin/plugin.json. That manifest is what this epic makes unnecessary, and 44 test files depend on the prefix it builds. Cut the load-time coupling and rebuild CALLABLE from the tool names the plugin actually registers, before any skill body is edited — otherwise the batch pass lands against a suite that cannot report on it.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PT0V78GPQXSDSG85A7RE1', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'patterns-worth-reusing', 'applied', 'A rename''s blast radius is every predicate that filters, not the literal string. mcp__plugin_dpm_dpm__X to dpm_X across 23 bodies is that rename. Grep for the pattern-derived corpora — anything matching on the old prefix shape — separately from the name itself, and keep the deepEqual-against-the-expected-set assertions, which have twice been the only thing between a rename and a sweep reporting clean on nothing.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PT3TM28QGX7QWZR6WSYPA', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'criteria-gaps', 'applied', 'A criterion naming a mechanism rather than a property can be unsatisfiable or too narrow without being wrong about what matters. Story 2 and story 4 enumerate four literal strings — mcp__plugin_, /dpm:, CLAUDE_PLUGIN_ROOT, .claude/ — so a Claude Code mechanism outside that list passes. Check each is a property before building against it, and amend with a citation where it is not.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PT5NVBQJ9JXJR746TR37C', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'testing-gaps', 'applied', 'Every claimed absence is paired with something that would catch its presence. Story 4''s third criterion is already written as a control — a planted Claude Code mechanism must make the build fail — so it is driven rather than asserted, and the same shape is applied to the SQL rejection and to the invocation-prose sweep.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PTD5FYCRMWW6VME4VP7G2', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'smooth-deliveries', 'applied', 'Find the oracle before writing a test that compares the port to itself. The released v0.7.0 is installed at ~/.claude/plugins/cache/ninthspace-marketplace/dpm/0.7.0/skills/, so its 23 skill bodies are on disk. The rewrite is diffed against them rather than asserted, which makes "only host mechanics changed" a measurement instead of a claim.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PTGYCKVFPAZQEBRQGPC8Z', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'testing-gaps', 'applied', 'A duplicated reading fails silently toward a false report. tests/support/skills.js is the shared reader for skill bodies and 44 files rest on it, so every new check this epic adds goes through it rather than beside it, and any private regex over a skill body found along the way is migrated in the same change.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PTKG9PQW3W3DN3GB5SQSV', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'codebase-discoveries', 'applied', 'Ask the host what it holds, and do not believe its CLI on the first answer. Stories 1, 2, 3 and 5 each end in a scratch-project run; the probe plugin that dumps skill.transform(draft => draft.list()) goes in first, CLI listings are run twice before being believed, and a disagreement sends me to the host log before the code.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PTNHS7NQYWDYQ3P4YCT9M', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'criteria-gaps', 'applied', 'After changing something, ask what else quotes it. tool-naming.test.js deliberately asserts the skill prose still names mcp__plugin_dpm_dpm__, as the marker that this epic had not yet run. The batch pass makes that assertion fail on purpose, so it is moved with its reasoning intact rather than deleted, and the same question is asked of every coverage binding this epic touches.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PTYYMXA4BY6MK5CQ9D505', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'complexity-underestimates', 'not_applicable', 'Five of retro 01''s observations bear on the TypeScript conversion and the environment rather than on skill prose, and are set aside as a group so the non-selection is a decision rather than an omission: .nvmrc and environmental criteria discharged by a repository artefact; the Record<string, any> row-type decision; import type being loud to a regex and invisible at runtime; paths resolving out of the checkout, which is subsumed here by the skills.js coupling already dispositioned applied; and the container CI environment, whose lessons are carried by the absence-plus-control entry above. None routes to a step this epic performs.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19PV1K4TXX28YY06654QTZ8', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M193697Y6ZF3Q1KGVYPW5G15', 'patterns-worth-reusing', 'applied', 'An absence is only an observation when something was watching. Every manual scratch run in this epic states the evidence that the event happened — a count of loading-plugin lines in the log, a planted breach, a control write — beside its result, after a reload check in the last epic passed by measuring a registry nothing had disturbed.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4HJE8DDT0862XQZH0TQ7', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', 'Testing Gaps', 'applied', 'Stories 1 and 2 are entirely about paths that resolve outside the checkout — OpenCode''s hook path, the package cache directory, the symlink target. Each check anchors on evidence read at the target rather than on a constructed path, and an absent hook or absent cache is reported as a diagnostic rather than skipped.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4KRG6DWCXD53G4KHBMVJ', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', 'Patterns Worth Reusing', 'applied', 'Path containment is relative(a, b).startsWith(''..'') and never a substring test — the exact bug this observation caught, and story 2''s symlink target is the same question in the same shape. Every claimed absence in this epic gets a control that would catch its presence.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4PFZNWTRM1XNPBWT3BWH', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', 'Criteria Gaps', 'applied', 'This epic''s criteria name v2 mechanisms written before the host was opened — a hook path, a plugin storage API, a permission model. Each mechanism is checked to exist before anything is built against it; where one does not, the criterion is amended to the checkable and equally strong property with the citation, not written around.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4S0GTEXMWTDS0DZY8SN4', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', '', 'applied', 'Stories 3 and 5 are questions about a running host, so a probe leads rather than a reading of the SDK types. Bounded: the invocation walk cost seven attempts last epic, so this run stops and reports what the attempts established rather than repeating them.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4TR1N9GWBH54P0EWJZD8', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', '', 'applied', 'v0.7.0 is installed on this machine and is the oracle for what the guard did and for what the README may claim. Every manual check in this epic states the evidence that the event under test actually occurred, beside the result.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M19Y4WMZKT7KDGP5VTH3SKJH', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936AGMZ3DD6GJZM5ATYYS7', '', 'applied', 'Story 4''s lens. A README restating a version, a path or a tool count that the code already computes is a second reading that goes stale silently — point at the source, and before asserting over an artefact grep for who else reads it.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3A26Z6RW13QJ7MKSGPBTF', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936BS9145G8158CBKDD07S', 'patterns-worth-reusing', 'applied', 'A sweep whose corpus is derived from a filter goes quiet rather than breaking, and this epic''s central artefact — the published tarball — is exactly that: `files` in package.json is a filter, and the check over its contents enumerates whatever the filter produced. So the tarball listing is asserted against a named expected set (the plugin entry, twenty-three skill directories, `shared/`, the five executables) rather than looped over, because a `files` field that stopped matching would otherwise leave the check sweeping an empty list and reporting clean. Twice now a deepEqual against the expected set has been the only thing between that and a false pass.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3A8HB1H34ACYJF7V2JXT6', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936BS9145G8158CBKDD07S', 'testing-gaps', 'applied', 'Story 2 installs from the published artefact into a project outside the checkout, which is the shape that produced fifty inherited failures and, worse, the ones that passed while asserting about a directory that was nobody''s. Every check about that install anchors on evidence the install produces — a file present in the extracted package, the package''s own manifest naming itself and its version — rather than on a path this repository computes. Epic 01-04 story 2 already proved the XDG-rooted scratch works for this and it is the fixture reached for again.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3AEBDHAY2W99SMR5Y6NP2', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936BS9145G8158CBKDD07S', 'testing-gaps', 'applied', 'Story 3 verifies the production restrictions — no network at runtime, no database service, no Claude Code artefacts — and every one of those is an absence. The isolated CI job epic 01-01 built is their intended consumer, and the discipline it established governs here: a flag whose effect is invisible when honoured is probed both ways, because a step that runs offline and passes is indistinguishable from a step whose `--network none` was silently ignored. Nothing in this story is recorded as met by inspection.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3AP5HMH66S7F75YVXFXP5', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1936BS9145G8158CBKDD07S', 'complexity-underestimates', 'not_applicable', 'Six of retro 01''s observations are set aside as a group so the non-selection is a decision rather than an omission: the module that dies at import and takes a suite''s assertions with it; `.nvmrc` versus the version manager; the `Record&lt;string, any&gt;` row-type decision; `import type` being loud to a regex and invisible at runtime; and the v0.7.0 dump as a parity oracle. All five belong to the conversion of the source tree, which this epic does not touch — it packages what that work produced. The sixth, a criterion naming a mechanism rather than a property, is carried instead by the retro 02 entry on amendment, which says the same thing with the stronger procedure attached.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3AWSK8EQSAZJKCTNJ1S2A', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936BS9145G8158CBKDD07S', 'testing-gaps', 'applied', '`tests/support/sources.js` is the shared reader for `package.json` and exists because `plugin.test.js` carried a private copy of that read. This epic''s whole subject is fields in that file — `version`, `files`, `exports` — so every new assertion goes through `sources.js` rather than beside it, and any private `readFileSync(package.json)` found on the way is migrated in the same change rather than left as style.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3B3TXZND9559YQBS0JXH8', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936BS9145G8158CBKDD07S', 'patterns-worth-reusing', 'applied', 'Story 1''s must-NOT is an absence — the tarball omits a file a registered skill needs at runtime — and an absence is only an observation when something was watching. The control is a planted one: a file a skill genuinely reads at startup is excluded from `files`, the check must fail on it, and only then does a clean result mean anything. `npm pack --dry-run` against the working tree is the oracle here in the same way the released v0.7.0 was last epic: it reports what npm will actually ship rather than what the manifest is believed to say.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3BA99NQ3Y1PFBBA8ADR6N', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936BS9145G8158CBKDD07S', 'codebase-discoveries', 'applied', 'Story 2 asks whether a plugin installed from the published artefact actually registers, which is a question about a running host and not about a file. The probe plugin goes in first rather than after exhausting `opencode2 plugin list`, which produced two false "it is not loading" conclusions last epic and a third in epic 01-04 story 2. Any CLI listing is run twice before being believed, and a disagreement sends me to the host log — where `Duplicate plugin ID: dpm` announced itself last epic while every CLI route stayed silent.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1A3BSFJWSTSA9YY6WRWADKW', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1936BS9145G8158CBKDD07S', 'criteria-gaps', 'applied', 'This epic''s criteria name a mechanism — publishing to npm at 0.1.0 — and publishing is irreversible in a way the earlier epics'' mechanisms were not, so the check that the mechanism is still the right one happens before the act rather than after. And when a requirement is amended here, `list_coverage` on it names every binding immediately: a bound fragment that is no longer a substring of the requirement is a broken binding whatever its verified date says, and this epic closes the spec''s last unclaimed requirements.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDGQ5NS47Q2CYK9NYFFBAT', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Criteria Gaps', 'applied', 'Every criterion in this epic was written before the v1 SDK was opened, which is exactly the shape retro 02 recorded. Step 1 opens the v1 SDK before planning against any criterion that names its shape, and any amendment is followed immediately by list_coverage on the requirement to find what else quotes the amended text.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDGSW7ZVSM2W8DKA8FKFRW', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Testing Gaps', 'applied', 'This run adds a second SDK devDependency — the same trigger that turned eleven tests red one epic ago, and every one was a duplicate reading rather than a broken property. Before adding it, grep for every reader of dependencies, devDependencies and the import graph, and migrate them in the same change rather than fixing them as they go red.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDGXZY40JV21YFZWBGXHH5', '01M1AC4EK1MTJZ74KNA0TPFPY1', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Scope Surprises', 'applied', 'Host version is now the variable the suite has never varied, exactly as install location was in epic 01-05 — where 1085 passing tests were all evidence about the checkout. Every test written this epic is asked which host it is evidence about; a v1 registrar that registers cleanly and does nothing is this epic''s "23 skills, 0 tools", so probes record raw shape unfiltered rather than a filtered sample whose absence reads as a defect.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDH1FDW0G2DTJRY0603BDQ', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Criteria Gaps', 'applied', 'Story 4 registers the skills under v1 "fenced and alarmed", and an enumerated must-NOT is a checklist rather than a sweep. The fence is re-derived from the v1 mechanism rather than copied from the v2 prohibition list, and that is raised in Step 5 early enough to change what gets built.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDH49A0QQAF3VES4KSN8E0', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Codebase Discoveries', 'applied', 'The v1 skill registration inherits the substituted absolute path into shared/, which v2 treats as external_directory and auto-rejects. Whether v1 gates the same way is a host fact to probe rather than assume, so story 4''s verification asks whether a v1 session can actually read what the registration points at, not merely that it registered.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CDH5XY2W3SCTYJT9JKFQK7', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6DXBMMCQ0F8PPK08H6XYF', 'Complexity Underestimates', 'applied', 'This epic is a dual-form transition — one entry, two registrars — which is precisely the case where the cost lands in the apparatus that observes the change rather than in the change. Step 1 budgets for tests/support/ before the registrar itself, and any dual-host matcher is asserted against the exact set on each side so it cannot silently accept the wrong one.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CXECCF0Q4QPGC365J2TM0A', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6DZ0WSWN6M2EWHT624AQN', 'complexity-underestimates', 'applied', 'The pilot''s cost landed in the instruments, not the rename: tests/support/skills.js derived a prefix and 40 files read through it. This epic is the same rename one layer down — the name moves onto disk. Applied at story 1''s Step 1: before renaming anything, enumerate every reader that derives or asserts a skill name, and build the dual-form object (current + legacy, plus the exact list of not-yet-renamed skills) FIRST, so the intermediate state is expressible and a dual-form matcher cannot silently accept an unrenamed skill. Story 3 exists because of this lesson; it is worked as the enabling step, not the cleanup.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CXEJKX7AN11F41JQ79ZK7J', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6DZ0WSWN6M2EWHT624AQN', 'criteria-gaps', 'applied', 'A prohibition written as a list of strings catches only the strings someone thought of — $ARGUMENTS survived a pass looking for exactly its class. This epic carries two must-NOTs of the same shape: story 1''s "no two skills share a front-matter name" and story 4''s "no silent overwrite". Applied at Step 5 for both: each must-NOT is derived from the mechanism rather than enumerated — read every name the skills tree actually produces and every key the host actually indexes on, and assert over that set, so a name nobody anticipated is still in the denominator.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CXES34CZ14V6CDT54KQRSH', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6DZ0WSWN6M2EWHT624AQN', 'testing-gaps', 'applied', 'Four green files in 02-01 compared the registration to the thing that built it, so they were true of any command whatever — including one that could not start. Story 4 asks for a post-registration check on the host''s registry, and written the easy way it becomes a second reading of discoverSkills, which cannot fail. Applied at Step 5 for story 4: the check must be exercised against a draft/registry that already contains a skill dpm did not put there, so the assertion has something to be wrong about.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CXF39PENMD2VMG6RC7MWYB', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6DZ0WSWN6M2EWHT624AQN', 'scope-surprises', 'applied', 'A requirement written to fence a risk can be discharged by the risk not existing — NFR3''s premise dissolved rather than being met or breached. This epic was planned before 02-01 chose embedded skill sources, and story 1''s first criterion asserts the directory name must equal the front-matter name "which is what OpenCode requires of the pair". Under the embedded route the host is handed name, location and content directly, so that premise may not hold. Applied at story 1''s Step 1: probe 1.18.25 for what it actually keys on before building to the stated requirement, per library 05 — and if the premise has dissolved, raise it as a change moment rather than quietly satisfying a criterion that no longer fences anything.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1CXF9GQ8N8FJZH2AP7FYMBX', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6DZ0WSWN6M2EWHT624AQN', 'complexity-underestimates', 'applied', 'The packaged install was not a paragraph in the README, it was a model the document was built on — a documented model is load-bearing in more places than the section stating it. The dpm- prefix is the same kind of thing: it lives in ID_PREFIX, in the README''s permission resource rule, in cross-references inside the twenty-three skill bodies, in the guard, and in the suite''s derived names. Applied at story 1''s Step 1: enumerate every site the prefix is load-bearing at before the rename, so the surface is known up front rather than discovered one failing test at a time.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1DY54PKMZ3SNA4H8X168ZX8', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6E0GJEWC0QMJ7DRXY5RVJ', 'codebase-discoveries', 'applied', 'The `external_directory` auto-reject is this epic''s premise, not background. A design verified against the registry is not one verified against a session doing what the registration told it to: all 23 bodies point at an absolute path outside the project, and the host refuses the read. So story 1''s tool is judged by whether it removes the need for any body to name a path the host can refuse — not by whether it returns bytes. Carried into Step 1''s exploration of every story: the question asked of each change is what a real session does with it, not what the registry holds.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1DY5CV9NZMYWPJFN5XFRE25', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E0GJEWC0QMJ7DRXY5RVJ', 'testing-gaps', 'applied', 'Applied to Step 5 of story 1, and raised now rather than after the tests are written. The obvious check on a document-serving tool is that it returns what the reader returned — four readings of one source, agreeing with each other, which is not evidence. At least one check must exercise the outside: read `shared/skill-conventions.md` off disk with `readFileSync` in the test and compare bytes against the tool''s answer, and drive the refusal path against a name that is genuinely not a document rather than against a mocked absence.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1DY5KXYCNT3GQHQGH9V3B1S', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E0GJEWC0QMJ7DRXY5RVJ', 'complexity-underestimates', 'applied', 'Applied to story 2''s exploration before any substitution is made. "Route twenty-four references through the tool" reads as twenty-four edits; the README install route read as one section and was load-bearing in six places with two test files holding it there. So story 2 opens by enumerating what the current absolute-path form is load-bearing in — the skill bodies, `resolveSupportingPaths`, the body-check script, the suite''s shared-file assertions, and the README''s `external_directory` guidance — before the first body is touched, and the enumeration goes in the plan rather than being discovered by a red suite.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1DY5W0R197Q7FEMCX7EHD0X', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6E0GJEWC0QMJ7DRXY5RVJ', 'complexity-underestimates', 'applied', 'Applied as a standing rule for every sweep this epic writes: no absence is asserted until a control has shown the same reading can produce a non-empty answer. Bears hardest on story 3, which deletes `resolveSupportingPaths` — a sweep for "no body names an absolute shared path" would return empty both when the routing succeeded and when the sweep stopped matching, and those are indistinguishable. The instrument also gets its own estimate: `tests/support/skills.js` and `tests/support/body-reads.js` observe the bodies, and epic 02-02 has just shown that the cost of a body-wide change lands in the comparisons those files hold rather than in the reads.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1DY63GMBQDV28752BF3GSTY', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C6E0GJEWC0QMJ7DRXY5RVJ', 'codebase-discoveries', 'applied', 'Applied to story 1''s must-NOT, "a second copy of either shared document exists anywhere in the tree. Control: a planted duplicate, reported by path." That is a tree sweep asserting an absence, and epic 02-02 found four such assertions that had never reported anything and never could. So the duplicate check is driven against a planted second copy in a temporary tree before it is asserted over the real one, the comparison is by content rather than by filename — a copy renamed is still a copy — and containment uses `withinPackage` rather than a path prefix.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAJ7W4XAQ6KZSMVS5KY3AA', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'codebase discoveries', 'applied', 'Retro 04 obs 01M1A1GF43BMAS62WJAZK2PZ26 — the permission draft that "named both halves and would have left a reader confident they had covered publishing". Two axes: loading a skill is action `skill` with the skill id as resource; running a dpm tool is the tool''s own name as the action. Story 2 is the direct descendant of that section, so this run does not get to re-derive it. Applied as: the two-axis table in README''s Permissions section is inherited fact, not something to restate or re-reason; what story 2 changes is only what v1''s engine matches the `skill` resource against. And the paired warning — "documents the permission entries I had just learned how to exercise" is not the same as "documents the recommended permission entries" — is the acceptance test for every sentence story 2 adds.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAJDXA5AQVK409H7QH8DY3', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'patterns worth reusing', 'applied', 'Retro 04 obs 01M19ZHE2YSQB357FDEPCS9355 — "when a path stops carrying a version, every instruction that ORDERED by that path is broken rather than merely relocated; grep for the sort, not only for the prefix." The install route has since moved again, from a package cache to a checkout clone, so the same question is live in a stronger form: not only which instructions name a package path, but which ones DERIVE anything from its shape. Applied as an explicit sweep step in story 1''s task 1 — enumerate every README instruction that computes over the install location, not only those that print it. Also carries retro 04''s other half: tests/readme-v2.test.js already enumerates every fenced block, executes it under a rule, and fails both on an unmatched block and on a rule matching nothing. That machinery exists; story 1''s edits go through it rather than beside it.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAJNNVCJS0F18GXBH42YT8', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'complexity underestimates', 'applied', 'Retro 06 obs 01M1CVE1PFAAFJNFJZ66HDHWDK — "the packaged install was not a paragraph in the README, it was a model the document was built on", load-bearing in six places with two test files holding it there; the estimate was "update the install section" and the work was six sections plus two suites. This epic is that lesson''s next instalment and the estimate is the same shape: both stories read as "edit some prose". Applied by refusing the paragraph-sized estimate up front — story 1''s first act is to enumerate every place the two-host model is load-bearing (README sections, tests/readme-v2.test.js''s RULES list, tests/permission-entries.test.js, tests/readme-symlink.test.js, support/dpm-clone.js) and to treat that enumeration as the story''s real surface. Named consequence already visible: README''s Status section still says the fork is "ported to OpenCode v2" and still lists spec 01''s five epics as the whole build-out.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAJWREWB45JR9D151MWVMR', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'criteria gaps', 'applied', 'Retro 06 obs 01M1CF9SJTM9J1H5XB3NG4NDDF and 01M1CQPK4ZCDPJN74EH74JCTWF, taken as a pair — "when a criterion''s stated mechanism is false, ask what the criterion would have to MEAN to be worth its place before proposing to remove it", against "a requirement written to fence a risk can be discharged by the risk not existing, and the record needs somewhere to say so". Both directions are live in this epic at once, because all five criteria across its two stories are written on a two-host premise the delivered README has already abandoned. Applied by separating, criterion by criterion, the property from the mechanism rather than answering the whole epic one way: the per-host FORMS go with the premise, while "these four sections are correct and complete for the host we support", "the location is stated correctly", "no stale second-host binary survives" and "the recommended rule matches all twenty-three identities on the engine that evaluates it" all survive intact. Raised to Chris as a change moment rather than resolved here — a run that only ever amends and a run that only ever supersedes are each following a rule rather than reading the case.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAK7JB8KSEZ8D65YR61MCY', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'testing gaps', 'applied', 'Retro 07 obs 01M1DVY4J7E83XH9HBMR6AMRCS — "knowing the lesson does not apply it; what applied it every time was running the reading and looking at what it actually returned before asserting an absence over it, which is the cheapest possible control and the one easiest to skip when the answer is expected to be empty." Story 1''s must-NOT is exactly that shape: sweep the README for a second host''s binary, expect nothing. Applied as a hard order of operations — print what the sweep returns over the current README before any assertion is written over it. Already paid once: the sweep for `opencode2` across the tree returns hits in four test doc comments and the protected v0.7.0 dump fixture, none of them README, so a naive whole-tree sweep would have been red for reasons that are all correct history. Narrow to the position — the README, and prose rather than a recorded quotation — per library lesson 04.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAKCGNX162QH04M1RKPT53', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'criteria gaps', 'applied', 'Retro 07 obs 01M1DT33X480VF1K0ZM6FK8167''s second half — the twenty-three published skill ids are the one list in this project that may NOT be derived from the tree, because deriving them would make the check read its answer off the thing under test; ADR 01-05 makes a registered name effectively permanent from the first publish. Story 2''s criterion 1 says the recommended rule "matches all twenty-three skill identities", and the tempting implementation is to discover the skills and glob-match what comes back — which passes if a skill silently vanishes and passes if every name changes together. Applied by matching the rule against the transcribed id list that already exists in the suite, with the discovered set checked against it separately so the two disagreeing is itself a failure.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAKK93AYMT239ZYV0GKKNF', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'testing gaps', 'applied', 'Retro 08 obs 01M1E99150J7TB3Z4X7KTS4QNF — "a test can pin a false instruction as firmly as a true one", from last epic, where the README''s external_directory recommendation was held in place by permission-entries.test.js asserting the block was present. Applied immediately, because it has already recurred and this run caused it: epic 02-03 removed that block but left the Permissions section''s opening two paragraphs saying "Every skill reads a file from the package directory, which the host treats as outside your project and asks about by default — so that one rule is worth setting whatever your configuration looks like", three paragraphs above the new text saying nothing DPM does reads outside the project. The section now contradicts itself and no test noticed, because the tests check that documented rules name things that exist and never read the prose framing them. That defect is story 2''s to fix and it is named here rather than discovered later.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAKSC7G8J4CZJAN1PQ8YZB', '01M1AC4EK1MTJZ74KNA0TPFPY1', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'scope surprises', 'deferred', 'Retro 05''s pair — "a step that cannot be reversed should not be a task; it should be a gate", and "an epic''s confidence is bounded by the object it has examined; until this epic the port had only ever examined the checkout". Neither half acts on this epic. There is no irreversible step in it: both stories edit tracked prose and tests, every change is reversible, and version control stays with Chris. The second half is real and is not this epic''s to discharge — the only way to know the documented install works is to follow it on a machine, which is FR8 and epic 02-05''s live walk. Deferred rather than dismissed, and named as the reason story 1 cannot claim its README instructions WORK, only that they are internally consistent and that tests/readme-v2.test.js executes the blocks it can.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAM995EDTA1FA2GZJ28RR0', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'patterns worth reusing', 'applied', 'Retro 03''s title finding — the cost of a corpus-wide change lands in the instruments that read the corpus, not in the corpus. Retro 07 sharpened it: an instrument absorbs READS and not COMPARISONS, and the comparisons were the four-to-one larger set. Both bear directly here. The README has instruments over it — tests/readme-v2.test.js''s RULES list, which classifies and executes every fenced block, and tests/support/dpm-clone.js''s DOCUMENTED_CLONE — and story 1 rewrites the blocks those instruments run. Applied as: change the instrument''s rules alongside the prose in the same task rather than after the suite goes red, and then separately grep for the literals — host binary names, path shapes, section headings — that other files compare against without going through either instrument.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAMCXDWDVCCH63X28HM25X', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'codebase discoveries', 'not_applicable', 'Retro 02''s carried lesson is about readings of the import graph — six duplicate sweeps, each subtly different, and the rule that every textual sweep over import statements asserts something different after a change to what an import means. This epic changes prose and the tests that read prose; it adds no module, moves no import, and touches nothing under src/. Recorded as considered and set aside rather than skipped silently, because the epic''s sibling lesson from retro 06 — the same trap arriving through a different artefact — is what made it worth checking.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1EAMGNB0XNSTJJFAWDC1ACQ', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M1C6E28V4PMVDKN1B7EJGBK7', 'criteria gaps', 'not_applicable', 'Retro 01''s amendment case — a criterion naming a mechanism that was unsatisfiable, amended to the checkable property — is the same reasoning already carried into this epic through retro 06''s restatement of it, which is the sharper and more recent form and is dispositioned above. Recorded here so the older source is visibly accounted for rather than assumed to be subsumed; nothing else in retro 01 (the JavaScript-to-TypeScript conversion and its byte-for-byte dump comparison) bears on documentation or permissions.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE0RF7FV937WWX0NDJCMTQ', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Testing Gaps', 'applied', 'Retro 06: "a negative reading needs a positive control listed alongside it in the same run, because the failure being guarded against is the run not reaching the code". This epic is almost entirely negative-prone readings of a live host — an MCP server that did not connect, a skill that did not appear, a deny rule that blocked nothing because the session never started. Every host probe in stories 2 and 3 carries a known-good entry beside the entry under test, answered by one invocation. Concretely: the deny-rule criterion (story 3 C4) runs the same skill twice in one harness, with and without the rule, and the run that is supposed to succeed is the control for the run that is supposed to be blocked. A blocked-looking result with no companion success is a reading of the harness, not of the permission engine.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE0ZX0H7WJMQ9A8A17WYWC', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Codebase Discoveries', 'applied', 'Retro 06: "poll for the marker, and treat its absence as a reading rather than as a timeout." This is the operating technique for every live-host invocation in the epic. `opencode run` is non-interactive, so each probe writes to a log, is polled for a specific marker, and is killed on it; a probe that stops early or never prints its marker is recorded as evidence about the host rather than retried as a slow fixture. The daemon side has the same shape — MTPLX on 127.0.0.1:8000 was confirmed serving by reading /v1/models, not by assuming the launch succeeded, and its stdout is the log that says whether a turn actually reached the model.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE17ZQVCE1NPQRJVJ51K71', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Testing Gaps', 'applied', 'Retro 06: "when a module hands a value to something outside the process, at least one check must exercise the outside" — four green files had asserted the registration equalled the thing that built it, which is true of a command that cannot start. That finding is this epic''s whole warrant, and it is the reason the epic exists rather than being folded into 02-01. Nothing in stories 2 and 3 may be satisfied by a reading of the port''s own source or of a test double: each is answered by a real 1.18.25 host process, and the evidence recorded is what that process printed. Corollary carried too — agreement among readings of one source is not evidence, so a criterion satisfied by two of our own tests agreeing is not satisfied.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE1FYQ27S62VXGDR9ABRH6', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Complexity Underestimates', 'applied', 'Retro 06: "a documented procedure with executable guards has a blast radius the guards make visible only when you change it", plus its recorded residue — with a checkout install there is no released DPM standing apart from the working tree, so a bug in the guard now blocks committing its own fix. Story 3 C3 walks the README''s instructions verbatim into a working install and expects a refusal on a stale projection, which means it exercises exactly that regression. Two consequences for this run: the throwaway project is deliberately outside this checkout so the walk cannot be rescued by the development tree, and the guard exercised in the walk is the one the README names rather than the installed plugin used for this repo''s own commits. Where the walk trips the known regression, that is recorded as a finding of the walk rather than worked around.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE1R3GDEWVABYAKF638Q56', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Criteria Gaps', 'applied', 'Retro 07: "when a criterion''s measure can move without the subject moving, it is measuring something else. Ask what else can move it before writing the number down." Story 1 C3 asks that the full suite passes on a machine with neither host binary on PATH. Two things can move that measure without the suite moving: a PATH stripped so aggressively that node itself is unreachable, which fails for the wrong reason, and a test that skips silently when a binary is absent, which passes for the wrong reason. So the reading is not a bare exit code — it records the pass count against the committed baseline and asserts zero skipped, and it establishes positively that a `which` for both binaries returns nothing inside the same shell that runs the suite.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE1ZFJ3ZKMRRFBT1BJ7WVW', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Codebase Discoveries', 'applied', 'Retro 07: "a predicate does not have to stop matching to go quiet, it can have been quiet from the day it was written. The tell is that a check for an absence has never once reported anything." Story 1 C1 is a must-shaped criterion with a must-NOT interior — nothing in the dump or the projection records which host wrote it — and it already names its control in its own text. This run treats that as binding rather than decorative: the planted host identifier goes into a real row in a real database, the sweep is run and seen to report it by path and by row, and only then is the sweep run over the clean artefact. A sweep whose first ever execution returns empty has not been verified.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE29NCTX5N0GT2S62EB5DP', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Criteria Gaps', 'applied', 'Retro 08: "Three green stories left the epic''s actual claim unchecked, and only a story written to walk the whole trip found it. The gap sat exactly at the seams, where each story''s assertions stopped." This epic IS that walk, one specification up — nine epics have each proved their own piece and none has started a skill in a real session and followed it to a commit the guard accepts. So the disposition is structural rather than a technique: story 3 is not permitted to be decomposed into per-seam checks that each pass. It runs one continuous trip and the evidence is the trip. The retro''s second half applies directly too: extract the argument from the artefact rather than writing it down. The skill the walk starts, the conventions it obtains and the tool it calls are read out of the registered bodies and the running host''s registries, not typed from memory — and the control matters more than usual, because "the walk succeeded" is also what a walk that extracted nothing and started nothing produces.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE2JE0Q278KM8S05GNY6SR', '01M1EWTJFC7H2N8GEXG4XGCKPR', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Patterns Worth Reusing', 'applied', 'Retro 09: "a control that asserts a non-empty result is weaker than one that asserts the exact set, because the first is satisfied by the patterns that already worked" — and its uncomfortable half, that knowing the lesson did not apply it, for the second epic running. Story 1 C1''s sweep will carry several patterns (a host binary name, a version string, a config path, a provider id). The control plants an artefact carrying every one of them and asserts the exact set of hits, not that hits occurred. Written down here because the last two epics both dispositioned this lesson and then failed it inside the same run; the specific trap last time was a line-anchored pattern against hard-wrapped text, so no pattern in this epic''s sweeps is line-anchored unless the thing it matches genuinely cannot wrap.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE2TQKF1Q4DW9ST22E4YG7', '01M1EWTJFC7H2N8GEXG4XGCKPR', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Testing Gaps', 'applied', 'Retro 09: "an executable check over a document tests the half of it nobody misreads … derive the list from the tree in both directions." Story 3 C3 takes the README''s install instructions verbatim into a fresh directory. The lesson''s bearing here is that the fenced blocks already have an oracle in readme-v2.test.js and it stays green regardless, so the walk''s value is in the parts between the blocks — the order the steps are in, the assumption that a step''s output is what the next step needs, the `<dpm clone>` substitution a reader has to perform. The walk records where a reader following the document in order would stop, and any gap found becomes README text plus a check derived from the tree rather than a hand-kept note.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M1GE34MHBW7NV5J8EWMNSQN4', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C6E3XG8EVENPG8P74RHGGA', 'Patterns Worth Reusing', 'not_applicable', 'Retro 08''s "a parity oracle is a floor, and an equality says it is a ceiling" — the INHERITED/ADDED reshape, with the note that the two remaining equality assertions, parity-v070.test.js''s dump and the corpus snapshot, should be reshaped when they hit their expiry. Set aside because this epic adds no tool, no skill and no test-corpus member: it verifies what is already built against a live host. Neither remaining equality is touched, so neither reaches its expiry here. Recorded rather than skipped silently because story 1 C2 does compare two dumps for byte-identity, which reads like the same shape and is not — that comparison is between two readings of one database, where equality is the property itself rather than a stand-in for a floor.');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9', 'dpm:do', 'Epic 01-05 — stories 1 and 3 complete; story 2 held awaiting Chris''s push, then a clean re-install and re-verify', 'LOOP CONTRACT: this run executes every story of epic 01-05 in one continuous loop and stops only at the gates dpm:do names. A finished task, story, verification or commit is NOT a gate. Never ask "shall I continue".

Test command: `node --test` from the repo root, Node 24 via `export PATH="/Users/chris/Library/Application Support/Herd/config/nvm/versions/node/v24.20.0/bin:$PATH"`. Framework: none (node:test). Suite at 1093/1093. tsc clean, `npm run modules` clean, guard clean, projection published.

EPIC 01-05 POSITION: story 1 complete (3/3 coverage verified). Story 3 complete (3/3 coverage verified, all 3 tasks). Story 2 is the only one open — tasks 1 and 2 are done and verified against a locally patched install; Chris chose "push first, then re-verify clean" at the gate, so its criteria are NOT yet recorded met.

WHAT STORY 2 STILL NEEDS, once Chris has pushed src/plugin/server.ts to main:
  1. rm -rf <scratch>/ghinstall/cache and <scratch>/ghinstall/config
  2. re-run `opencode2 plugin add github:ninthspace/opencode-dpm` with XDG_CONFIG_HOME/XDG_CACHE_HOME at the scratch
  3. re-run the standalone host with probe.js; expect 23 skills and `mcp connected server=dpm tools=183`
  4. re-run <scratch>/ghinstall/endtoend.mjs; expect 7/7
  5. then verify criteria 01M19582S6ABCHQ857XN2YRTYV, 01M1958422X7G47SMQ39TMXG8P, 01M19585MT85VK08FVW7BECR4C and their coverage rows, complete the story, then Step 8 epic close.

THE DEFECT AND THE FIX (story 2 task 1): the documented GitHub install registered 23 skills and 0 tools. Node refuses to type-strip any `.ts` under `node_modules` (ERR_UNSUPPORTED_NODE_MODULES_TYPE_STRIPPING, on 22 and 24, no flag lifts it) and OpenCode installs every plugin there. `localServer()` now detects the runtime: under bun it returns `[process.execPath, <root>/bin/dpm-mcp.ts]` with `environment: {BUN_BE_BUN: ''1''}`, else the old `[''node'', …]`. No build step; NFR2 intact. Guard is tests/installed-runtime.test.js (3 tests, control-first). Full write-up is the epic section "The installed package could not run its own MCP server".

ALSO ESTABLISHED: tool ids are `dpm_create_spec` with `options.namespace: ''dpm''`; `tool.name` is the bare `create_spec`. 183 of 195 ids carry `dpm_`. Epic 01-03''s 456 rewrites are correct.

STORY 3 METHOD, worth reusing: tests/support/network-watch.js is an `--import` instrument wrapping net.Socket.connect, net.Server.listen, dns.lookup, dns.promises.lookup and fetch. DPM_NETWORK_LOG records; DPM_NETWORK_BLOCK additionally throws after recording. Watch answers "made no attempt", block answers "completes with networking disabled" — the criterion names both. Two exceptions NAMED in suite-integrity.test.js (not exempted): the instrument''s node:net/node:dns imports, and production-restrictions.test.js''s loopback fetch control.

SCRATCH: <scratchpad>/ghinstall/ holds config/, cache/ (installed package, PATCHED — delete before re-verifying), data/, project/, endtoend-project/, probe.js, endtoend.mjs, run4-7.log.

UNCOMMITTED: package.json, src/plugin/server.ts, tests/support/sources.js, tests/executables-typescript.test.js, tests/plugin-entry.test.js, tests/vendoring.test.js, tests/suite-integrity.test.js, docs/ + .dpm/dpm.sql projection; NEW tests/publish-package.test.js, tests/installed-runtime.test.js, tests/production-restrictions.test.js, tests/support/network-watch.js.

CARRIED DEBT: retro due on epic 01-03 (7 ungrouped observations); four unverified 01-03 coverage rows (01M194YPV1N00588YDCT47GW1Q, 01M194Z3N2KEG60Z6PGTF85C4S, 01M194ZAEN8K3FXHNJDHTVQ526, 01M194ZHEXK4DE85A52DTJS9J8); FR2 and FR3 unclaimed; upstream dpm 0.7.2 narration changes (0c1d501, 265ec67) deferred. Open findings: /dpm:templates, /dpm:do, /dpm:epics still in JSDoc in src/tools/cross/template.ts, src/coverage/warrant.ts, src/preview/example.ts. DATABASE = ''.dpm/dpm.db'' is relative, so the cwd OpenCode gives a spawned MCP server decides which repository .dpm/ lands in.

STANDING: version control stays with Chris (no commit/add/push/branch unless asked); edits via the Edit tool file-by-file, never sed/perl/awk; every tool value is its own argument.', NULL, '2026-08-30T11:09:12.357Z', '2026-08-30T20:48:17.812Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-epics-02', 'dpm:epics', 'Complete — all five epics broken down, gap check clean', '{"source_spec":"01M1BJS4H76EB2K3Z98YPNG17B","run":"complete","totals":{"epics":5,"stories":18,"criteria":62,"tasks":44,"story_edges":18,"epic_edges":7,"coverage_rows":55,"adr_warrants":8},"tags":{"unit":46,"integration":7,"manual":8,"target":1},"gap_check":"every one of the 62 story criteria reads accounted_for; 20 of the 22 non-wont requirements carry coverage. FR9 and FR10 are could-haves left unbound by design; FR11-FR14 are wont.","fully_manual_stories":["02-05 story 2 Install under a real v1 host","02-05 story 3 The end-to-end walk"],"deferred":"spec 01 pivot (ENVR9, ENVR4, NFR3, FR3 mechanism criterion, FR15) is a separate run","next":"publish and commit; then dpm:do on epic 02-01"}', NULL, '2026-08-31T15:17:25.456Z', '2026-08-31T16:42:49.005Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-retro', 'dpm:retro', 'Complete — retro 03 recorded on epic 01-03', 'mode: synthesise. Subject: epic 01-03 "Skill port and registration" (01M193697Y6ZF3Q1KGVYPW5G15), chosen by Chris. Retro 03 "Skill port: the cost landed in the instruments" created (01M1ABMF2GJVS45PYQ2H6WCVW1). All 7 observations gathered with positions 0-6; story_id untouched on every one. Synthesis written on the two paired categories (complexity-underestimates: 01M19SFYZD + 01M19XN46B; patterns-worth-reusing: 01M19VT4A2 + 01M19X968M) and deliberately left unset on the three singletons (criteria-gaps, scope-surprises, codebase-discoveries) rather than restating them. Step 4 library write-back skipped: the only library document scopes to architect/do/epics/spec, not retro, so nothing was read at startup to amend. Still outstanding across the project: epics 01-04 and 01-05 have no retro; epic 01-02''s retro 02 gathered four observations carrying no story_id, leaving its five stories'' six observations ungathered.', NULL, '2026-08-30T21:58:25.615Z', '2026-08-30T22:12:09.870Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-retro-02-repair', 'dpm:retro', 'Complete — epic 01-02''s six story observations gathered into retro 02', 'Done. Retro 02 (01M19PKK0012R8QQZ86813ATB5) now holds 10 observations: its four original synthesis-shaped rows at positions 0-3, and epic 01-02''s six real story observations at 4-9 (01M19M93YZ story 1, 01M19M9RBM story 1, 01M19MRYF8 story 2, 01M19NF6TM story 3, 01M19NX65E story 4, 01M19PG055 story 5). Only retro_id and position were set — no synthesis, no story_id change, nothing retired. Every epic in the spec now carries a retro and every observation in the project is gathered: 34 in total — 9 in retro 01, 10 in retro 02, 7 in retro 03, 5 in retro 04, 3 in retro 05. Left open for Chris: rows 0-3 of retro 02 are cross-story syntheses recorded as observation rows rather than in the synthesis column, so retro 02 reads as ten observations where the other retros read as their story observations plus syntheses. Folding them in would mean retiring four rows, and retirement is defined as "the lesson is no longer true anywhere", which is not the case — so it needs a decision, not a tidy-up.', NULL, '2026-08-30T22:22:28.535Z', '2026-08-30T22:22:59.395Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-retro-04', 'dpm:retro', 'Step 1 — gather epic 01-04''s observations', 'mode: synthesise (never retire, learn or triage in this run). Subject: epic 01-04 "Guard, documentation and host behaviour" (01M1936AGMZ3DD6GJZM5ATYYS7), chosen by Chris. Library check carried from the previous run in this session: the only library document (01M190RZY3N512H26B7SMAPWKS) scopes to architect/do/epics/spec, not retro, so it does not apply and Step 4 has nothing to amend. Taxonomy read at limit 100: 7 observation categories, none project-added.', NULL, '2026-08-30T22:12:44.496Z', '2026-08-30T22:12:44.496Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-retro-05', 'dpm:retro', 'Complete — retro 05 recorded on epic 01-05', 'mode: synthesise. Retro 05 "Publish: the epic that opened the artefact" (01M1AC4EK1MTJZ74KNA0TPFPY1) created on epic 01-05. All 3 observations gathered at positions 0-2; story_id untouched. Synthesis written for the two paired categories (scope-surprises: 01M1A42P9B + 01M1A8J3R5; testing-gaps: 01M1A8J3R5 + 01M1A6THRW) and left unset on the three singletons (criteria-gaps, codebase-discoveries, patterns-worth-reusing). Step 4 library write-back skipped — the only library document does not scope to retro. Every epic in the spec now carries a retro: 01 (retro 01), 02 (retro 02), 03 (retro 03), 04 (retro 04), 05 (retro 05). One repair still outstanding and never started: retro 02''s four observations carry no story_id, so epic 01-02''s five stories'' six observations (01M19M93YZ, 01M19M9RBM, 01M19MRYF8, 01M19NF6TM, 01M19NX65E, 01M19PG055) remain ungathered.', NULL, '2026-08-30T22:16:52.402Z', '2026-08-30T22:20:43.383Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-retro-learn', 'dpm:retro', 'Complete — four lessons promoted, eleven observations retired at source', 'mode: learn. Done. Chris approved all four candidates. Library entries created (each with scopes then one section, in that order, before anything pointed at them): 02 absence-needs-a-control (testing-standards; do, epics) 01M1ACQFRJ0JVFMTFZQE1BA665; 03 find-the-oracle-first (testing-standards; do) 01M1ACQH5P4XHAT87SQZNBKM9K; 04 no-substring-matching (coding-standards; do) 01M1ACQJD8SR4B6P8SPQCET4R6; 05 probe-the-host-first (architecture; do, architect) 01M1ACQM2C6KWX1W5CCQZKVYQH. Eleven observations then took library_doc_id with retired_at and retired_reason in the same call — 3, 3, 3, 2 respectively. Corpus went 34 to 23 offered. Verified: the retro projection renders retirements rather than filtering them (src/projection/templates/retro.ts:10), so all five retro documents keep the text and gain a Retired line. Note for a future run: library_doc_id is a single column, so an observation carrying two durable lessons graduates once — 01M19GV7Q1 went to absence-needs-a-control though it also carries the canonical substring bug, which no-substring-matching cites in its body instead.', NULL, '2026-08-30T22:26:15.175Z', '2026-08-30T22:33:17.560Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('8afd89dc-8e1d-4c30-959b-48255fc1b4f9-spec-v1', 'dpm:spec', 'Complete — spec 02 approved', 'skill=dpm:spec. COMPLETE.

Spec 02 = 01M1BJS4H76EB2K3Z98YPNG17B "OpenCode v1 host support", status complete, builds_on spec 01 (01M191BE7MHM077FE9YM09B2ZK).
28 requirements (FR1-FR14, NFR1-NFR5, ENVR1-ENVR5, ENVX1-ENVX4), 33 acceptance criteria with approaches, 5 ADRs all accepted, 3 prose sections (The problem, Scope boundary, Integration boundaries).

ADRs: 02-01 shared documents served by the MCP server (01M1BRZF6RZET0X87F8HBD1VWM, 5 options); 02-02 one entry, host detected once (01M1BS1PKT28DGEWHFDZE889PT); 02-03 build on skills.paths fenced and alarmed (01M1BS1S883B15Q557G93HBFNS); 02-04 skills carry their own dpm- prefix, 23 directory + front-matter renames (01M1BS1W0Z2W3APKKB2XQJRVDV); 02-05 second SDK by npm alias (01M1BS1XJ6GP8VN4D8PQAGXXZM).

DECISIVE EVIDENCE GATHERED THIS RUN: OpenCode does NOT expand @ file references in instruction files (docs) — the documented routes are opencode.json `instructions` or telling the model to Read the file. v1 skill docs also require the front-matter name to MATCH THE DIRECTORY NAME and to satisfy ^[a-z0-9]+(-[a-z0-9]+)*$ — which is why 02-04 is 23 directory renames, not 23 front-matter edits. config.skills.paths is absent from the documented discovery roots, confirming it is undocumented rather than merely untested.

OUTSTANDING AFTER THIS SPEC:
1. dpm:epics on spec 02.
2. A dpm:pivot run on spec 01 amending five requirements: ENVR9 (v2 as THE production host), ENVR4 (v2 beta CLI as the dev requirement), NFR3 (pins @opencode-ai/plugin@beta), FR3''s mechanism criterion (names ctx.skill.transform), FR15 ("OpenCode v1 support", wont/out_of_scope — supersede rather than reword).
3. Two unestablished host facts, neither blocking: whether v1 permits a model read of a path inside the plugin package; how v1 loads a module exporting more than one plugin function.
4. Spec 01''s three [manual] FR3 rows and ENVR8''s [target] row remain open.', NULL, '2026-08-31T09:28:51.469Z', '2026-08-31T12:27:44.153Z');
