INSERT INTO "dependency" ("id", "kind", "source_document_id", "source_story_id", "target_document_id", "target_story_id") VALUES ('01M1CB4F3KFJ97PQ43BK0SQ9KC', 'blocks', NULL, '01M1CB28ZZ9ESQY6FR4BSNJDSH', NULL, '01M1CB2AHDAQ1JRMMJYB23QH4P');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M196EKMCSBATV86ZBRERN9R7', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CRHRQC3Z4E42TM3XKPGT', NULL, NULL, 0, '`tests/support/skills.js` cannot be imported in this fork at all: its module-level `CALLABLE` constant reads `.claude-plugin/plugin.json`, which the vendoring step deliberately dropped. Every suite importing it therefore dies at load with an ENOENT before running a single assertion, rather than failing an assertion that names the cause. The refactoring pass found this by trying to reuse `skillNames()` and had to revert.

This shapes Story 4. "Restore the inherited test suite green" has two classes of failure in it, not one: assertions that are wrong about the fork, and modules that will not load in the fork. The second class hides the first — a suite that dies at import contributes one opaque failure standing in for however many real assertions it holds, so the 50 remaining failures are a lower bound on the work rather than a count of it. Cutting the load-time couplings first is what makes the rest of the count mean anything.', 'A module that dies at import contributes one opaque failure standing in for every assertion it holds, so a failure count taken before the load-time couplings are cut is a lower bound rather than a measurement. Sequence the work accordingly next time: cut what will not load, then count.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M196EQZC9ZD32E6VJAS2TRRZ', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CRHRQC3Z4E42TM3XKPGT', NULL, NULL, 1, 'Raising the floor to 24 was one constant; getting the machine to 24 was not. `nvm install 24` and `nvm alias default 24` both succeeded and `node --version` went on reporting 22.18.0, because nvm''s auto-activation re-selects whatever Node is already on `PATH` rather than the default alias — so every shell descending from an already-pinned session keeps the old version, and the alias is only consulted where nothing was pinned. What actually satisfied the criterion was committing `.nvmrc`, which the contributor''s shell already acts on when entering the directory.

Worth carrying forward because the criterion is written as "`node --version` on the contributor''s machine reports 24.0.0 or above", and the obvious reading of that — install the version — leaves it false. The repository artefact is the mechanism, not the install.', 'An environmental criterion written as an observation about the contributor''s machine is discharged by the repository artefact that makes it true on every machine, not by an install performed once on one. Reach for the committed mechanism — `.nvmrc`, an engines field — before the version manager.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19BJFTXHC9PTSCD2THNXY3F', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CSTFYJ1RQWVK6AX2QYP0', NULL, NULL, 2, 'The conversion''s hard part was not the syntax but the *type* for an untyped SQLite row, and getting it wrong once cost a full pass over the projection. TypeScript''s rule — an index signature does not supply a target type''s *required* named properties — was established empirically in a scratch file rather than guessed at, and it invalidated the first approach (small named row shapes like `{id, number}` passed between modules), because `Record<string, any>` is not assignable to them. The settled answer is one honest type, `Record<string, any>`, declared once per layer with a written rationale: `Row` in `projection/naming.ts`, `Args`/`Row` in `tools/convention.ts`, `ViolationRow` in `integrity/register.ts`. The alternative, `unknown`, was rejected in writing because it puts several hundred identical casts at call sites, none of which check anything. Two consequences worth carrying forward: object spread **drops** an index signature, so `.map((r): Row => ({...r, x}))` needs the return annotation or the nested shape silently loses every column it came in with; and shared types were pushed *downwards* into the module with no imports and re-exported, rather than sideways, so no type-only import points back up a dependency edge.', 'The expensive decision in a JS-to-TS port is the type given to an untyped row, and it is worth settling empirically in a scratch file before the first module is converted rather than discovering it a hundred files in. One honest `Record<string, any>` per layer with a written rationale beat both small named shapes and `unknown`; the two traps — spread dropping an index signature, and type-only imports pointing back up a dependency edge — are worth a coding-standards entry.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19BK4937ESM8E8TQ6T88EZS', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CSTFYJ1RQWVK6AX2QYP0', NULL, NULL, 3, 'A type-only import is invisible at runtime and highly visible to a textual sweep, and that mismatch broke a real invariant test two suites deep. `server.test.js` and `publish-cli.test.js` each walk the static import graph to prove no executable reaches `node:sqlite` before the Node-floor check runs — a genuine NFR2 guarantee, since ES imports evaluate before any statement in the file. Adding `import type { DatabaseSync } from ''node:sqlite''` to `src/db/capability.ts` is erased by both Node''s type-stripper and `tsc` under `verbatimModuleSyntax`, so the guarantee held; the regex did not know that, and reported a crash that cannot happen. The right fix was the sweep, not the source. Two things made it safe: the exclusion lookahead is narrow in both directions (`import { type Row, insert }` still loads the module for `insert`; `import type from ''./x''` is a value default import bound to the name `type`), and each suite now asserts the exclusion directly against three literal strings rather than trusting the walk''s silence. The generalisable lesson: after a TypeScript port, every textual sweep over import statements is asserting something subtly different from what it was written to assert.', 'After a TypeScript port every textual sweep over import statements is asserting something subtly different from what it was written to assert, because `import type` is loud to a regex and invisible at runtime. Audit the sweeps as part of the conversion, fix the reading rather than the source, and have each caller assert the exclusion against literal strings so the walk''s silence is never the only evidence.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19CFH1YN3E20748372GN2TN', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CV7AYZP0X6SV38W5FT4J', NULL, NULL, 4, 'A rename''s blast radius is not the string that names the file — it is every predicate that *filters* by extension, and only one of those is caught by rewriting the string. The narrow rewrite moved 54 occurrences of `dpm-X.js` across 26 files cleanly, and the suite then went from 50 to 55 failures. Four were escaped regexes (`/dpm-import\.js$/`) the pattern could not see, and the fifth was the dangerous one: `readdirSync(bin).filter((name) => name.endsWith(''.js''))` in two suites, which silently became an empty enumeration. Both were saved by an assertion their authors had written for exactly this — `deepEqual(binaries, [the five])` with the message "the set of binaries moved — the sweep below is enumerating something else now". Without that line the two suites would have swept nothing and reported clean, which is the false pass this project keeps rediscovering. The generalisable rule: when renaming by extension, grep for `endsWith`, `filter` and escaped `\.js` separately from the literal name, and treat any sweep whose corpus is derived from an extension as part of the rename.', 'A rename by extension has a blast radius the literal string does not describe: every predicate that filters on that extension is part of the rename, and the ones that go quiet are more dangerous than the ones that break. Grep for `endsWith`, `filter` and escaped `\.js` separately from the name, and keep writing the assertion that names the corpus — twice now, a `deepEqual` against the expected set is the only thing standing between a rename and a sweep that reports clean on nothing.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19ENVMGEB1EEVRZ3FGNA32Y', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CZBACY1KZJ264E2ZH76G', NULL, NULL, 7, 'The criterion said the sweep "imports every file under `src/` and `bin/`", and `bin/` cannot be imported: `dpm-guard.ts` ends in `process.exit(run(...))` and `dpm-mcp.ts` in `await main()`, both at module top level, so importing them runs the guard against the repository and starts a server waiting on stdin. The criterion was amended to say what is actually checkable and equally strong — resolve every specifier in both roots, import the modules under `src/` — rather than the sweep being written to match wording it could not satisfy. The distinction matters because resolution is what a wrong extension breaks, so nothing was given up: the planted controls catch an extension-less import, a stale `.js` pointing at a `.ts`, and a bare specifier, all three in `bin/` as readily as in `src/`.', 'A criterion that names a mechanism rather than a property can be unsatisfiable without being wrong about what matters — "imports every file" was unachievable for `bin/`, while "resolves every specifier" gives up nothing a wrong extension could hide. Amend the criterion to the checkable and equally strong form, with the citation, rather than writing the implementation to match wording it cannot meet; and prefer stating criteria as properties so the question does not arise.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19EZQKD9RBKZ3PDHAJZM357', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CWMBV0R2TR8M9NEDNBKV', NULL, NULL, 5, 'Every one of the 50 inherited failures traced to a path that resolved out of the checkout. At v0.7.0 the plugin sat inside the marketplace repository, so `join(dirname, ''..'', ''..'')` reached a sibling; in a standalone fork it reaches the developer''s home directory. The damaging cases were not the ones that crashed but the ones that passed: `reference-environment.test.js` checked that CI did not exist in a directory that was never this project''s, and `corpus.test.js` compared dpm''s skills against an unrelated `~/Work/git/cpm` and reported a missing conversion. The fix in each case was to anchor on evidence rather than on a path — a plugin manifest naming itself and its version, a recorded list of what the source release shipped — and to report an absent neighbour by diagnostic rather than skipping. Twice during this story a control I wrote fired and was right: the CPM drift detector found that the sibling was a genuine but abandoned 1.0.0, and the `CLAUDE_` scrub control fired in exactly the environment its criterion describes, where there is nothing to scrub. The second was a bug in the control, not the code — a control that demands the hazard be present fails on the machine where the hazard is absent.', 'Extracting a component from a monorepo relocates every relative path that pointed outward, and the tests that go on passing are the ones to hunt: they now assert about a directory that is nobody''s. Anchor a check on evidence — a manifest naming itself and its version, a recorded list of what the source shipped — rather than on a path, report an absent neighbour by diagnostic rather than by skipping, and write controls that tolerate the hazard being absent, since a control demanding the hazard fails on the clean machine.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19FJ1V28GRJ2KH1M6MVMY5R', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193CY1QWF6PRDPHJTR1P95S', NULL, NULL, 6, 'The inherited suite already covered four of this story''s eight criteria properly, and every one of those tests compares the port against itself — they would all keep passing if the conversion had changed the dump format, the sort order or the allocator, provided it changed them consistently, which is the shape a 100-module rename actually takes. What was missing was an oracle written by v0.7.0, and the repository turned out to hold one: `.dpm/dpm.sql` at commit 1123bc7 was produced by v0.7.0''s dumper and allocator before a line of the port existed. Frozen as `tests/fixtures/v070-dump.sql`, it gave the strongest result of the epic — the ported restorer reads 296,061 bytes of v0.7.0 output and the ported dumper writes them back unchanged, and replaying v0.7.0''s 21 creates in v0.7.0''s order allocates v0.7.0''s numbers. The lesson worth carrying: when porting, look for an artefact the old code left behind before writing a test that can only compare the new code to itself. Also worth noting for the next story that touches this area: `start()` does not restore — the restore is a step in the server''s bring-up — and a test that calls `start()` on a clone gets a seeded database whose empty content tables look exactly like a broken restore.', 'A port verified only against itself passes any change made consistently, which is the shape a large rename actually takes — so before writing a parity test, look for an artefact the old code left behind. Here the repository''s own history held one, and it turned a self-consistency claim into byte-identical evidence; make "find the oracle first" the opening move of any future parity story.', NULL, '01M1ACQH5P4XHAT87SQZNBKM9K', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: "find the oracle before generating the expectation" proved out three times across retros 01, 02 and 03, so it belongs where every run reads it rather than where it is re-judged.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19GV7Q1P63DBMFP71K1SC5G', '01M19H43RS516A49PH5JSMQKQD', 'retro', '01M193D0TS9VBQKYHW2PWPFMXX', NULL, NULL, 8, 'The first CI run was the first time this suite had ever run on a machine other than the one that wrote it, and it failed two tests out of 1015 — both for reasons no amount of local running could have surfaced.

The sharper of the two is a genuine latent bug that had been passing for the wrong reason since v0.7.0. `coverage-retirement-environment.test.js` asserted that a fixture database is outside the repository by writing `file.path.includes(DPM)` — a substring test standing in for a path test. It asks whether the repository''s path appears anywhere inside the fixture''s, which is a different and much weaker question. On a checkout at `/Users/chris/Work/git/opencode-dpm` it is indistinguishable from the right check; in the container, where the checkout is `/dpm` and `mkdtempSync` produces `/tmp/dpm-XXXXXX`, it fired on a scratch file that was exactly where it belonged. Containment between two paths is `relative(a, b).startsWith(''..'')`, and nothing else.

The second was not a bug but a missing environment: ENVR6 asks for a hook installed at `.git/hooks/pre-commit`, a fresh checkout has none, and the choice was between narrowing the assertion to accommodate CI or installing the hook so the assertion stays true. Installing it is right — it is what a contributor does on their first clone, so a CI run without it is a run against an environment the specification does not describe. The same problem arrived a second way in the container: `COPY` brings a symlink across as a symlink, so the host''s hook link pointed at a path that exists on one machine and nowhere in the image, and a dangling link reads as no hook at all.

The design decision worth carrying is that every absence in the isolated job is paired with something that would catch its presence. The Docker build fails if the base image already has Node or a compiler, so "installed into a bare environment" is a state the build passes through rather than a claim about it. And `.github/network-probe.js` is run twice — once with networking and once with `--network none` — because a step that runs the suite offline and passes is indistinguishable from a step whose `--network none` was silently ignored. The probe takes its target as an argument, so the suite drives it against a `data:` URL and a closed loopback port and exercises all four combinations without a packet leaving the machine, which keeps the suite offline-clean while still proving the control works.', 'A suite that has only ever run where it was written carries bugs that pass for the wrong reason, and a second machine is the cheapest way to find them — the substring-for-path check had been green since v0.7.0 and took one containerised run to expose. Stand CI up earlier in a port than last, and keep the discipline the isolated job established: every claimed absence is paired with a control that would catch its presence, and a flag whose effect is invisible when honoured is probed both ways.', NULL, '01M1ACQFRJ0JVFMTFZQE1BA665', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: the control-for-every-absence discipline recurred in retros 01, 03 and 05, so it is now standing guidance read at startup rather than a lesson re-judged each run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19M93YZTA8XT2H3GRZ92FQ9', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194E5SEXMD6W90PSM0ATR4J', NULL, NULL, 4, 'Adding one devDependency turned eleven tests red, then six more, and every one was a duplicate reading rather than a broken property. `@opencode-ai/plugin` is taken `import type` only, so `dependencies` stayed `{}` and the nine assertions about it were untouched — exactly as planned. What broke instead was the *other* claim: "nothing under src imports a package". Four separate readings of that existed — `sources.js:staticImports`, `sweeps.js:importSpecifiers`, and inline regexes in `server.test.js` and `projection.test.js` — and only the first had been taught, during the TypeScript port, that `import type` is erased before evaluation. The three that had not went on reporting a runtime dependency that does not exist. Consolidating them onto the one reading fixed all six at their source, and the same shape recurred twice more: the `.node` sweep in `plugin.test.js` walked `node_modules` and read a transitive dev package''s prebuilt binary as something dpm ships, and CI''s clean-install grep matched the *name* `node-gyp-build-optional-packages` — a script that selects a prebuilt and compiles nothing — rather than the act of compiling. Both were replaced by artefact checks with controls. The lesson is narrower than "avoid duplication": a helper written to end a duplication only ends it for the callers that were migrated, and the copies left behind fail silently in the direction of a false report.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19M9RBM22VKHVVN0WH3551N', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194E5SEXMD6W90PSM0ATR4J', NULL, NULL, 5, 'The scratch-project run was worth three tasks of reading, and every finding contradicted an assumption the plan had written down. The config key is `plugins`, not `plugin` — the wrong key is accepted and normalised away with a diagnostic in the log and no error at the CLI, so the first attempt looked like a plugin that would not load. `package` is `import()`ed as a literal path with `?mtime=` appended, so a *directory* does not resolve and `exports` is never consulted for the filesystem-path form; the entry *file* is what a local config must name. And the host runs the TypeScript source directly, since it is Bun-compiled. The connection failure that followed was dpm''s own ENVR8 floor check refusing under Node 22 — correct behaviour, indistinguishable at the CLI from a broken registration ("MCP error -32000: Connection closed"), and resolved by restarting the background service from a shell with Node 24 first on PATH. Reading the registry took a throwaway probe plugin that wrote `ctx.skill.list()` to a file, after three CLI and HTTP routes returned nothing useful; that probe is the technique to reach for again, because it asks the host what it holds rather than asking a test what it thinks the host holds.', NULL, NULL, '01M1ACQM2C6KWX1W5CCQZKVYQH', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: the probe-before-the-CLI habit and the OpenCode host facts behind it were relied on across retros 02 and 03, and they are knowledge about the host rather than a lesson about a run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19MRYF83D901P55M6BE2WCT', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194E73NGKXF2ZJYSE0S5GZ3', NULL, NULL, 6, 'A real oracle for the tool surface was already on this machine and nearly went unused. Criterion 3 asks the advertised set and every schema to match v0.7.0 "against a stored snapshot", and the obvious move — generate the snapshot from the port and commit it — produces a self-portrait: it would pass on the day it was written and go on passing through any consistent drift, which is precisely the failure `parity-v070.test.js` was written to name. What made it a genuine comparison is that the released v0.7.0 is installed at `~/.claude/plugins/cache/ninthspace-marketplace/dpm/0.7.0/`, so `bin/dpm-mcp.js` from the *release* could be run and its `tools/list` reply captured. The two surfaces came back byte-identical at 168,465 bytes — 183 tools, every description, every schema — which is a far stronger result than a self-generated snapshot could ever have reported, and it cost one command. The oracle then joined `v070-dump.sql` under the existing must-NOT against rewriting a fixture, and tripped `fixtures.test.js`''s rule that no fixture is a parseable document; that rule was narrowed by naming the two oracles individually rather than exempting an extension, because an extension-shaped hole would let a corpus arrive as JSON. The lesson: before generating an expected value, look for a copy of the thing being ported.', NULL, NULL, '01M1ACQH5P4XHAT87SQZNBKM9K', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: "find the oracle before generating the expectation" proved out three times across retros 01, 02 and 03, so it belongs where every run reads it rather than where it is re-judged.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19NF6TMZWAQGFK9KC1FBACQ', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194E8W7MJQ0WMEANHJ3YRZQ', NULL, NULL, 7, 'The story was framed as a yes/no question about the host — does a registered skill''s `location` let it reach a sibling file — with a fallback prepared for "no". Neither branch was taken, because the question turned out to be answerable on our own side: substituting the absolute path at registration means the host''s behaviour stops mattering. The half-hour spent trying to make the host answer it was the part that was wasted, and it was spent first: executing the built-in `skill` tool from a probe failed schema validation on a hand-built `Tool.Context` with branded ids, several HTTP and CLI routes returned HTML or nothing, and the local model provider was unreachable. Three dead ends before asking whether the question needed answering at all.

The prepared fallback was what made the wrong branch attractive. Inlining 15KB into twenty-three bodies was written into the story as the negative case, so it read as the sanctioned answer rather than as the expensive one — and its worst cost was not the duplication but that it would have broken `tests/support/skills.js`''s per-procedure tool resolution, which nobody would have noticed until a skill''s tool sweep started passing for the wrong reason. A specification that names a fallback is naming what was thinkable when it was written, not what is best once the ground is known.

One reading error worth keeping. The first check that the substitution had worked reported twenty-three bodies still carrying an unresolved `dpm/shared/` reference, against a set that had none: the resolved absolute path ends `.../opencode-dpm/shared/skill-conventions.md`, which contains the literal the search was for. A sweep looking for the thing it replaced has to be run against text the replacement has been taken out of — the same false-report shape as the `import type` readings in story 1, arriving from the opposite direction.', NULL, NULL, '01M1ACQJD8SR4B6P8SPQCET4R6', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: substring matching produced a false result four times across retros 02 and 04 and one bug latent since v0.7.0, which makes it a coding standard rather than a recurring discovery.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19NX65EB4CAT11ZM65WMVJA', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194EA95B25V3M2MCBC35A1J', NULL, NULL, 8, 'The story''s four criteria were written against a package that would hold one runtime dependency. It holds none — story 1 established that `Plugin.define` is the identity function and took the SDK `import type` — so two of the four had to be amended before anything could be built against them, and the amendments were bigger than a rewording: "exactly one entry under `dependencies`" became "empty", and with it the whole story got easier. There is no production install tree to sweep for a native binary, because `npm ci --omit=dev` creates no `node_modules` at all.

That is the second time this epic that a criterion arrived carrying an assumption from before the SDK was opened, and both times the copy was found by reaching the story rather than by looking for it. NFR1 was amended in story 1; its two copies in story 4 sat unamended for three stories, and one coverage row was still quoting the sentence that had been amended away — a binding to text that no longer exists in the requirement, which reads as covered and is not. Amending a requirement should be followed by asking what else quotes it, and the tools make that a one-call question.

The verification split cleanly into what this machine can show and what it cannot, and saying so was more useful than a verdict. The clean install was run with `PATH` cut down to Node''s own `bin` — no `cc`, `gcc`, `g++`, `make`, `python`, `python3`, `node-gyp` or `clang` reachable — and it completed, compiled nothing, and left no `build/Release`. What it is not is the container: this machine has no runtime for one, and the image''s claim is stronger, because there the toolchain is absent from the system rather than hidden from the process. The container run is genuinely outstanding, and recording it as outstanding costs nothing next to a green tick that would have to be walked back.

`msgpackr-extract` earned its second mention. It is the one package in the lockfile declaring an install script, and the tempting assertion — "no install script anywhere" — would have been false the day the SDK arrived and would have read as a regression rather than as a discovery. The true and narrower claim is that it is `dev` and its prebuilts are `optional`, so it never runs for a user and never compiles for a contributor whose platform has a prebuilt.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19PG05589PR72WGVY9CC2RY', '01M19PKK0012R8QQZ86813ATB5', 'retro', '01M194EBJHMAV5E7KCK0PA0GKF', NULL, NULL, 9, 'The integration story found one real defect, and it was in my own recorded knowledge rather than in the code. Story 1''s finding was written down as "the project config key is `plugins`", which is true and incomplete: the value is an array of `string | { package, options }`, and the map form I wrote from that note was discarded by the host with a normalisation diagnostic and no error. Twenty minutes went into "the plugin will not load" before reading `@opencode-ai/schema/dist/config/plugin.js`, where the shape is four lines. A note that records a key without its type is a note that will be misread, and the schema was two directories from where I was already working.

The host''s own CLI is not a trustworthy first answer. `mcp list` and `plugin list` report "No MCP servers configured" and "No plugins found" for a second or two after `service start`, then report correctly and stably — while the log shows the plugin loading the whole time and a probe running inside the host sees the full registry. Both of my false "it is not loading" conclusions today came from believing a first CLI answer. The probe plugin has now been the reliable instrument four times in this epic, and the CLI has been misleading twice; the ordering should have been obvious sooner.

The reload check needed a control and the control changed the result''s meaning. Touching the watched entry file left the registry unchanged, which looked like a pass and was not evidence of anything — the log showed no reload had occurred, so I had measured a registry that had not been disturbed. Restarting the service and counting `loading plugin` lines for the entry gave 2, and only then does "55 skills, 23 dpm, 0 duplicates, unchanged" mean the registrations survived something. This is the same false-pass shape the suite is built around, arriving in a manual check where there is no test file to remind you.

What the run confirmed is worth stating plainly because three stories were building toward it without ever seeing it together: 183 tools, the exact count of the v0.7.0 oracle, all prefixed `dpm_` and none carrying the old form; 23 skills whose conventions path is absolute and opens; one connected server. Every piece had been verified separately and the composition had not been, and the composition is the thing a user actually installs.', NULL, NULL, '01M1ACQM2C6KWX1W5CCQZKVYQH', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: the probe-before-the-CLI habit and the OpenCode host facts behind it were relied on across retros 02 and 03, and they are knowledge about the host rather than a lesson about a run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19PKYHHE62Q1Y3Z8C5NTSDW', '01M19PKK0012R8QQZ86813ATB5', 'retro', NULL, NULL, NULL, 0, '**A duplicated reading fails silently in the direction of a false report, and this epic hit that shape six times.** Four separate readings of the import graph existed and only one knew `import type` is erased; the `.node` sweep walked `node_modules` and read a dev package''s prebuilt as something dpm ships; CI''s grep matched the *name* `node-gyp-build-optional-packages` rather than the act of compiling; `plugin.test.js` carried a private copy of the `package.json` read that `sources.js` exists to be. None of these was a broken property — every one was a second reading that had not been taught what the first had learned, and each failed by reporting a problem that did not exist or missing one that did.

**Why it matters more here than in ordinary code**: a test''s job is to be the thing that notices, so a reading that has silently stopped noticing is the one defect the suite cannot catch. Consolidating onto one reader fixed six failures at their source in a single edit, and the two remaining copies were only found because a story happened to touch them.

**How to apply**: when a helper is written to end a duplication, migrate every caller in the same change, and when a shared reader already exists, treat a private copy of the same read as a defect on sight rather than as style. Before writing an assertion over an artefact, grep for who else reads that artefact.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19PMJBXJHP9G40P8RGB1HB3', '01M19PKK0012R8QQZ86813ATB5', 'retro', NULL, NULL, NULL, 1, '**Ask the host what it holds; do not ask a test what it thinks the host holds — and do not believe the host''s CLI on the first answer.** A throwaway probe plugin that writes `ctx.skill.transform(draft => draft.list())`, `ctx.mcp.transform(draft => draft.list())` and `ctx.tool.transform(draft => draft.list())` to a file was the instrument that answered four separate questions this epic could not otherwise settle: the rendered tool-name form and its character substitution, whether `location` and `content` are stored verbatim, the full registered set, and whether a reload duplicates.

Against that, `opencode2 mcp list` and `plugin list` produced two false "it is not loading" conclusions, because both report nothing for a second or two after `service start` while the log shows the plugin loading throughout. Three CLI and HTTP routes to the same information returned HTML, nothing, or a schema-validation failure on a hand-built `Tool.Context`.

**How to apply**: for any question about a running host''s registry, write the probe first rather than after exhausting the CLI. Run any CLI listing twice before believing it. And when the answer disagrees with expectation, read the host''s log before concluding the code is wrong — every genuine misconfiguration in this epic announced itself there as a normalisation diagnostic while the CLI stayed silent.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19PMSVAG7DT2RR68AFSTVS6', '01M19PKK0012R8QQZ86813ATB5', 'retro', NULL, NULL, NULL, 2, '**A specification written before the dependency was opened carries assumptions into every story that quotes it, and amending one copy does not amend the others.** Four criteria and one requirement across three stories were amended in this epic, all from the same discovery — `Plugin.define` is `define(plugin) { return plugin }`, so the SDK is a type-only import and `dependencies` stays empty. NFR1 was amended in story 1; its two copies in story 4''s criteria sat unamended for three stories, and a coverage row was still quoting the sentence that had been amended away, which renders in the matrix as a verified binding to text the requirement no longer contains.

The second family was the same shape from a different source: story 4''s "pinned to the `beta` tag" (a tag is not a pin), and story 2''s naming criteria written against Claude Code''s `mcp__plugin_<plugin>_<server>__` form. Every amendment had a citation and none was a relaxation — NFR1''s headline got *stronger*, from one runtime dependency to none.

**How to apply**: after amending a requirement, immediately ask what else quotes it — `list_coverage` on the requirement names every binding, and a bound fragment that is no longer a substring of the requirement is a broken binding whatever its verified date says. Before building against a criterion that names a mechanism rather than a property, check the mechanism still exists; retro 01 flagged that pattern and it recurred here three times.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19PN4YEPAP09S02P0SDYNMZ', '01M19PKK0012R8QQZ86813ATB5', 'retro', NULL, NULL, NULL, 3, '**Before generating an expected value, look for a copy of the thing being ported — and before recording a manual check as passed, look for what would have shown it failing.** Two halves of one discipline, and both changed a result in this epic.

The oracle: criterion "match v0.7.0 against a stored snapshot" invited generating the snapshot from the port, which is a self-portrait that passes on the day it is written and through any consistent drift afterwards. The released v0.7.0 was installed on the machine, so its `bin/dpm-mcp.js` was run and its real `tools/list` reply captured — 183 tools, byte-identical at 168,465 bytes. One command, and a far stronger claim.

The control: the reload check first "passed" by touching the watched entry file, which left the registry unchanged — but the log showed no reload had happened, so nothing had been measured. Restarting the service and counting `loading plugin` lines gave 2, and only then did "55 skills, 23 dpm, 0 duplicates" mean anything. The same shape appeared in the substitution check, where a search for the replaced string matched inside the absolute path that replaced it and reported 23 failures against a set with none.

**How to apply**: for a port, the previous version is an oracle and is usually still installed. For any manual check, name the evidence that the event under test actually occurred, and state it beside the result — a count in a log, a control write, a planted breach. An absence is only an observation when something was watching.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19SFYZD8WN9WFTCF8BKK1K8', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V4CBNMW9KRVBHS83R3DM', NULL, NULL, 0, 'The pilot''s biggest cost was not the rename — it was that `tests/support/skills.js` derived its callable prefix from the Claude Code manifest and 40 test files read bodies through it. Rewriting one skill made five other test files fail in shapes that had nothing to do with the skill: bodies reporting no tools at all, a classification registry reporting every site stale, a manifest test pairing a derived prefix with a literal that had quietly become the wrong one. The fix was to make the transition a first-class object — `CALLABLE` derived from the plugin entry, `LEGACY_CALLABLE` beside it, `EITHER_CALLABLE` as the exported alternation every reader matches on, and `bodiesOnLegacyForm()` asserted against the exact list of skills not yet done — so the dual-form matcher cannot silently accept an unported body. Story 2 should expect the same shape: the batch pass is 424 substitutions and roughly zero decisions, and what will take the time is the assertions written against the old form in files nobody thinks of as skill-port files.', 'Both estimates were made about the change and both costs landed in the apparatus that observes the change. Renaming 28 strings in one skill body was the cheap part of story 1; the expensive part was a test support module that derived its callable prefix from the Claude Code manifest and that 40 files read bodies through. Walking an invocation was the cheap part of story 5; the expensive part was a probe that could not report. And both failed in the same direction — bodies reporting no tools, a classification registry reporting every site stale, `ctx.skill.transform` returning a `Registration` with no registry in it, a probe writing no report at all. Every one of those presents as *there is nothing here*, which is indistinguishable from a genuine absence and is therefore read as a result rather than as a broken instrument. The transferable rule is two-part: estimate the observability of a change alongside the change, and treat any empty reading as unproven until a control has shown the instrument can produce a non-empty one.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19SGCN380AZP3N5VK1AVYTE', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V4CBNMW9KRVBHS83R3DM', NULL, NULL, 6, 'Epic 01-02 chose registration-time path substitution over inlining the conventions into 23 bodies, and priced the fallback. What neither option was priced against turned up the first time a real session tried to follow the substituted path: opencode2 refused the read — `permission requested: external_directory (/Users/chris/Work/git/opencode-dpm/shared/*); auto-rejecting` — because the package lives outside the project the session runs in, so every one of the 23 bodies points at a file the host treats as external. Interactively the user is prompted; non-interactively the read simply fails unless the project sets `permission.external_directory`. The decision still looks right, but it now carries an installation obligation that belongs in epic 01-04''s guidance, and it is a reminder that a design verified against the registry is not the same as one verified against a session actually doing what the registration told it to.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19VSVSXYWDGGVXPD4SWP9YX', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V5Q15F8TQR44DPVPJBRY', NULL, NULL, 5, 'The rewrite was mechanical in twenty-two bodies and not a rewrite at all in the twenty-third. `ralph` does not name a Claude Code path that needed substituting — it is built end to end on a stop-hook contract it describes fourteen times, and that hook was never shipped even by released v0.7.0, whose `hooks/` holds a `pre-commit` and nothing else. So the port met a missing capability wearing the costume of a find-and-replace. The story''s own planning had flagged it (story 1 task 3 wrote it into the epic section precisely so story 2 would meet it as a decision), and that flag is the only reason it cost a question rather than a silent path substitution that would have left a skill reading as ported and unable to work.', NULL, 'Resolved by keeping ralph registered and recording the must-NOT unmet for it alone — the smallest amendment surface, since excluding it would have forced amending three criteria that say "twenty-three". The v2 loop mechanism is unbuilt and unowned.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19VT4A23CHQTSBACRXG8KQZ', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V5Q15F8TQR44DPVPJBRY', NULL, NULL, 2, 'A 549-edit mechanical rewrite across twenty-three files was made auditable by inverting it: reverse-substituting `dpm_` back to `mcp__plugin_dpm_dpm__` and diffing each body against the released v0.7.0 copy gave 0 differing lines for all twenty-two batch bodies and for `shared/skill-conventions.md`, and 6 for the pilot — the three intentional line pairs. That is a far stronger claim than "the tests still pass", because it says what was *not* touched: no procedure prose, no gate wording, no table. The technique needs a byte-identical oracle to invert against, which this port has and which most refactors do not.', 'Both are the same move made in two places: stop a claim from resting on something the change itself rewrote. The port could not honestly say "no procedure prose was touched" on the strength of a suite that was being edited alongside the bodies, so the claim was anchored outside the change — reverse-substitute `dpm_` back to the old prefix and diff against the byte-identical v0.7.0 release, giving 0 differing lines across 22 bodies and 6 intentional ones in the pilot. The prohibition check could not honestly say CI enforces the rule the test sweeps for if each held its own copy of the list, so the two were made one object: `HOST_MECHANISM` is defined in the script CI runs and imported by the test that sweeps with it. Either anchor externally or collapse to a single definition — what neither observation says alone is that both were reached by asking *what could make this claim agree with itself*. Both also carry their own limit, which is why they are patterns rather than rules: the oracle technique needs a byte-identical oracle most refactors do not have, and it stays a manual check because `vendoring.test.js` forbids any source from naming the marketplace checkout.', 'Stays a manual check: `vendoring.test.js` forbids any source from naming the marketplace checkout, so it cannot become a test without a test that silently passes when the released copy is absent.', '01M1ACQH5P4XHAT87SQZNBKM9K', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: "find the oracle before generating the expectation" proved out three times across retros 01, 02 and 03, so it belongs where every run reads it rather than where it is re-judged.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19WXKMW56XWN8EWFEV2JXRT', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V710KP0J5V188YR3EBDX', NULL, NULL, 4, 'Story 2''s must-NOT listed four Claude Code mechanisms — `mcp__plugin_`, `/dpm:`, `CLAUDE_PLUGIN_ROOT`, `.claude/` — and a fifth was in all twenty-three bodies the whole time. `$ARGUMENTS` is the *argument half* of the same slash-command mechanism: the harness substituted the user''s typed text into the body before the model saw it, so the token was a hole the host filled and v2 fills with nothing. It survived a pass that was looking for exactly this class of thing because a prohibition written as a list of strings can only catch the strings someone thought of. The failure it would have caused is the quiet kind — a literal `$ARGUMENTS` sits in a sentence that still reads as an instruction, so a model does not error on it, it invents a value.', NULL, 'Found by asking what "invocation prose" meant beyond the descriptions rather than accepting that story 2 had already satisfied the criterion. The lesson generalises past this port: an enumerated must-NOT is a checklist, not a sweep, and the next epic''s prohibitions are worth re-deriving from the mechanism rather than copied from the last list.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19X968MX1P6AVTK4J73YQEC', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V89DXC10121AWAN7KZ5N', NULL, NULL, 3, 'The story asked for a CI check, and the suite already read both rules — so the temptation was to call it done and add a workflow line pointing at `npm test`. What makes the separate check worth its cost is not enforcement in the abstract but *where the failure lands*: this is the rule a contributor breaks while doing something else entirely, writing a skill body, in a file whose nature says nothing about being under a prohibition. A named step puts the rule''s name in the output instead of a test''s. The same reasoning is already on the record for the module sweep, which is separate from the suite for the mirror-image reason — a suite reaches a module by importing it, so it cannot speak for one nothing imports.', 'Both are the same move made in two places: stop a claim from resting on something the change itself rewrote. The port could not honestly say "no procedure prose was touched" on the strength of a suite that was being edited alongside the bodies, so the claim was anchored outside the change — reverse-substitute `dpm_` back to the old prefix and diff against the byte-identical v0.7.0 release, giving 0 differing lines across 22 bodies and 6 intentional ones in the pilot. The prohibition check could not honestly say CI enforces the rule the test sweeps for if each held its own copy of the list, so the two were made one object: `HOST_MECHANISM` is defined in the script CI runs and imported by the test that sweeps with it. Either anchor externally or collapse to a single definition — what neither observation says alone is that both were reached by asking *what could make this claim agree with itself*. Both also carry their own limit, which is why they are patterns rather than rules: the oracle technique needs a byte-identical oracle most refactors do not have, and it stays a manual check because `vendoring.test.js` forbids any source from naming the marketplace checkout.', 'The consolidation that fell out is the part worth keeping: HOST_MECHANISM is defined in the script CI runs and imported by the test that sweeps with it, so the reading and the enforcement of that reading cannot disagree. Restating the list in both would have put the copy CI ran in the file nobody reads.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19XN46BYP1KJSWEK5EE20B5', '01M1ABMF2GJVS45PYQ2H6WCVW1', 'retro', '01M194V9HR3KH3XB66JEG6651N', NULL, NULL, 1, 'Seven attempts to execute the invocation walk failed, and six of them failed silently — the probe wrote no report at all, which reads identically to a probe that never ran. Two host facts came out of it that are worth more than the walk would have been. Plugins load **lazily**: a freshly started server has registered nothing until a request asks it to, so a probe that starts and reads immediately sees an empty world. And `ctx.skill.transform(cb)` returns a `Registration` carrying only `dispose` — **not** the callback''s value — so a probe that reads the return value gets an empty registry, which is indistinguishable from a host that registered nothing. Both failure modes present as "there is nothing here", which is the shape that costs the most time: the probe was reporting a broken host when it was reporting a broken probe.', 'Both estimates were made about the change and both costs landed in the apparatus that observes the change. Renaming 28 strings in one skill body was the cheap part of story 1; the expensive part was a test support module that derived its callable prefix from the Claude Code manifest and that 40 files read bodies through. Walking an invocation was the cheap part of story 5; the expensive part was a probe that could not report. And both failed in the same direction — bodies reporting no tools, a classification registry reporting every site stale, `ctx.skill.transform` returning a `Registration` with no registry in it, a probe writing no report at all. Every one of those presents as *there is nothing here*, which is indistinguishable from a genuine absence and is therefore read as a result rather than as a broken instrument. The transferable rule is two-part: estimate the observability of a change alongside the change, and treat any empty reading as unproven until a control has shown the instrument can produce a non-empty one.', 'The instrumentation lesson is the transferable one: everything was written at the end of the run, so a hang anywhere produced no evidence about where. Writing the report incrementally — after the registry read, after the session, after each row — was added on the seventh attempt and would have identified the hang on the second.', '01M1ACQFRJ0JVFMTFZQE1BA665', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: the control-for-every-absence discipline recurred in retros 01, 03 and 05, so it is now standing guidance read at startup rather than a lesson re-judged each run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19Z0XXBFFZA4S7MECMTXQTC', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1951C1R30C8CQABYF7YZJ82', NULL, NULL, 0, '**The port swept `skills/` for host mechanisms and never swept `src/`, and the guard is the one module in `src/` that writes prose a user acts on.** `describe()`''s divergence branch ended `or run /dpm:publish if you are already in a session` — a Claude Code slash command v2 does not mint — and it survived three epics of the port, including the epic that built a CI check for exactly this class of string. The check walks `skills/` and `shared/` because that is where the criterion pointed; nothing asked whether the prohibition had a second home. It is printed at the moment a reader is most likely to type what they are told, since the commit they just made was refused.

**Two smaller findings came out of fixing it, and the second is the reusable one.** First, the comment references that remain (`/dpm:templates`, `/dpm:do`, `/dpm:epics` in `src/tools/cross/template.ts`, `src/coverage/warrant.ts`, `src/preview/example.ts`) are stale in the same way but are JSDoc rather than output, and no story in this epic covers them.

Second: matching the message against the bare skill id `dpm-publish` reported the skill as offered in the one refusal that must not offer it, because `dpm-publish` is a substring of `bin/dpm-publish.ts`. Three assertions were written that way and one passed for that reason. Retro 02 recorded the same shape from the other side — a search for a replaced string matching inside the absolute path that replaced it. The fix was to export the *phrase* rather than the id and match on that, so a caller asking "does this message offer the publish skill" cannot be answered by a path.

**How to apply**: when a prohibition is enforced over one directory, ask what else in the tree produces the same kind of artefact before recording the rule as enforced. And when a new identifier is a substring of an existing path, the identifier is not a safe thing to match on — export the phrase that contains it.', '**Codebase discoveries.** All three are the same failure of coverage: the port handled the mechanism where a criterion pointed, and the mechanism had a second home nobody asked about. The prohibition on Claude Code strings was enforced over `skills/` and `shared/` because that is where the criterion pointed, and the guard — the one module in `src/` that prints prose a user acts on — ended its divergence message with `/dpm:publish`, surviving three epics including the one that built the CI check for exactly that string. The migration instruction was rewritten for the new package path, and the *sort* over that path was broken too, because an OpenCode package directory is a sha256 of the literal specifier string and carries no version to order by. The permission draft named the skill axis and the tool axis and still recommended a rule on the first as though it governed the second, when loading a skill is `skill` with the skill id as resource and running a dpm tool is the tool''s own name as the action — no overlap, and 183 separate tool actions doing the writes. In each case the second surface is the one a *user* touches: advice they retype after a refusal, an upgrade command they run, a config they write believing publishing is covered. What none of the three says alone is that the criterion names where the team was looking, not where the mechanism lives — so a rule recorded as enforced is worth one more question: what else in this tree produces the same artefact for a reader?

**Testing gaps.** Both are assertions that passed for the wrong reason and were indistinguishable from passing for the right one. Matching a refusal message against the bare skill id `dpm-publish` reported the skill as offered in the one refusal that must not offer it, because `dpm-publish` is a substring of `bin/dpm-publish.ts` — three assertions were written that way and one passed for that reason alone. Searching the README for the beta callout by its own opening sentence found the TL;DR''s shorter restatement instead, so the test was right that its match failed and wrong about what it had matched, and the failure named two sections without naming either. Retro 02 recorded this shape from the other side — a search for a replaced string matching inside the absolute path that replaced it — which makes this the third instance and no longer a coincidence. The fix was the same both times and is the transferable part: stop matching on a string that something else in the tree can contain, and match on structure the artefact actually has. Export the *phrase* rather than the id, so "does this message offer the publish skill" cannot be answered by a path. Extract the blockquote and assert there is exactly one, rather than searching for prose a document deliberately says twice at different lengths.', NULL, '01M1ACQJD8SR4B6P8SPQCET4R6', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: substring matching produced a false result four times across retros 02 and 04 and one bug latent since v0.7.0, which makes it a coding standard rather than a recurring discovery.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M19ZHE2YSQB357FDEPCS9355', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1951DJH04XXS5ZN0Z3GBDSB', NULL, NULL, 1, '**The install could be done for real without touching the machine, and that changed what the story was allowed to conclude.** `opencode2 plugin add` writes to the global configuration, which is the user''s live setup — so pointing `XDG_CONFIG_HOME`, `XDG_DATA_HOME` and `XDG_CACHE_HOME` at a scratch directory bought a genuine `plugin add` against the real GitHub remote with no side effect to undo afterwards. The criterion asked for a real install and got one; nothing had to be inferred from documentation.

**The location turned out to be derivable, and checking that was worth more than reading it.** The package lands at `$XDG_CACHE_HOME/opencode/packages/git-<hash>/node_modules/opencode-dpm/`, and `<hash>` is sha256 of the literal specifier string — `sha256("github:ninthspace/opencode-dpm")` matches the directory name byte for byte. Confirmed from the other direction by installing `github:ninthspace/opencode-dpm#main`, the same repository under a different string, which produced a *second* directory. So the hash is over the text somebody typed, not over the repository or the resolved commit.

**That killed the old instruction rather than relocating it.** The Claude Code form ended `sort -V | tail -1`, which sorted a version out of the path. There is no version in an OpenCode package path, and sorting hex digests orders nothing — so the replacement sorts by modification time. The same fact reaches the guard: `src/guard/main.ts` refuses a database from a newer release and explains it as "an upgrade installs beside the previous release rather than over it", which is Claude Code''s mechanism. The refusal stays reachable — two specifiers for one repository give two installs of different ages — but the sentence explaining why no longer describes the ordinary case.

**Two probes returned nothing and were recorded rather than chased**, per the bound this run put on host probing: `opencode2 plugin list` said "No plugins found" twice against a configuration declaring two, and the host log shows only CLI starts and no plugin load. The control is uninformative — the machine''s real configuration declares no plugins, so the same answer there is correct — so the section says what it establishes (where a git install lands) and explicitly not what it does not (that a plugin registers from there).

**How to apply**: an XDG-rooted scratch turns "install it for real" from a change to the user''s machine into an ordinary test fixture, and it should be the first thing reached for when a criterion asks for a real install. And when a path stops carrying a version, every instruction that *ordered* by that path is broken rather than merely relocated — grep for the sort, not only for the prefix.', '**Codebase discoveries.** All three are the same failure of coverage: the port handled the mechanism where a criterion pointed, and the mechanism had a second home nobody asked about. The prohibition on Claude Code strings was enforced over `skills/` and `shared/` because that is where the criterion pointed, and the guard — the one module in `src/` that prints prose a user acts on — ended its divergence message with `/dpm:publish`, surviving three epics including the one that built the CI check for exactly that string. The migration instruction was rewritten for the new package path, and the *sort* over that path was broken too, because an OpenCode package directory is a sha256 of the literal specifier string and carries no version to order by. The permission draft named the skill axis and the tool axis and still recommended a rule on the first as though it governed the second, when loading a skill is `skill` with the skill id as resource and running a dpm tool is the tool''s own name as the action — no overlap, and 183 separate tool actions doing the writes. In each case the second surface is the one a *user* touches: advice they retype after a refusal, an upgrade command they run, a config they write believing publishing is covered. What none of the three says alone is that the criterion names where the team was looking, not where the mechanism lives — so a rule recorded as enforced is worth one more question: what else in this tree produces the same artefact for a reader?

**Patterns worth reusing.** Both take something the project had been treating as unverifiable and make it an ordinary fixture, and both pair it with a check in the opposite direction so the fixture cannot go quiet. Pointing `XDG_CONFIG_HOME`, `XDG_DATA_HOME` and `XDG_CACHE_HOME` at a scratch directory bought a genuine `opencode2 plugin add` against the real GitHub remote with nothing to undo on the user''s machine — a real install as a test fixture rather than a fact inferred from documentation. Enumerating every fenced block in the README, classifying each by a rule and executing it turned documentation into something that can fail, and it found three defects reading could not: `git config core.hooksPath` exiting 1 on the very outcome the documented check is looking for, `sh` rejecting `dpm-link()` because POSIX forbids a hyphen in a function name, and the anchored-prose match recorded under testing gaps. The second half is what keeps either honest. An unmatched block fails **and** a rule matching nothing fails, so a rewrite that deletes a command cannot leave a rule guarding an empty set and a sweep reporting clean. The same discipline was applied to what the scratch install could *not* establish: `plugin list` returning "No plugins found" was recorded as uninformative rather than as a negative, because the control returns that same answer when it is correct. A fixture that can only ever agree with you is not evidence; both of these were built with the disagreeing case inside them.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A01FWXJF076P74V5JK4E7C', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1951FE5F4G1PTK9BF5WNW7Q', NULL, NULL, 4, 'The story''s first criterion has an empty antecedent — "anything that was per-session scratch keyed by an environment variable uses ctx.storage" — and the audit found the antecedent empty. That shape passes by doing nothing, and it passes identically whether the sweep found nothing, the sweep read nothing, or the regex quietly stopped matching. Three different facts, one empty array. What made the difference was refusing to assert the negative: `session-scratch.test.js` enumerates the environment reads, holds the set equal to a written classification table, and drives the reading against three planted sources including a commented-out one. A new `process.env.X` now fails until somebody classifies it, so the empty antecedent stays checked rather than merely being true today.

Two things fell out of doing it that way. The exemption the conclusion leans on — "where a database session row is not already the answer" — is only a defence if the row exists and carries state, so that became its own test rather than an assumption in a comment; the sweep alone would be equally empty in a release that had lost sessions altogether. And the classification is written down rather than derived, because a variable''s name says nothing about whether it holds state between calls; what is mechanical is only that the two sets match.

Left open and not claimed: `DATABASE` is a relative path, so which directory OpenCode gives a spawned local MCP server as its cwd decides which repository `.dpm/` lands in. Every test here runs the server against an explicit root, so nothing here reaches that question — it is a fact about the running host, of the same class as the ones epic 01-04 story 4 and the `target` criteria elsewhere leave to the deployment.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A1GF43BMAS62WJAZK2PZ26', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1951J6PTV1WPNCCCF58J3TD', NULL, NULL, 2, 'The story''s first README draft recommended putting `ask` on `skill`/`dpm-publish`, and the review that killed it asked one question: why would anyone deny a skill in this repository? They are all meant to be used. That is right, and the draft had drifted into demonstrating a mechanism rather than advising a reader — the criterion says "documents the recommended permission entries", and I had answered "documents the permission entries I had just learned how to exercise". Not the same thing. What survived is an allow-list for the one case that needs configuration, plus the confirmation moved onto `dpm_publish`, the tool that actually unlinks. The `deny` prose stays but is now framed as something met — inherited config, restricted agent — rather than something chosen.

The finding underneath it is worth keeping whatever the wording: loading a skill is the action `skill` with the skill''s **id** as the resource, while running a dpm tool is the tool''s own name as the *action*. Two axes, no overlap. A rule on one is invisible to the other, so the intuitive "gate the skill and its work is gated" is precisely wrong — the skill rule governs whether a procedure is read, and the writes happen under 183 separate tool actions. That is the section''s whole reason to exist, and it is also why the first draft was dangerous rather than merely unnecessary: it named both halves and would have left a reader confident they had covered publishing.

Three probe runs produced nothing at all before the host log gave the cause: `Duplicate plugin ID: dpm`. Story 2''s install had left two git specifiers in the scratch global config, and with the project config''s local path that is three plugins claiming one id — which kills the *entire* plugin load rather than the duplicate, so a working probe presents as a hung one. Worth carrying: a scratch fixture built by an earlier story is state the next story inherits, and this one had no symptom pointing at it.

Where the story declined to automate: the two behavioural criteria are `manual`, and this project has always been tested by hand. A test asserting the host''s permission semantics would assert my transcription of them and pass just as well when the transcription is wrong. So the test file checks the thing a person cannot recheck every commit — that every documented rule names a skill or tool that exists — and leaves the behaviour to the probe. The transcribed glob matcher is the one thing there taken on trust, and it is named as such in the file.', '**Codebase discoveries.** All three are the same failure of coverage: the port handled the mechanism where a criterion pointed, and the mechanism had a second home nobody asked about. The prohibition on Claude Code strings was enforced over `skills/` and `shared/` because that is where the criterion pointed, and the guard — the one module in `src/` that prints prose a user acts on — ended its divergence message with `/dpm:publish`, surviving three epics including the one that built the CI check for exactly that string. The migration instruction was rewritten for the new package path, and the *sort* over that path was broken too, because an OpenCode package directory is a sha256 of the literal specifier string and carries no version to order by. The permission draft named the skill axis and the tool axis and still recommended a rule on the first as though it governed the second, when loading a skill is `skill` with the skill id as resource and running a dpm tool is the tool''s own name as the action — no overlap, and 183 separate tool actions doing the writes. In each case the second surface is the one a *user* touches: advice they retype after a refusal, an upgrade command they run, a config they write believing publishing is covered. What none of the three says alone is that the criterion names where the team was looking, not where the mechanism lives — so a rule recorded as enforced is worth one more question: what else in this tree produces the same artefact for a reader?', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A2N7F530TKPZ7593WDND5B', '01M1ABW515ZXDD7XEVEANRSWH0', 'retro', '01M1951GSMQ3JY8MJAX204ZEY0', NULL, NULL, 3, '**Running the README found three defects that reading it could not.** The commands were not transcribed into the test and asserted; every fenced block was enumerated, classified by a rule, and executed. What that turned up: `git config core.hooksPath` exits 1 when the key is unset, which is the outcome the documented check is *looking for*; `sh` rejects `dpm-link()` as a syntax error because POSIX forbids a hyphen in a function name, so a block correct for the `.zshrc` it was written for is invalid in the shell a test runner reaches for by default; and the beta callout could not be located by searching for its own opening sentence, because the TL;DR says the same thing in a shorter form and the anchored match found that one — reporting the entrypoints warning missing from a paragraph that was never supposed to carry it.

The third is the one worth keeping. **The test was right that its match failed and wrong about what it had matched**, and nothing in the failure said so — it named two sections and neither of them by name. A search anchored on prose finds the first instance of that prose, and a document that deliberately says a thing twice at different lengths has more than one. The fix was to stop searching: the callout is a blockquote, so it is extracted as one, with an assertion that there is exactly one blockquote in the file. Structure the document actually has, rather than a phrase it happens to contain.

**Two of the three would have passed as documentation defects if the rule had bent instead.** Accepting any non-zero exit would have hidden every genuinely broken command; switching the block to `bash` without saying so in the README would have left a reader pasting non-POSIX syntax into a POSIX shell with a syntax error and no explanation. So both are declared at the rule with a reason the test asserts is present, and the shell case additionally requires the README itself to name the shell — the rule cannot quietly absorb a gap in the prose it is checking.

**The enumeration is what makes the file worth having**, and it fails in both directions: an unmatched block fails, and a rule matching nothing fails too. Without the second, a rewrite that removed a command leaves a rule guarding an empty set and the sweep reporting clean.', '**Testing gaps.** Both are assertions that passed for the wrong reason and were indistinguishable from passing for the right one. Matching a refusal message against the bare skill id `dpm-publish` reported the skill as offered in the one refusal that must not offer it, because `dpm-publish` is a substring of `bin/dpm-publish.ts` — three assertions were written that way and one passed for that reason alone. Searching the README for the beta callout by its own opening sentence found the TL;DR''s shorter restatement instead, so the test was right that its match failed and wrong about what it had matched, and the failure named two sections without naming either. Retro 02 recorded this shape from the other side — a search for a replaced string matching inside the absolute path that replaced it — which makes this the third instance and no longer a coincidence. The fix was the same both times and is the transferable part: stop matching on a string that something else in the tree can contain, and match on structure the artefact actually has. Export the *phrase* rather than the id, so "does this message offer the publish skill" cannot be answered by a path. Extract the blockquote and assert there is exactly one, rather than searching for prose a document deliberately says twice at different lengths.

**Patterns worth reusing.** Both take something the project had been treating as unverifiable and make it an ordinary fixture, and both pair it with a check in the opposite direction so the fixture cannot go quiet. Pointing `XDG_CONFIG_HOME`, `XDG_DATA_HOME` and `XDG_CACHE_HOME` at a scratch directory bought a genuine `opencode2 plugin add` against the real GitHub remote with nothing to undo on the user''s machine — a real install as a test fixture rather than a fact inferred from documentation. Enumerating every fenced block in the README, classifying each by a rule and executing it turned documentation into something that can fail, and it found three defects reading could not: `git config core.hooksPath` exiting 1 on the very outcome the documented check is looking for, `sh` rejecting `dpm-link()` because POSIX forbids a hyphen in a function name, and the anchored-prose match recorded under testing gaps. The second half is what keeps either honest. An unmatched block fails **and** a rule matching nothing fails, so a rewrite that deletes a command cannot leave a rule guarding an empty set and a sweep reporting clean. The same discipline was applied to what the scratch install could *not* establish: `plugin list` returning "No plugins found" was recorded as uninformative rather than as a negative, because the control returns that same answer when it is correct. A fixture that can only ever agree with you is not evidence; both of these were built with the disagreeing case inside them.', NULL, '01M1ACQJD8SR4B6P8SPQCET4R6', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: substring matching produced a false result four times across retros 02 and 04 and one bug latent since v0.7.0, which makes it a coding standard rather than a recurring discovery.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A42P9BAFKY898QEY1NSA8G', '01M1AC4EK1MTJZ74KNA0TPFPY1', 'retro', '01M1957QGCTGTTW0VJP7JHDG74', NULL, NULL, 0, '**The story''s real defect was not in its tasks — it was that the story existed.** The tasks named the version, `files` and `exports`; what was actually wrong was that the epic proposed to claim a permanent name on a public registry for a route the specification defers. FR1 says `opencode2 plugin add github:...` "**and later** the npm form", and *later* had been read as *now* by whoever planned the epic, me included, for four tasks and two coverage bindings before anyone asked why. The user asked, in five words, and the answer took one reading of the requirement.

**Worth carrying: a task list can be entirely correct and still be executing the wrong story.** Nothing in tasks 1 or 3 was wasted — the manifest work and the tarball tests apply unchanged, because the artefact is the same artefact whichever route delivers it. What would have been wasted, irreversibly, is the act the task list did not describe as a decision: `npm publish` reads as a step when it is written between "set the version" and "write the tests", and it is the one line in the epic that cannot be undone. **A step that cannot be reversed should not be a task; it should be a gate.** That is a planning lesson rather than an execution one, and it belongs to whatever writes epics.

**The pivot cost two coverage rows, and one of them was already wrong.** Both quoted the fragment "and later the npm form". The second was bound to story 2''s must-NOT — *the install is verified from the working tree rather than from the package the installer built* — a criterion about where evidence comes from, which was never about npm at all. It had been sitting there unverified since the epic was planned, and the only reason it surfaced is that `list_coverage` on the requirement was the first thing the pivot did. Retro 02 recorded exactly this procedure after an amendment; this is the first time running it found a binding that was wrong for a different reason than the one being fixed.

**And the finding that made the manifest work worth doing regardless.** The package OpenCode had actually installed from the GitHub specifier in epic 01-04 was on disk in the scratch cache: **418 files, 6.4 MB**, the whole repository — `docs/` with this project''s planning corpus, `tests/`, `scripts/`, `.dpm/` with the database dump, and `.claude-plugin/plugin.json`, a manifest addressed to Claude Code shipped inside an OpenCode package. There was no `files` field, and `private: true` from the vendoring commit would have blocked distribution outright. Both were invisible from the manifest alone and obvious the moment the installed artefact was opened — which is the same move as running the README''s commands rather than reading them, one epic earlier.', '**Scope surprises.** Both surprises came out of the artefact rather than the plan, and in both the plan was internally consistent and pointing the wrong way. Story 1''s task list was correct in every task and was executing a story the specification defers: FR1 says the GitHub specifier "**and later** the npm form", and *later* had been read as *now* for four tasks and two coverage bindings before anyone asked — the question that dissolved it was five words long and cost one reading of the requirement. Story 2''s suite was 1,085 tests passing, all of them evidence about the checkout, and the artefact differed from the checkout in the single variable the suite never varied. Neither surprise needed new reasoning; both needed someone to open the object that would actually be delivered. The installed package had been sitting in the scratch cache since epic 01-04 at 418 files, 6.4 MB, carrying `private: true` and a Claude Code manifest; the type-stripping refusal was one spawn away. What neither observation says alone is that an epic''s confidence is bounded by the object it has examined, and until this epic the port had only ever examined the checkout. These are two halves of one surprise — what we ship, and what it does once installed — and they both landed in the last epic because nothing earlier had a reason to open it.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A6THRW6SGNJ4PPJQE61K6J', '01M1AC4EK1MTJZ74KNA0TPFPY1', 'retro', '01M1957TECZSEEFTKG9DNVT7S7', NULL, NULL, 2, 'Three absence criteria, and the work that mattered was choosing the instrument rather than writing the checks.

**The obvious experiment was the weak one.** "Run it with networking disabled" is what the criterion says and what the task was titled, and it answers only half the criterion: a cycle that completes offline has shown it does not *need* the network, not that it did not *try*. A swallowed `ECONNREFUSED` is indistinguishable from never having called, and the criterion''s second clause is "making no outbound connection attempt". So the order was inverted — watch first, then block — and both clauses got their own run. Watching also turned out to be the cheaper of the two to make trustworthy, because a recorder cannot be caught by a `try`/`catch` up the stack the way a thrower can.

**Blocking in-process beat blocking at the interface.** No privileges, no machine state, and stricter than a firewall: loopback and name resolution go too, so there is no local service and no cached lookup for the cycle to lean on. The reflex was to reach for the OS.

**Static evidence was available and was not enough.** `node:net`, `node:dns`, `node:http` and `fetch` appear nowhere in `src/` or `bin/`, which is worth knowing and is not the claim — a grep cannot see through a dynamic specifier or into a dependency. Kept as a supporting reading in the `.claude/` check, where it is paired with a control on the comment-stripper, and not relied on for the network claim.

**The suite refused the instrument, and refusing it was correct.** `suite-integrity.test.js` already forbids importing an outbound builtin and calling an outbound global, so the watch failed on both counts — it imports `node:net` and `node:dns` to wrap them, and its control script calls `fetch` at a loopback port nothing answers on. The temptation was to relax the sweeps to admit a "helper". Both were **named** instead, following the precedent the file sets for `capability.test.js`: a rule loosened to a shape admits the next real violation silently, whereas a third entry arriving in a named list fails until somebody classifies it. Worth noting that the guard caught its own enforcement mechanism — the sweeps are doing their job on the people writing them.

**Every check here has a firing control, and one of them is the block itself.** An empty log is also what an instrument that never loaded would produce, so the blocked run ends by asking the same child to do the one forbidden thing and requiring it to fail. That pattern — prove the instrument works in the same test that relies on it — is what the earlier stories kept having to retrofit.', '**Testing gaps.** A green suite and an empty log are the same kind of claim, and both are worthless without a run that shows the apparatus can go red. `executables-typescript.test.js` spawns all five binaries and spawns them from the tree, so location was a constant the suite could not speak about; 1,085 passing tests were evidence about one value of it, and the value that mattered was the other one. The absence criteria had the mirror problem — an empty network log is exactly what an instrument that never loaded would produce — and story 3''s answer is the discipline story 2 had to retrofit under pressure: every check carries a firing control, and the blocked run ends by asking the same child to do the one forbidden thing and requiring it to fail. The two also share their fix, which is not more assertions but a second run in the opposite direction: plant the tree under a real `node_modules` and require `node` to refuse it before believing the checkout copy passing means anything. One story learned this by being wrong about a defect that made every install non-functional; the next built it in from the start. That is the same lesson retro 03 recorded from epic 01-03 — an empty reading is unproven until a control shows the instrument can produce a non-empty one — arriving for the third epic running, which makes it a property of this project rather than of any one story.', NULL, '01M1ACQFRJ0JVFMTFZQE1BA665', 'library', '2026-08-30T22:32:00.000Z', 'Promoted: the control-for-every-absence discipline recurred in retros 01, 03 and 05, so it is now standing guidance read at startup rather than a lesson re-judged each run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1A8J3R5GZ012ZXWK8B3P7RJ', '01M1AC4EK1MTJZ74KNA0TPFPY1', 'retro', '01M1957RXJ674PDNMB53CEGBT1', NULL, NULL, 1, 'The story did the one thing no other story in the port had done — installed the thing and used it — and that alone found a defect that made every install non-functional.

**The defect was invisible from inside the repository, by construction.** Node refuses to strip types from any `.ts` under a `node_modules` directory, and OpenCode installs every plugin into one. So `node bin/dpm-mcp.ts` worked in the checkout and could not work in the artefact, and 1085 passing tests were all evidence about the checkout. `executables-typescript.test.js` spawns all five binaries and spawns them from the tree. **Location was a variable the suite never varied**, and the artefact differed from the checkout in exactly that one respect.

**The failure mode was worse than a crash.** 23 skills registered and 0 tools; every skill''s procedure writes exclusively through those tools. The plugin advertised the whole method and could perform none of it, with nothing in the interface saying so. A plugin that failed to load would have been a better outcome — someone would have noticed.

**Two diagnostic habits paid for themselves.** Every escape from the type-stripping restriction was closed off by *test* rather than by reasoning — two Node versions, three flags, and the same tree copied outside `node_modules` — which is what turned "Node seems not to like this" into a fact with a shape. And the fix candidate was checked the same way: `BUN_BE_BUN=1` really does turn `opencode2` into a bun CLI, that bun really does carry `node:sqlite`, and `process.execPath` really is the host binary *inside a loaded plugin*, which is where it mattered and not where it was convenient to check.

**The instrument lied once, and it looked exactly like a second defect.** After the server connected, the probe reported `dpmTools: 0`. It was reading `tool.name`, where the namespace lives on `tool.id` — the tools were all there as `dpm_create_spec`. Ten minutes were nearly spent on a bug in the port that was a bug in the probe. **A filtered sample reporting an absence is not evidence of an absence**, and the fix was to record both fields unfiltered rather than to guess a better filter. Recording the raw shape first would have cost nothing and saved all of it.

**The gate was worth stopping at.** The first end-to-end pass ran against an install carrying the fix as a local patch, which was enough to prove the mechanism and not enough to satisfy a criterion naming the documented command against GitHub. Chris chose push-then-re-verify, the patched cache was deleted outright, and the cold run is the only evidence on the record. It also paid an unplanned dividend: the cold install came down at **166 files**, matching `npm pack` exactly, which answers the question the epic had left open at 418 — the installer does honour the `files` allow-list.', '**Scope surprises.** Both surprises came out of the artefact rather than the plan, and in both the plan was internally consistent and pointing the wrong way. Story 1''s task list was correct in every task and was executing a story the specification defers: FR1 says the GitHub specifier "**and later** the npm form", and *later* had been read as *now* for four tasks and two coverage bindings before anyone asked — the question that dissolved it was five words long and cost one reading of the requirement. Story 2''s suite was 1,085 tests passing, all of them evidence about the checkout, and the artefact differed from the checkout in the single variable the suite never varied. Neither surprise needed new reasoning; both needed someone to open the object that would actually be delivered. The installed package had been sitting in the scratch cache since epic 01-04 at 418 files, 6.4 MB, carrying `private: true` and a Claude Code manifest; the type-stripping refusal was one spawn away. What neither observation says alone is that an epic''s confidence is bounded by the object it has examined, and until this epic the port had only ever examined the checkout. These are two halves of one surprise — what we ship, and what it does once installed — and they both landed in the last epic because nothing earlier had a reason to open it.

**Testing gaps.** A green suite and an empty log are the same kind of claim, and both are worthless without a run that shows the apparatus can go red. `executables-typescript.test.js` spawns all five binaries and spawns them from the tree, so location was a constant the suite could not speak about; 1,085 passing tests were evidence about one value of it, and the value that mattered was the other one. The absence criteria had the mirror problem — an empty network log is exactly what an instrument that never loaded would produce — and story 3''s answer is the discipline story 2 had to retrofit under pressure: every check carries a firing control, and the blocked run ends by asking the same child to do the one forbidden thing and requiring it to fail. The two also share their fix, which is not more assertions but a second run in the opposite direction: plant the tree under a real `node_modules` and require `node` to refuse it before believing the checkout copy passing means anything. One story learned this by being wrong about a defect that made every install non-functional; the next built it in from the start. That is the same lesson retro 03 recorded from epic 01-03 — an empty reading is unproven until a control shows the instrument can produce a non-empty one — arriving for the third epic running, which makes it a property of this project rather than of any one story.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CF96Y5D3AFG96M9B78AGKE', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99TTCYG60Z4A27SBXH9CR', NULL, NULL, 0, '**Erasure is a blind spot, and the second SDK is what turned it from harmless into load-bearing.** A type-only import is erased before evaluation, so every runtime check in this project is blind to it *by design* and correctly so: `staticImports` skips it, the module sweep''s bare-specifier rule never receives it, and `dependencies` staying empty says nothing about it. With one SDK nothing could fall into that gap. With two published under one package name at two versions and told apart only by an npm alias, the specifier is the sole evidence of which host a module is typed against — so a registrar typed against the wrong SDK type-checks, sweeps clean, and is wrong. That is the same failure shape as epic 01-05''s "23 skills registered and 0 tools": the thing advertises correctness and cannot perform it, with nothing in the interface saying so.

**The rule found two defects on its first two runs, neither of which was what it was built for.**

First run: `src/plugin/index.ts` names `@opencode-ai/schema/skill` for `Skill.Info`, and `@opencode-ai/schema` is declared nowhere. It resolves only because the v2 SDK depends on it and npm hoists it — so `tsc` has been passing on an edge no artefact in this repository asserts, and a v2 release that dropped the dependency would break the type check on a file nobody touched with nothing naming the cause. That forced the rule''s set to be a *type surface* per host rather than a plugin package per host, which is the more honest model anyway. The undeclared transitive is recorded and not fixed: declaring it is a manifest decision.

Second run: the partition control between the two readings failed on `import type from ''./x.ts''`. `staticImports` excluded type-only imports with a lookahead containing `type\b\s*(?!from\b)`, and `\s*` **backtracks to empty** — so the inner test succeeded against a space, the exclusion fired, and a value default import bound to the name `type` was read as type-only by the one reading whose entire job is to see runtime edges. Its own doc comment claimed the opposite, in a bullet written to document exactly that case. Nothing in the tree writes the form, so it cost nothing; what matters is that the comment had been right-sounding and wrong for three epics, and the thing that found it was a control asserting a *property of the pair* — every static import is either evaluated or erased, never both and never neither — rather than another assertion about either pattern. The fix was to stop having two patterns: one match, one predicate, and the partition holds by construction instead of by two regexes agreeing.

**Carry forward: after any change to what an import *means*, the readings of the import graph need a partition control and not another example.** Retro 01 recorded that every textual sweep over import statements asserts something subtly different after such a change. This is the third epic in which that has come true, and the difference this time is that the check which caught it was written to hold two readings against each other rather than to test either one against a case somebody thought of.', '**Theme — the types were the least reliable source in the epic, and this is where that starts.** The specifier is the only evidence of which host a module is typed against, and erasure makes it invisible to every runtime check by design. The rule written to close that found two defects that were not what it was built for, and both were found by a control asserting a property of a *pair* of readings rather than another example against one. That pattern recurs three more times below and is the epic''s most transferable finding: where two readings partition a set, assert the partition, not the halves.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CF9SJTM9J1H5XB3NG4NDDF', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99TTCYG60Z4A27SBXH9CR', NULL, NULL, 1, '**A task described a hole that was not there and pointed at one that was, and the difference was settled by planting rather than by reading.** Task 2 said "a sweep that only knows `@opencode-ai/plugin` would pass a runtime import of `@opencode-ai/plugin-v1`". Three citations said otherwise: NFR2 asks for checkability by "the **existing** module sweep"; `scripts/module-sweep.ts` refuses every bare specifier before it attempts resolution, with no name list anywhere; and a planted tree inside the repository — so `node_modules` really would resolve — produced the identical complaint for both SDKs and none for a type-only import of the alias.

The temptation at that point is to amend the criterion and drop the task, and that would have been wrong. The clause named a mechanism that does not exist, but the task''s own scope note — "the sweep''s **recognition rule**, not its reporting" — described a real and unguarded property one level over: not *which specifiers may be evaluated*, which was already absolute, but *which packages may be named for their types*, which nothing checked at all. Reading the clause as the second thing kept the criterion standing, kept the task real, and closed a gap that would otherwise have been story 2''s to discover.

**Worth carrying: when a criterion''s stated mechanism is false, ask what the criterion would have to mean to be worth its place before proposing to remove it.** Retro 01 recorded the mirror case — a criterion naming a mechanism that was unsatisfiable, amended to the checkable property. Both times the fix was to separate the mechanism from what the mechanism was reaching for. The difference is which way it resolved, and the reason it resolved differently here is that the planting produced *evidence about what was already covered*, which made the uncovered thing visible by contrast.

**And the refactoring pass found what four passing suites were hiding from each other.** Four files each asked "does this manifest declare a script that runs at install time" with a loop of their own, and the four lists disagreed: `plugin.test.js` guarded `prepublish` and not `prepack`; `baseline`, `dependency-isolation` and `plugin-entry` guarded `prepack` and not `prepublish`, two of them omitting `build` as well. Every one of them passed, and every one was a genuine hole another was covering with nothing recording the arrangement — a `prepublish` script would have been caught by exactly one of the four. The union is now one reading with a control that plants each name in turn, driven from the list itself so a fifth copy cannot appear. This is the same shape as retro 02''s six duplicate readings of the import graph, arriving through a different artefact: the duplicates were not written to disagree, they were written at different times by people who each needed the answer and none of whom could see the others.', '**The epic superseded fourteen criteria and three tasks across five stories, and this is the reasoning that kept it honest.** A criterion naming a mechanism that turns out not to exist is not thereby wrong; ask what it would have to mean to be worth its place before proposing to remove it. Applied here it saved a task and closed a real gap. Applied in stories 3, 4 and 5 it did the opposite and the criteria genuinely went — the difference being whether the *property* survived the mechanism or went with it. Both directions belong in the record, because a run that only ever amends and a run that only ever supersedes are each following a rule rather than reading the case.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CHQGRQ4SGBJGX8GTB7TCP9', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99W8SPDHE5RTF76GGVRKP', NULL, NULL, 2, 'The story was planned against a premise the hosts disproved: that v1 and v2 differ in how they *call* a plugin. They do not. OpenCode 1.18.25 accepts a default export of `{id, setup}` and calls `setup(context)` exactly as the v2 beta does, so one unchanged export serves both and the entry needed no new shape. What differs is context capability — nine domains against twenty-two. Reading that off the SDK types would have found the opposite: `@opencode-ai/plugin-v1` types only v1''s callable entry, so the protocol dpm actually uses under v1 is undocumented there, and a plan built from the types would have produced a second entry point nobody needs.

The finding that made criterion 2 buildable came from the same probes and would not have been guessed. v1''s nine domains are a strict *subset* of v2''s twenty-two, so no missing domain identifies v1 — absence cannot be the marker. The one domain both carry with disjoint contents is `plugin`: `{add, remove}` under v1, `{list}` under v2. That, with `mcp` being v2-only, gives each host an *independent positive* marker. Written the obvious way — v2 is "has mcp", v1 is "does not" — the two branches are one test and its negation, every context classifies as something, and the both-match case the criterion demands is unreachable. Loosening the predicate to exactly that shape was run as a deliberate red: three controls failed and the happy-path classification test still passed, which is the whole argument for the controls existing.

The probing cost far more than the building. Eight consecutive readings came back empty because `opencode2 run` hands the prompt to a shared background service started from the user''s own config, so the fixture config and every `XDG_*` override were being applied to a process that was not loading the plugin. `--standalone` fixed it. A separate v1 reading was recorded as a negative when it was really a truncation — the run had been killed at a four-minute timeout before `setup` was called — and re-running it to completion reversed the conclusion. Both traps have the same shape as the lesson already in the library: an empty reading needs a control before it is believed, and the control has to be a *positive* result from the same harness.', '**Every conclusion in this observation was later overturned, and it is kept because the method that produced it was sound and the method that overturned it was the same one.** The "both hosts accept one entry" reading was true of what was probed and false of what shipped: the object route and the callable route cannot live in one module, which took two more stories to establish. The cost is the lesson — three of the four traps in this epic were harnesses reporting on the wrong process (a shared background service, a killed run, a stale cache), and each produced a *clean-looking negative*. The library already says an empty reading needs a positive control from the same harness. What this epic adds is stricter: **in the same run**, not merely the same harness, because the thing that goes wrong is the run and not the fixture.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CQC5FJD1FJ1ETQ87XY0QA7', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99XSZNHY02M8TZRVMPWQT', NULL, NULL, 3, 'Four consecutive v1 probe readings were lost to a stale plugin cache, and every one of them read as a clean negative. v1 caches plugin loading per project under XDG_CACHE_HOME; once poisoned — by an earlier run that stalled the loader — the object-route module still *evaluates* and its `setup` is simply never called. The report therefore shows the module loading and nothing else, which is exactly the shape of a host that does not support the protocol. Two design conclusions were drawn from those readings and both were wrong: that one module cannot carry two routes was right for a different reason, and that v1 will not resolve a package specifier was never established at all. Clearing the cache directory made the same fixture produce the full reading immediately.', '**The sharpest instance of the epic''s recurring trap, and the one that should reach the library.** Four consecutive readings looked like clean negatives and were a poisoned cache; two design conclusions were drawn from them and neither was sound as stated. The rule is now specific enough to follow: **a negative reading needs a positive control listed alongside it in the same run**, because the failure being guarded against is the run not reaching the code, and a control in a separate run does not touch that. The technique that finally worked — a known-good entry beside the entry under test, one run answering both — is the same shape as the partition control from story 1, arriving through a probe harness instead of a regex.', 'The rule that would have caught it: a negative reading needs a positive control in the SAME run, not merely in the same harness. The control that finally worked was a known-good path entry listed alongside the specifier under test, so one run answers both. Recorded in tests/support/host-contexts.js''s re-recording notes alongside the three other traps.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CQCEGVXA1ZDBP6A278C7SE', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99XSZNHY02M8TZRVMPWQT', NULL, NULL, 4, '`opencode debug skill` and `opencode debug config` answer without an LLM turn, and neither was found until most of a session had been spent driving probes through `opencode run` — which loads the plugins early and then blocks on a model call that may never return. Half the lost time in this story was spent waiting on turns whose output was never needed. Neither debug command loads the object route, so `run` is still the trigger for skill registration, but the right technique is to poll the incremental report and kill the process the moment it holds what was asked for, rather than waiting for the turn.', '**A tooling finding that paid for itself twice more in story 5.** Polling an incremental report and killing the process on a marker is now the way every v1 probe in this epic was run, and it turned four-minute waits into twenty-second ones. Story 5 added the other half: the run itself is evidence — a probe that *stops early* is telling you the host blocked, and reading that as "the fixture is slow" cost one wasted reading before the pattern was recognised. Worth carrying as a pair: poll for the marker, and treat its absence as a reading rather than as a timeout.', '`opencode serve` boots a headless server and does NOT load project plugins — checked, so it is not the shortcut it looks like. Plugins load per session, per directory.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CQPK4ZCDPJN74EH74JCTWF', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C99ZKVV6FGAB9QS4YA5JPJ', NULL, NULL, 5, 'A requirement written to fence a risk can be discharged by the risk not existing, and the record needs somewhere to say so. NFR3 is a spec `must` whose entire content is how to build safely on `config.skills.paths` — one write site, a marker naming it unsupported, a check that fails loudly when the host normalises it away. Probing found `skill.transform`, a typed and published route that carries the skill body rather than a path to it, so the undocumented key is written from nowhere. NFR3 is not met and not breached: its premise dissolved. Two of story 4''s four criteria and two of its three tasks existed only to satisfy it, and were superseded rather than completed.', '**The theme''s clearest statement: the specification was written from the published types, and three of its hardest requirements were about a route that was not the route.** NFR3 existed to fence an undocumented key; FR4 and ENVX2 existed because a host reading `SKILL.md` verbatim leaves the conventions rewrite nowhere to run. One probe of the bundled v2 API — which the v1 types do not describe — dissolved all three. That is a spec-authoring lesson rather than a delivery one: **where a specification''s risk analysis rests on a published type surface, probe the runtime before the risks become requirements**, because a fence around a hazard that is not there costs criteria, tasks and a story''s worth of design.', 'The same probe collapsed FR4 and ENVX2 from hard problems into non-problems — both are about a host that reads SKILL.md verbatim leaving resolveSupportingPaths nowhere to run, and an embedded source is handed the rewritten text directly. Worth carrying into the next spec: the specification was written from the SDK''s published types, and the route that mattered was in the bundled v2 API the types do not describe.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CVDGV3XZHNW5RVE6QNQ82M', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C9A10T12G36GD9PC17DTYX', NULL, NULL, 6, 'The integration story found a defect that four green per-story test files could not see, and the reason is that every one of them compared the registration to the thing that built it. `localServer` named a runtime; `v1-registrar.test.js` asserted the config hook registered what `localServer` returned; `plugin-entry.test.js` asserted the command''s second element was the packaged executable. All true of any command whatever, including one that cannot start. Nothing asked whether the runtime named could run the server, and the answer under the target host was no — v1''s bun is 1.3.14 and has no `node:sqlite`, where the `installed-runtime.test.js` fixture that established the bun route preferred a standalone `bun` and fell back to `opencode2`, whose bun is 1.4.0 and does. On a machine with no standalone bun, that test had been passing against the runtime of the host the epic had already dropped. The reading that closes it is one line — spawn the registered runtime and import `node:sqlite` — and it is the kind of reading a suite acquires only when something forces it, because until then the registration and the assertion are the same sentence read twice.', '**The epic''s most expensive finding, and the one worth promoting.** Four green test files asserted that the registration equalled the thing that built it — true of any value whatever, including a command that cannot start. The defect was only reachable by asking a question about the *world* rather than about the code: can this runtime load `node:sqlite`? That is one line, and no amount of care inside the existing assertions would have produced it. Stated as a rule: **when a module hands a value to something outside the process, at least one check must exercise the outside.** The corollary is the story-1 partition control again — the four files agreed with each other because they were four readings of one source, and agreement among readings of one source is not evidence.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1CVE1PFAAFJNFJZ66HDHWDK', '01M1CVM84M7H2N1F0KRW29TXB3', 'retro', '01M1C9A10T12G36GD9PC17DTYX', NULL, NULL, 7, 'A one-line change to which runtime is registered turned into a rewrite of two test files and five README sections, and the reason is worth recording: the packaged install was not a paragraph in the README, it was a model the document was built on. The link instructions globbed the package cache, the shell functions globbed it twice more, the `external_directory` permission entry named it, the out-of-date-guard section explained staleness in terms of two specifiers for one repository, and the develop-DPM-itself section rested on there being an installed release distinct from the working tree. That last one does not survive the change at all — with a checkout install the guard is the code you are editing, so a bug in the guard now blocks committing its own fix, which the README had to be made to say rather than quietly stop saying. The estimate was "update the install section"; the work was "the install route is load-bearing in six places, and two test files hold it there".', '**Where the epic''s estimate was most wrong, and it was not in the code.** The registrar changes were small; the documentation was not, because the install route was a model the README was built on rather than a section it contained. The generalisable part is that **a documented procedure with executable guards has a blast radius the guards make visible only when you change it** — two test files held the old model in place, and finding them was the same afternoon''s work as changing it. The uncomfortable residue is recorded rather than smoothed over: with a checkout install there is no released DPM standing apart from the working tree, so a bug in the guard now blocks committing its own fix. That is a real regression in the development workflow, accepted because the alternative was an install with no tools.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DSMJ7B4C54SHZPQGSXCAFQ', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NH4G73B75EAPFTR1E46T', NULL, NULL, 0, 'The rename itself was twenty-three `mv`s and twenty-three one-line edits, and the plan''s own surface enumeration under-counted the fallout by four to one. Retro 03''s lesson was applied deliberately — `skillSource` was made to resolve a bare name to its `dpm-` directory *before* the directories moved, which is what kept roughly forty test files from going red on the spot. It worked, and the plan then predicted three files would still fail. Eleven did, across twenty-four tests: the corpus list, `skill-port`''s recorded gap and `skill-invocation`''s composition were the three that were foreseen, but `body-asks`, `body-corpus`, `body-reads`, `skill-epics`, `skill-spec`, `skill-reference-input`, `skills-gates` and `skills-resume` were not, and each one holds a *bare-name* assumption of its own rather than reading through the instrument. The instrument absorbed the reads; what it could not absorb was every file that compares a name it got from the instrument against a literal it wrote down.

Two of those literals are worth separating, because they fail in opposite ways. `guard-fix.test.js` ran the composition backwards — `PUBLISH_SKILL.slice(ID_PREFIX.length)` — to turn an id back into a directory, and broke loudly the moment the round trip stopped being needed. `scripts/skill-body-check.ts` compared `RECORDED_GAP.skill === ''ralph''` against a directory name and would have gone *quiet*: a valid string matching nothing, the exemption silently unapplied, and five stop-hook references surfacing as five breaches of a corpus nobody had touched. Library lesson 04 names exactly this — after a rename, grep for the predicates that filter on the old form separately from the literal name — and it was that instruction, not the failing suite, that found the second one before it fired.

The other thing the story established is that the criterion''s stated premise was false. OpenCode requires nothing of the directory/front-matter pair: under the embedded-source route the host is handed `{name, description, location, content}` and never opens the directory. Epic 02-01 had already demonstrated the exact mismatch live — twenty-three skills registered as `dpm-<skill>` from unprefixed directories, accepted by 1.18.25 — so the evidence was in hand before the story started and only needed reading. The rename is still right, for dpm''s own reasons, but a story built on the stated reason would have gone looking for a host constraint to satisfy and found nothing to aim at.', '**An instrument absorbs reads, not comparisons — and the ratio was four to one.** Changing `skillSource` before the `mv`s was the right move and it worked: roughly forty files that *read* a skill through the helper never noticed the rename. Eleven files failed anyway, across twenty-four tests, and every one of them failed for the same reason — it took a name *from* the instrument and compared it against a literal it had written down itself. The plan predicted three of the eleven. The lesson for the next rename is not "change the instrument first"; it is that changing the instrument first bounds the reads and tells you nothing about the comparisons, and the comparisons are the larger set. Enumerate them separately, by grepping for literals of the old form rather than for calls to the helper.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DT33X480VF1K0ZM6FK8167', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NJN1KWKMHZ6T6BV2VWWY', NULL, NULL, 1, 'Deleting `ID_PREFIX` took four lines in `src/`. What it actually cost was `DiscoveredSkill.id`, which turned out to be reachable from seven places across five test files — and every one of them read `skill.id` on an object that now returns `undefined` rather than throwing. Two of the seven were caught by a `deepEqual` and reported as `[undefined, undefined, …]`; the other five were `undefined` interpolated into an assertion *message*, where the assertion still passes and the failure text, if it ever fired, would say "undefined is registered from …". Those were found by grepping for the field, not by running the suite. The field was two answers to one question — `id` held the prefixed string, `name` the bare one — and every caller had to know which one it wanted; deleting it is the reason the seven sites existed to find.

The criterion asked for the constant to be gone from `src/plugin/` with a planted-reintroduction control, and writing that check honestly is where the real thinking went. `ID_PREFIX` still appears five times under `src/`, in the doc comments explaining that it was removed and why. A sweep for the word reports all five, and the only way to quiet it is to delete the explanations — a check that passes by destroying the record of why it exists. So the sweep strips comments first, and it reads for a *declaration* of a namespace fragment rather than for the identifier: `/(const|let|var)\s+[A-Z_]*(PREFIX|NAMESPACE)[A-Z_]*\s*(:[^=]+)?=\s*[''"`]/`. Retro 03''s criteria-gaps lesson decided that shape — a check naming `ID_PREFIX` would be walked straight past by the same constant called `SKILL_PREFIX`, which is what anyone reintroducing it would actually write. The control asserts both directions on the same predicate: four reintroduction spellings caught, five innocent lines including two real doc comments left alone.

One criterion here was load-bearing in a way its wording understates. "The registered name for each skill is the same string as before the change" is what makes moving the prefix safe at all, because ADR 01-05 records a registered name as effectively permanent from the first publish. It is also the one list in the epic that may not be derived from the tree — deriving it would make the check read its answer off the thing under test — so the twenty-three published ids are transcribed, with a comment saying why that is the exception.', '**A check for an absence must not be satisfiable by deleting the explanation of it.** The criterion asked that `ID_PREFIX` be gone from `src/plugin/`, and the obvious check — sweep for the identifier — reports five hits, all of them doc comments recording that it was removed and why. The only way to quiet that check is to destroy the record. So the sweep strips comments and reads for a *declaration* of a namespace fragment rather than for the name: a reintroduction called `SKILL_PREFIX` is caught, and the prose explaining the history is not. That shape generalises past this epic — whenever a criterion forbids a thing by name, ask what the file is allowed to *say* about the thing, and match on the construct rather than the word.

**Deleting a field that returns `undefined` is a rename with no compiler behind it.** `DiscoveredSkill.id` had seven readers; two failed loudly in a `deepEqual`, and five were `undefined` interpolated into assertion *messages*, where the assertion passes and the only cost is a failure sentence that says "undefined is registered from …" on some future day. `grep` found those five; the suite never would have. The same shape as the quiet predicates in the observation above, one type-system layer down.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DVXREQQRJZ8M05RXDHTSHR', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NM656AR8N6H2ESMCD6P6', NULL, NULL, 2, 'The criterion asked for a suite-passing-count floor, and the count turned out to measure the user''s staging area rather than the suite. Renaming twenty-three tracked directories without staging the moves puts the index and the working tree out of step, and `plugin.test.js`''s index reading fails on exactly that — one test short of the floor, with nothing lost, nothing skipped and every other file green. The criterion was amended to drop the count and read file by file instead: every pre-epic test file present, unskipped, and still declaring cases. The per-file reading catches the failure the count was written for — a file emptied by the rename is present, unskipped, and asserts nothing — and it catches it in the one place a total cannot, because a total goes on looking healthy while one file quietly stops testing.', '**A criterion that counts the suite is measuring the machine as much as the code.** The passing-count floor was a reasonable thing to ask for and it failed for a reason with nothing to do with the suite: twenty-three tracked directories had moved and the moves were not staged, so an index-reading test failed and the total came in one short. Nothing was lost; nothing was skipped. The amendment replaced the total with a per-file read — every pre-epic file present, unskipped, still declaring cases — which catches the failure the count was written for and catches it in the one place a total cannot, because a total stays healthy while one file quietly stops testing. **The general form: when a criterion''s measure can move without the subject moving, it is measuring something else.** Ask what else can move it before writing the number down.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DVY4J7E83XH9HBMR6AMRCS', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NM656AR8N6H2ESMCD6P6', NULL, NULL, 3, 'Every sweep written for this rename had to be told what is not a skill name, and the first draft of each got it wrong in the same way. A blanket sweep for bare skill-name literals across `tests/` returned 489 hits in 101 files, nearly all of them document kinds, library scope keywords and agent names — `''spec''`, `''review''`, `''do''` — which merely share spellings with a directory. A sweep for `skillSource(''x'')` call sites reported four skills the tree does not have, because `tests/support/package-tree.js` exports a same-named function that *builds* a synthetic source. And the third draft reported this file''s own `assert.throws(() => skillSource(''nonesuch''))` controls, which name something missing on purpose. Each was fixed by narrowing to the position rather than the string: the front of a quoted literal, the import the call resolves through, and the absence of an `assert.throws` wrapper. Library lesson 04 is written about renames, and it applies just as hard to the readings written to police one.', '**Library lesson 04 was cited three times in this epic and its first draft was broken three times anyway.** A sweep for bare skill-name literals returned 489 hits in 101 files, almost all of them document kinds and scope keywords that merely share spellings with a directory. A sweep for `skillSource(''x'')` reported four skills the tree does not have, because a support module exports a same-named *builder*. A third reported this very file''s `assert.throws` controls, which name something missing on purpose. Each fix was the same move — narrow to the *position* rather than the string: the front of a quoted literal, the import a call resolves through, the absence of a `throws` wrapper. **Knowing the lesson does not apply it.** What applied it, every time, was running the reading and looking at what it actually returned before asserting an absence over it — which is the cheapest possible control and the one easiest to skip when the answer is expected to be empty.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DWC5NZQBEBMNZHSY57P4GA', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NP5XWKJ06Y9X8512V9TR', NULL, NULL, 4, 'The read-back is quiet in the ordinary case by construction, and saying so is what stopped it becoming a check that cannot fail. dpm''s sources go in last, so inside dpm''s own transform dpm''s entries win every name it claimed — a post-registration check written as another look at what `discoverSkills` returned would have passed forever and proved nothing. Retro application 01M1CXES34CZ14V6CDT54KQRSH said as much before the code existed, and the shape it forced is a pure `displacedSkills(registered, registry, root)` the tests hand a registry holding a foreign skill dpm did not put there, plus a draft whose `list()` starts returning entries the `source` calls never made. What the check catches in production is named rather than implied: a host that keys and replaces rather than appends, a replay that reorders the transforms, and a source the decode dropped so dpm''s name is registered to nobody.', '**A retro application that fires before the code exists is the only kind worth recording.** The disposition taken at this run''s retro gate said the clash check must be driven against a registry containing a foreign skill dpm did not put there, or it becomes another reading of `discoverSkills` that cannot fail. That was written before the story started, and it was exactly right: dpm''s sources go in last, so within dpm''s own transform dpm wins every name and the obvious implementation is a check that passes forever. The shape it forced — a pure function taking `(registered, registry, root)`, plus a test double whose `list()` starts returning entries the `source` calls never made — is the reusable part. **Where a check''s subject is state the code itself produced, the check has to be given state from somewhere else, or it is the code agreeing with itself.**', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DWCHXHMJN5W7ED63ZRYDVX', '01M1DWFNH5V427AQ8Y1P0GF0PV', 'retro', '01M1C9NP5XWKJ06Y9X8512V9TR', NULL, NULL, 5, 'Four assertions already in the suite asked whether a skill''s location was inside this package, and all four asked it with `location.startsWith(join(ROOT, ''skills''))` — the exact form library lesson 04 forbids. A sibling package installed one character along, `${ROOT}-other/skills/dpm-do`, satisfies every one of them, so the single path each was written to reject was the path it accepted. None had ever failed, and none would have. The fix is one predicate, `withinPackage(root, path)` in `src/plugin/root.ts`, asking `relative` whether the step climbs out; the four sites now share it, and the control that distinguishes it from the prefix form is driven rather than described — the planted sibling passes `startsWith` and fails `withinPackage` in the same test. Worth noting that the lesson was already in the library and already cited in this epic''s other stories, and the four sites still went unnoticed until a story asked the same question in production code.', '**Four assertions had been asking the containment question the forbidden way, and none of them could ever have failed.** `location.startsWith(join(ROOT, ''skills''))` accepts `${ROOT}-other/skills/dpm-do` — the single path each assertion existed to reject. They passed every run, for two epics, because the trap they were written against is the one they let through. This is the strongest form of the epic''s recurring theme: a predicate does not have to *stop* matching to go quiet, it can have been quiet from the day it was written. **The tell is that a check for an absence has never once reported anything** — which is indistinguishable from working, and is why every absence in this suite is supposed to carry a control. These four had no control. The fix is one shared `withinPackage(root, path)` asking `relative` whether the step climbs out, with the planted sibling driven through both forms in the same assertion so the difference between them is visible rather than argued.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DZ4WH85Q8FTTEHHWNWFJ04', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C9X82WCTH2ZTSP9QSPBW1H', NULL, NULL, 0, 'The 184th tool could not be added without reshaping a test that had been correct for two epics. `tests/tool-naming.test.js` asserted the ported surface *equals* v0.7.0''s oracle — 183 tools, name for name, description for description — and `tests/parity-v070.test.js` forbids rewriting that oracle, correctly: regenerating a fixture is how any parity finding gets disposed of without a line of the test being deleted. The two together left no room for a tool the port adds on purpose, which ADR 02-01 requires.

The resolution was to change the shape of the claim rather than either side of it: v0.7.0''s surface is a **floor**, not a ceiling. Every one of the 183 must still be present and byte-identical; anything else must be named in an `ADDED` list carrying what added it. That is `tests/suite-integrity.test.js`''s existing INHERITED/ADDED idiom, reused rather than invented, and it preserves the property actually worth defending — the surface may not grow *silently*. The oracle was not touched, which `git status` confirms and `parity-v070.test.js` re-checks on every run.

Two consequences the equality had been hiding. The per-tool comparison had to move from index-matching to name-matching: an added tool sorting into the middle would otherwise offset every comparison after it and report 180 failures for one addition. And the subset direction needed its own control — a subset check passes trivially over an empty oracle, so the reading is now driven in both directions with a planted rewording and a planted loss.', '**A parity oracle is a floor, and an equality says it is a ceiling.** The assertion was right for as long as the port was only a port, and the day it had to be wrong was the day the port first added something on purpose — at which point the cheapest fix was to rewrite the protected fixture and undo the whole story silently. The shape that survives is the one `suite-integrity.test.js` already found for test files: an inherited set that must be present and unchanged, plus a hand-kept additions list carrying what added each one. Every "we match the release exactly" assertion in this suite has the same expiry date, and the two that are left — `parity-v070.test.js`''s dump and the corpus snapshot — should be reshaped when they hit it rather than argued with.', 'Epic 02-03 story 1. Suite 1145 → 1154, all green; typecheck, module sweep and skill-body check clean.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1DZP49PGG6SHSTW5SYYP7M4', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C9X9NSXNCN0ANYYHGF8PWT', NULL, NULL, 1, 'Rewriting twenty-four references cost four edits outside the twenty-four, and each was a check that had been written against the mechanism being replaced rather than against the property it was defending.

Two of them were exact tool-set assertions. `tests/skill-publish.test.js` pinned dpm-publish''s surface at exactly `[''publish'']` and `tests/skill-templates.test.js` pinned dpm-templates at exactly two tools — both correct while the conventions arrived by a *path*, and both broken the moment every body gained a tool call. The temptation was to widen the expected list; that would have said these skills need one more tool than they do. What was done instead is subtract `read_shared_document` explicitly and assert it was there to subtract, so a skill that stops calling for its conventions still fails rather than slipping through the exemption. The constant lives once, in `tests/support/skills.js`, with the reason attached.

One was `tests/corpus.test.js`''s claim that a body naming **Conversational Output** must also name the file that section is in. The claim survives unchanged; what satisfies it is now the tool call. The other was prose: the shared conventions'' own opening paragraph described itself as a file a skill reads, which stopped being true of the corpus it governs.

The remaining four suite failures are all one thing — `resolveSupportingPaths`''s own controls, each of the form "and here is proof the rewrite had something to rewrite". With zero references left they fire correctly. They are story 3''s subject, not a regression, and they are reported here rather than absorbed.

A near miss worth recording: the first draft of the replacement prose wrote "the whole of ADR 02-01", and `corpus.test.js` refused it — the shared conventions may not name an artefact by a number a renumber would move. The rule caught a sentence written by the run that was meant to be following it.', '**Replacing a mechanism costs more in the checks written against it than in the mechanism.** Twenty-four one-line edits pulled four unrelated tests over, and each one had encoded *how* the property held rather than the property: an exact tool set that was only exact because the conventions arrived by a path, and a rule requiring a body to name the file its sections live in. The repair that works is to subtract the new arrival explicitly and then assert it was there to subtract — a filter with no companion assertion is an exemption that starts hiding the thing it was written to permit. The one to carry forward: when a change adds something to every member of a set, go and find the tests that pinned any member''s size.', 'Epic 02-03 story 2. Suite 1160 tests, 1156 pass, 4 fail — all four are story 3''s mechanism. typecheck, module sweep and skill-body check clean.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1E99150J7TB3Z4X7KTS4QNF', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C9XB5NBSBPCDXXAP0H8KKR', NULL, NULL, 2, 'Deleting `resolveSupportingPaths` took forty lines out of `src/plugin/skills.ts` and turned four tests from claims about a transform into claims about its absence — which is the harder thing to check and where the work actually was.

Three of the four inverted rather than being deleted, and the inversions are the record of what happened. `tests/v1-skills.test.js` asserted every body''s shared reference had been rewritten to an absolute path that exists, with a control counting the substitutions; it now asserts every registered body is byte-identical to its file, with a control that the comparison can come out false. `tests/skill-supporting-files.test.js` asserted all twenty-three sources still carried the relative form — because the substitution ran at registration and what a maintainer edited was unchanged — and now asserts none does. `tests/publish-package.test.js`''s must-NOT rested on the rewrite throwing when a shared document was missing from the tarball; it now drives `read_shared_document` against the extracted package and deletes a document to see the refusal. That last one got stronger by moving: the old check failed loudly at load, and a tarball missing `shared/` now loads perfectly and fails on the first call of every session, so the check is aimed at where the failure actually is.

The sweep for the deleted rewrite is deliberately not a search for its name. A function deleted and reintroduced under another name passes a name search and fails the criterion, and renaming is the likeliest way it comes back — somebody needs one path fixed and writes four lines rather than reaching for a function that no longer exists. So it matches the operation: a substitution applied to a skill body, and the reference pattern that would drive one. It also had to strip comments first, because four modules explain the removal and name the function while doing so — a sweep over raw source would report those, and the cheapest way to make it pass would be to delete the explanations.

**A user-facing falsehood surfaced that no criterion covered.** The README''s "The one entry to set" told every user to grant `external_directory` on the clone''s `shared/*`, because every skill body read a file outside their project. That stopped being true the moment story 2 landed, and no test noticed — `permission-entries.test.js` asserted the block was *present*, so it was actively holding the stale instruction in place. Raised as a change moment rather than absorbed; Chris chose to fold it into this story on the grounds that story 3''s own task says it closes the external-directory cost retro 04 recorded, and a README recommending a permission for a deleted mechanism is that cost still open. `HOST_ACTIONS` is now empty with the history attached, and the exact-set assertion gained a planted block, because an empty expected set is satisfied by a reader that finds nothing at all.', '**A deletion sweep that searches for a name is a sweep the next author passes without trying.** What had to be prevented was a *substitution applied to a skill body*, so that is what the patterns match — the operation, plus the two dead identifiers as a courtesy — and the sweep strips comments first, because four modules now explain the removal and name the deleted function while doing so. A raw-source sweep would have reported its own explanations, and the cheapest way to make it green would have been deleting them. Second thing worth keeping: the README''s stale `external_directory` recommendation was not merely left behind, it was **held in place** by a test asserting the block existed. A test can pin a false instruction as firmly as a true one, and removing the instruction meant editing the check that guarded it — so the check was rewritten to assert the opposite, with a planted block proving the reader can still see such a rule.', 'Epic 02-03 story 3. Suite 1161 tests, all pass. typecheck, module sweep, skill-body check clean. Refactoring pass: nothing to consolidate — the deletion is the consolidation, and the dead SHARED_DIRECTORY re-export from skills.ts went with it.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1E9H0KW4GJKBRTA5EQ9T5J6', '01M1E9JX4D4HAKX7H75CPT88FS', 'retro', '01M1C9XCMX24NRBKESSPQ369QV', NULL, NULL, 3, 'The story that was supposed to be a formality found the gap the other three could not see between them, and it is worth naming precisely because all three passed.

Story 1 asked whether the tool answers a name. Story 2 asked whether every body names the tool. Story 3 asked whether anything still transforms a body. **None of them ever took a name out of a body and put it into the tool.** A corpus asking for `conventions` against a tool serving `skill-conventions` satisfies every assertion in all three files, and no dpm skill would ever read its conventions again — the exact silent omission this epic exists to close, reassembled out of three green checks. So the round trip extracts the argument from the registered prose rather than writing it down, and the control plants a body asking for a document that is not there.

**The criterion''s second half named something the repo does not have, and it was a gate rather than a judgement call.** It asked for the trip under "a v1 stub context" and "a v2 stub context". There is one recorded host context — `V1_CONTEXT`, probed off OpenCode 1.18.25 — and v2 lives only in `src/plugin/hosts.ts`''s type graph, which is erased before evaluation. Building a v2 double would have meant writing it from SDK types, which is precisely what `support/host-contexts.js`''s own header says it refused to do, and is how the bun regression stayed green through epic 02-01. Chris chose the reading that maps onto something real: v1''s two plugin protocols, which dpm ships a separate module for. The criterion was amended to say so.

That turned out to be the better axis anyway. The two routes are the only place a shared-document surface can break invisibly — the skills registering from one tree while the server serves another tree''s `shared/` — and it is the same divergence epic 02-01 story 5 was written to catch. The test drives bodies from the object route against the tool from the registry the callable route''s command would build, and then checks that the bytes both routes agree on are the file''s, because two routes agreeing is not the same as two routes being right.', '**Three green stories left the epic''s actual claim unchecked, and only a story written to walk the whole trip found it.** Story 1 proved the tool answers a name, story 2 proved every body names the tool, story 3 proved nothing rewrites a body — and a corpus asking for `conventions` against a tool serving `skill-conventions` satisfies all three while no skill ever reads its conventions again. The gap sat exactly at the seams, where each story''s assertions stopped. The fix that generalises: **extract the argument from the artefact rather than writing it down**. A test that calls the tool with the string a maintainer knows is correct is testing the maintainer''s memory; one that reads the string out of the registered body is testing the system. And the control matters more than usual here, because "every trip succeeded" is also what a reading that extracted nothing and called nothing produces — the extraction is prose-matching, and prose gets reworded.', 'Epic 02-03 story 4. Suite 1165 tests, all pass. typecheck, module sweep, skill-body check clean. Refactoring pass skipped: the story added one test file and touched no implementation.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1EWEVJDNCF61FQD39B63AMA', '01M1EWTJFC7H2N8GEXG4XGCKPR', 'retro', '01M1CA41FG02G8MZT4AP76Z341', NULL, NULL, 0, 'The story was planned as a rewrite of four README sections and turned out to be a rewrite of none of them, because epic 02-01 story 5 had already done that work and its coverage row was already verified. What was left was the prose the executable checks are blind to, and it was worse than the sections.

**Every command in the README ran, and the document was still wrong about what it is.** `readme-v2.test.js` classifies every fenced block by a rule and executes it, fails on an unmatched block and fails again on a rule that matches nothing — a genuinely strong instrument, green throughout. The Status section meanwhile said the package was ported to a host it had been moved off, listed spec 01''s five epics as the whole build-out while a second specification had delivered four more, and explained `ralph`''s dead loop by reference to that same departed host. None of that is a command, so none of it was reachable from the one place the README is checked.

The reading that closes it derives the epic table from `docs/epics/` **in both directions**: every projected epic document must appear in the table, and every filename the table names must exist. A hand-kept list would have reproduced the original defect exactly — it is only ever edited by whoever remembers to, and nobody remembered for four epics. The table also has to distinguish delivered work from work that has not shipped, which is asserted separately, because a table rendering both alike is true of something on every row and leaves the reader to be the one who is wrong.

**The placeholder was the same failure one word wide.** Command blocks said `<package path>`, which was accurate while there was a package and read as though there still were once the install became a clone. It was also defined four sections after its first use, inside *When something else owns the hook* — a section a reader arriving from a guard refusal has no reason to open, which is exactly the reader who meets it in a command they are about to run. Renamed to `<dpm clone>` and defined where it first appears, with the assertion written as a position check rather than a presence check, because "it is defined somewhere" is what was true before.

Two things followed the rename outward. `readme-v2.test.js`''s `PLACEHOLDER` constant, changed in the same task rather than after the suite went red — retro 03''s instrument lesson, applied deliberately. And `scripts/skill-body-check.ts`, whose recorded-gap message printed the identical stale claim about the departed host; the README''s own sentence had just been rewritten and the script''s had not, which is retro 04''s question — what else in this tree produces the same artefact for a reader — answering itself one grep later.

**No coverage was marked verified, and that is the story''s most considered act.** All three bindings quote FR6''s two-host text. The criteria were amended to drop the second host at Chris''s ruling; the fragments could not be, because the spec is read and not written. Marking them would have recorded the README as covering a host this story''s own must-NOT forbids it from naming. FR6''s v1 half is discharged already by two correctly-scoped rows epic 02-01 wrote. The three two-host rows are left standing and unverified rather than retired, so the divergence between the specification and the decision that overtook it stays visible to whoever revises the spec.', '**An executable check over a document tests the half of it nobody misreads.** `readme-v2.test.js` is a strong instrument — every fenced block classified by a rule and run, an unmatched block a failure, a rule matching nothing a failure too — and it was green throughout while the README said the package was ported to a host it had been moved off and listed half the epics that built it. Commands are the part of documentation that fails loudly in a reader''s terminal; prose is the part that fails silently in their head, and it is the part with no oracle unless one is built. The one built here is worth copying: **derive the list from the tree in both directions**. Every projected epic must appear in the table and every filename in the table must exist, so the section cannot go stale without going red. A hand-kept list would have reproduced the original defect exactly — it is only ever edited by whoever remembers to, and for four epics nobody did.', 'Epic 02-04 story 1. Suite 1165 → 1173, all green. typecheck, module sweep and skill-body check clean. Refactoring pass: CLONE_PLACEHOLDER moved into tests/support/dpm-clone.js beside DOCUMENTED_CLONE, so the two files checking the README against that token share one literal.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1EWSCM34DMQVF90XHBWQVRH', '01M1EWTJFC7H2N8GEXG4XGCKPR', 'retro', '01M1CA434SC66WN2SQV8MWBZGD', NULL, NULL, 1, '**The story''s own control found a dead pattern in the story''s own must-NOT, on the first run.** The sweep for claims the section had stopped making true was written line-anchored — `/^[^\n]*reads a file from the package directory[^\n]*$/m` — which reads naturally and cannot work, because the README is hard-wrapped and the sentence it was written against breaks between `package` and `directory`. It passed against the current section, where there is nothing to find, and would have gone on passing for the life of the project while a third of the must-NOT constrained nothing. What caught it was the control planting the removed paragraph *verbatim* and asserting all three patterns report, rather than asserting that some did. `tests/support/skills.js` records this trap for skill bodies; it is a property of every hard-wrapped document here, and the fix is `\s+` between every word rather than a space.

That is the retro-07 disposition this run recorded before starting — *run the reading and look at what it returns before asserting an absence over it* — paying for itself inside one story, on a pattern written by the run that had just written the disposition down.

**The defect the story was fixing was one this run caused.** Epic 02-03 removed the `external_directory` rule and left the two paragraphs framing it, so the section opened by telling every reader that one entry was worth setting whatever their configuration looked like, three paragraphs above the text saying nothing DPM does reads outside the project. Nothing noticed: the checks over this section ask whether documented *rules* name skills and tools that exist, and prose is not a rule. The section had been internally contradictory for an epic and every test was green.

**The reading the criterion actually needed was the other half of a partition.** `permission-entries.test.js` already asked whether each recommended rule finds a skill. It never asked whether each skill finds a rule — and a recommendation that names only real skills can still leave half the method denied, invisibly, because the rule matches *something* and the first test passes. Story 2 adds skills → rules, and the two together are the partition retro 06 named after four green files that each checked one side of one.

Two things kept it honest. It reads `discoverSkills`, because what the permission engine matches is the string the host is handed, not the directory listing — and before ADR 02-04 those differed, which is precisely the state in which `dpm-*` matches every registration and nothing a reader can find in the tree. And the README''s claim about where the id comes from is checked *against the tree* rather than only found in the prose, so the sentence cannot outlive the mechanism the way the paragraph above it did.

**No fourth transcribed list.** The criterion wanted the twenty-three held against the published ids, and `corpus.test.js` already transcribes them with `suite-skill-names.test.js` policing the region. A copy here would have been a fourth thing to keep in step rather than a second opinion, so what is asserted locally is the count — enough to fail when a skill goes missing, and no more than this file has a right to claim.

**One of the two coverage rows was left unverified deliberately.** Its fragment quotes FR7''s premise that the engine matches "the unprefixed front-matter name". Epic 02-02 put the prefix into the front matter and dissolved that premise, so the README now correctly says the opposite of the text the row binds. FR7 is another requirement written to fence a risk that no longer exists.', '**Knowing the lesson still did not apply it, for the second epic running.** This run opened by dispositioning retro 07''s rule — *run the reading and look at what it returns before asserting an absence over it* — wrote it into a row, and then wrote a line-anchored must-NOT pattern against a hard-wrapped paragraph that breaks mid-phrase. It passed. It would have gone on passing forever while a third of the sweep constrained nothing. What caught it was planting the removed paragraph **verbatim** and requiring *every* pattern to report, rather than requiring that some did — and the general form is worth stating plainly: a control that asserts a non-empty result is weaker than one that asserts the exact set, because the first is satisfied by the patterns that already worked.

The second half is the one to carry into the next documentation change. This epic''s whole subject was a paragraph the previous epic left behind, and the previous epic''s subject was an instruction a *test* had been holding in place. Two epics running, the defect was residue: something removed correctly, with the sentences around it left describing it. The check that would have caught both is neither a rule check nor a command run — it is asking, after removing a mechanism, what the document still *says* about it.', 'Epic 02-04 story 2. Suite 1173 → 1178, all green. typecheck, module sweep and skill-body check clean. Refactoring pass: the file''s two separate imports from ./support/skills.js merged into one, and basename used where a path was being split on a literal slash.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1GF6D3FP7VHWV5Z8TAW8A5P', '01M1GPS7MS4BPFANKN7X9NA36A', 'retro', '01M1CB27C7DJJ88XTNPGP3A4QM', NULL, NULL, 0, 'The criterion said "written through the v1 server ... read through the v2 server", and the first thing the story had to establish is that **there is no such pair of servers**. `localServer()` computes one command and hands the same one to whichever host asks, so a test looking for a difference in what dpm *registers* finds none and reports agreement it never earned. What actually differs is the process that ends up running the file, and `src/plugin/server.ts` already had it written down: v1 must use `node`, because the bun compiled into 1.18.25 is 1.3.14 and has no `node:sqlite`; v2 can use its own bun, 1.4.0, which does. Both were re-read off the machine rather than taken from the comment — `BUN_BE_BUN=1 opencode2 -e` printed `1.4.0` and a `DatabaseSync` function — and the comparison became two runtimes over one database. Byte-identical dump, byte-identical projection, guard exit 0 on both.

**Three things were built as controls and one of them caught something.** The planted-identifier sweep asserts the exact set of six `why` values comes back from the dump and from the projection independently, per retro 09; a stale-dump control holds `publishThrough`''s removal in place, without which a runtime that did nothing would hand back its predecessor''s bytes and every comparison would pass on the strength of the failure; and the divergence control was rewritten mid-story to run the *same* `distinct()` the real assertion uses, because a control that builds its own equality proves that equality works rather than that the comparison can see. The one that caught something was in `suite-integrity.test.js`: the new stand-down check reported *itself*, because its planted literals sit in the file and `withoutComments` strips comments but not strings. The fix was a line anchor — legitimate here, where the subject is source and a stand-down is a statement, and the opposite of retro 09''s trap, which was anchoring against hard-wrapped prose. It is recorded in the comment as having arrived by failing rather than by being remembered.

**Two findings the story did not go looking for.**

First, `docs/epics/02-05-epic-v1-walk.md` renders "Story 2 — Blocked by: Story 3" while the row says `source=story 2, target=story 3, kind=blocks`, and `readiness.ts:15` states the contract in as many words: *"An edge reads source-blocks-target, so the epic that cannot start is the target."* `src/projection/load.ts:112` loads a story''s edges by `source_story_id` — the edges where the story **is** the blocker — and `src/projection/templates/epic.ts:101` renders their targets under `**Blocked by**`. Wrong end and wrong label. The readiness query and `list_story ready:true` are correct; only the document is wrong, which is the shape `epic.ts`''s own docblock warns about — *"Neither is wrong on its own terms, both report success, and the reader believes the file."* Out of this epic''s scope and left unfixed rather than absorbed.

Second, ENVX1''s real reading is not the one the criterion''s words produce. Running the suite with both binaries off `PATH` gave 1185/1185 and zero skipped — and proved nothing, because `installed-runtime.test.js:46` and `v1-integration.test.js:46` reach the v1 CLI by absolute path under `$HOME/.opencode/bin`. With a `HOME` holding no `.opencode` the numbers are 1183 pass, 0 fail, 2 skipped. The two skips turned out to be the good kind — each names ENVX1 as its warrant, states what the skip costs, and leaves a companion control that runs on any machine — so the silent binary dependency task 2 went looking for is genuinely absent. What was absent instead was any record that there are exactly two: the existing must-NOT is anchored on `test.skip(` and `{ skip: true }`, and cannot see the runtime `t.skip()` form both of these use. That gap is now closed by a named exact set in both directions.', '**The criterion''s words named a comparison that did not exist, and finding the real one was the story.** "Written through the v1 server, read through the v2 server" presupposes two servers; `localServer()` builds one command for both hosts, so the difference is not in what dpm registers but in which runtime ends up executing the file. The story found the real axis — two runtimes over one database — by re-reading both off the machine rather than trusting the comment that recorded them.

That is the epic''s pattern in its mildest form: **a written artefact describing a mechanism that has moved.** Here it was a criterion, and the cost was an hour of reorientation. In story 2 it was the SDK''s own types, and the cost was three stacked defects behind 1185 green tests. In story 3 it was the README''s Permissions section, and the cost was a documented install that could not start a host. Same failure, three degrees of severity, and in every case the only thing that surfaced it was going and looking at the running thing.

The two findings the story did not go looking for are also the epic''s pattern. The projection''s "Blocked by" inversion is a document that is wrong while every query behind it is right — `epic.ts`''s own docblock names that shape. ENVX1''s reading was 1185/1185 with both binaries off `PATH`, which proved nothing, because two tests reach the CLI by absolute path; the honest reading needed a `HOME` with no `.opencode` in it. **A check that passes because it did not reach its subject is indistinguishable from one that passed.** That sentence is the whole retro.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1GK2748F5GN6Y5SCERK518G', '01M1GPS7MS4BPFANKN7X9NA36A', 'retro', '01M1CB28ZZ9ESQY6FR4BSNJDSH', NULL, NULL, 1, 'Four green suites in a row certified an install that had never once loaded. The story''s job was to watch the plugin come up under a real 1.18.25 host, and what it found instead was three stacked defects, each hidden by the one above it. (1) `index.ts` exported a constant beside its route, and 1.18.25 walks every export of a plugin module and refuses the whole module on the first one that is not a plugin — one ERROR line, then a session with no server. (2) With that fixed, `skills-entry.ts` still would not load, and the reason was not in its shape at all: its route is fed by a `plugins` config key that v1''s configuration layer strips before any loader sees it, logging `path=["plugins"] kind=unsupported action="Omitted native setting that cannot be represented in V1"`. There is no arrangement of exports by which a plugin registers a skill on this host — the v1 SDK''s `Hooks` has no skill member — so the second entry had nowhere to run and was deleted. (3) With the skills moved to the `skills` config key, the server registered and then reported `server unavailable key=dpm status=failed`, because `RUNTIME` is the bare string `node` resolved off the HOST''s PATH rather than the developer''s, and the node there was 22.18.0 — dpm''s own version guard refusing, correctly, into a log nobody reads.

The through-line is that every one of the 1185 tests reached into a module and called its export itself. `tests/support/host-contexts.js` says of itself "this is a recording and not a model", and that was true of the context SHAPE it recorded and false of the module ACCEPTANCE RULE it never probed. A driver that calls `entry.server(...)` is asking a question about the module, and that question can only ever be answered yes. Library lesson 05 — ask the host, not a test''s idea of the host — named this exactly, and the suite still had no test that could fail.

What broke the deadlock was reading the loader out of the compiled CLI binary rather than reasoning from the SDK types, which turned out to disagree with the host: the SDK publishes `Plugin = {id, setup}` for a route the host it ships with cannot reach. Once the loader was legible the fix was obvious and the probes became cheap. `opencode serve` was the instrument that mattered — it stays up, and `/config`, `/mcp` and `/skill` answer directly, so "the server reached connected state" and "23 skills are registered" stopped being inferences from the absence of an error line and became readings. The absence of an error line is exactly what a run that never reached the loader produces, which is why the earlier rounds were unreadable.

Two consequences were accepted rather than absorbed. ADR 01-08''s profile seam loses its skills half — a directory the host walks takes no options — which changes nothing today because `full` is the only profile there has ever been, but FR13''s `lite` will need another mechanism. And the clash alarm is gone: `displacedSkills` read the registry back and named any `dpm-*` entry that was not dpm''s own, and there is nowhere to run it now. Probing what replaced it found something worse than expected — two entries in one `skills` array both declaring `dpm-probe` resolved last-one-wins with NO warning logged at all. The host''s `duplicate skill name` warning fires between discovery roots, not within the array. So ADR 01-05''s prefix is now the entire defence, the README carries the ordering hazard for the user, and `readme-host.test.js` pins that it does.', '**The suite could not fail, and nothing about it looked wrong.** Every driver reached into a module and called its export itself — a question about the module, answerable only yes. `host-contexts.js` had written "this is a recording and not a model" about itself, and that sentence was true of the context *shape* it recorded and false of the module *acceptance rule* it never probed. Library lesson 05 already said *ask the host, not a test''s idea of the host*; the lesson was in the library, applied at the retro gate, and the suite still had no test that could go red.

That is the sharpest thing in this epic. **A lesson can be correctly recorded, correctly recalled, and correctly dispositioned, and still not be applied — because applying it means building a fixture that starts a host, and every incremental step points the other way.** Nothing was lazy here. Each of the four green suites was a reasonable next thing to write. The gap was structural: no test in 1185 could observe the boundary, and no test that could observe the boundary was cheap enough to be the obvious next one.

What broke it was **finding the oracle** (library lesson 03) in an unexpected place: the compiled CLI binary, read with `strings`, in preference to the SDK types — which turned out to publish a route the host it ships with cannot reach. Once the loader was legible the probes became cheap, and `opencode serve` turned three inferences into three readings. The cost of *not* having that instrument is measurable: the first two rounds of this story were spent reasoning from the absence of an error line, which is exactly what a run that never reached the loader also produces. **An absence is only an observation when something was watching** — library lesson 02, met again from the other side.

Two consequences were named rather than absorbed, and both belong in the epic''s ledger: ADR 01-08''s profile seam loses its skills half (inert today, `full` being the only profile, and a real constraint on FR13''s `lite`), and the clash alarm is gone with something worse in its place — two `skills` entries declaring the same name resolve last-one-wins with **nothing logged at all**. ADR 01-05''s prefix is now the whole defence rather than half of one.', NULL, '01M1KG47SWP0BZXAVYCHB2BANG', 'library', '2026-09-03T11:25:00.000Z', 'Promoted to library 07. Its durable half is not "probe the host" — library 05 already said that and was correctly applied — but that a lesson needing a fixture nobody builds incrementally has to be scheduled as a story.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1GPFKRN3C5P28R2PZB7G642', '01M1GPS7MS4BPFANKN7X9NA36A', 'retro', '01M1CB2AHDAQ1JRMMJYB23QH4P', NULL, NULL, 2, '**`?? []` is how a test reads the wrong document and reports nothing.** The README''s Permissions section had recommended OpenCode 2''s `permissions` array — an array of `{ action, resource, effect }` — through four stories of a README the project had already retargeted at v1 alone. v1 does not ignore that key: it reports `Configuration is invalid` and the session does not start, so every reader who pasted the recommended block got a host that would not come up.

Ten tests in `permission-entries.test.js` were pointed at exactly this. They read the section''s fenced JSON with `JSON.parse(block).permissions ?? []` and got an empty list, which every loop in the file passes over in silence — "every documented rule is well-formed" is trivially true of no rules, "every skill is covered by a recommended rule" was the one that should have failed and did not, because `allowed.length > 0` was the only floor and it was checked against a list built from the same absent key. `readme-v2.test.js` checked the same blocks for parsing to a non-empty object, which the wrong shape does. Four green files, a rule with a provenance comment, and a recommendation that could not load.

The floor idiom this project uses everywhere — assert the corpus is non-empty before filtering it — was present and did not help, because it was applied to the *result* of the wrong reading rather than to the reading itself. `rules.length >= 3` says the extractor found three things; it says nothing about whether the three are the three in the document. What catches this is asserting the **shape you refuse** as an absence, not the shape you accept as a presence: `refusedBlocks()` must be empty, driven red over a planted block first.

The general form: a reader with a default is a reader that cannot report failing to find its subject. Every `?? []`, `?? {}` and `?? ''''` in a test that reads a document is a place where a renamed key becomes a clean pass.

**And the walk is what found it, which is the second half.** No amount of reading the README against itself would have surfaced this — the section is internally coherent and describes a real permission model, just a different host''s. It took pasting the block into a project and starting `opencode`. Story 2 established that the suite could not see whether the host would accept dpm''s modules; story 3 establishes the same about whether the host will accept dpm''s documentation. Both were answered by one command, in a throwaway directory, in under a minute.', '**Story 2 found a suite that could not see the host; story 3 found a suite that could not see the document.** The mechanism is the same and the tell is smaller: `JSON.parse(block).permissions ?? []`. A reader with a default cannot report failing to find its subject. Ten tests, each with an honest floor assertion, all reading a key that was not there and finding nothing to be wrong with.

The floor idiom this project uses everywhere was present and did not help, and understanding why is the transferable part. `rules.length >= 3` asserts that *the extractor found three things*. It does not assert that the three are the three in the document. The floor was placed one step too late — on the result of the reading rather than on the reading itself — and one step is all it takes.

**What catches this is asserting the shape you refuse, as an absence, driven red first.** `refusedBlocks()` must come back empty, and the control plants a block in the refused shape and shows the same reading finds it *and* yields no rules — the two facts that together made the old reading silent. That pairing is the reusable artefact from this story, and `tests/support/readme.js` is where it now lives so the two files that check the README''s blocks cannot disagree about what they are reading.

Read against the epic as a whole, story 3 completes a progression. Story 1: a criterion described a mechanism that had moved. Story 2: an SDK described a route its own host could not reach. Story 3: a README described a host that was not the one it named. **Three artefacts, each internally coherent, each wrong about the running thing, and none of them detectable from inside the artefact.** The only instrument that found any of them was starting the host and looking — a `curl` against `opencode serve`, or one `opencode run` in a throwaway directory, in under a minute each. That is cheap enough that the honest conclusion is not "we should test more" but "the walk should have come first".', NULL, '01M1KG469P8ZP8S4NVGGRM4EVW', 'library', '2026-09-03T11:25:00.000Z', 'Promoted to library 06. The `?? []` reading is the second of the three shapes that entry names, and the "assert the shape you refuse, driven red first" fix is now standing guidance rather than a lesson re-judged each run.');
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M1HG40FRMPBM22DV9KBE81ZF', NULL, NULL, NULL, '01M1HFRMWHFBPVC0KMT7CBXXC6', 'quick', 0, 'Three fixtures wrote the edge backwards and every test over them passed, because an inverted row read by an inverted reader produces the right-looking line. `corpus.js` named its source end `blocked`; `tool-corpus.js` carried a comment saying "Story 2 is held back" over a row where story 2 was the blocker; `templates.test.js`''s cross-epic case asserted the far epic''s name on the story doing the blocking. The renderer and the fixtures agreed with each other and disagreed with `readiness.ts`, which had stated the direction in as many words for four epics.', NULL, 'The fix was two lines. Getting the fixtures to state the direction they meant, so the next reader cannot learn the wrong one back from them, was most of the change. The oracle that settled it was outside both: `list_story ready: true`, which goes through `readyClause` rather than through the loader.', '01M1KG469P8ZP8S4NVGGRM4EVW', 'library', '2026-09-03T11:25:00.000Z', 'Promoted to library 06. The inverted fixture read by an inverted reader is the third shape that entry names, and it is what made the third occurrence enough to promote on.');
INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M190RZY3N512H26B7SMAPWKS', 'library', 'root', 1, NULL, 'opencode-dpm-port-spec', 'opencode-dpm: DPM Ported to OpenCode v2', 'pending', NULL, NULL, NULL, NULL, NULL, '2026-08-30T09:42:25.987Z', '2026-08-30T09:42:25.987Z', NULL, NULL);
