INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M1C6DXBMMCQ0F8PPK08H6XYF', 'epic', 'child', NULL, 1, 'v1-registrar', 'The v1 registrar', 'complete', 'Delivered against OpenCode v1 alone. The specification was written for a second registrar alongside v2 (FR11 records "both hosts stay supported from one codebase" as a `wont`); Chris retargeted the epic at v1 mid-run, so FR11 is contradicted by decision rather than overlooked. dpm ships two entry modules because v1''s two plugin protocols cannot share one, and installs from a clone because no runtime can start its MCP server from a packaged copy.', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', NULL, NULL, '2026-08-31T15:18:57.652Z', '2026-08-31T21:26:27.657Z', NULL, NULL);
INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M1C6DZ0WSWN6M2EWHT624AQN', 'epic', 'child', NULL, 2, 'skill-identity', 'Skill identity', 'complete', NULL, '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', NULL, NULL, '2026-08-31T15:18:59.356Z', '2026-09-01T07:02:16.323Z', NULL, NULL);
