INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M1C6E28V4PMVDKN1B7EJGBK7', 'epic', 'child', NULL, 4, 'two-host-docs', 'Documentation and permissions', 'complete', 'Delivered against one host, like epic 02-01 before it. Every criterion in both stories was written on a two-host premise; Chris ruled at the change moment that each be amended to the v1 property rather than superseded or worked as written, and all five carry their own "Amended from …" clause. FR6 ("cover v1 and v2") and FR7 (whose premise is that the engine matches "the unprefixed front-matter name") are both behind the decisions that overtook them — FR6 by the retarget epic 02-01 recorded, FR7 by ADR 02-04 moving the prefix onto the front matter. Four of this epic''s six coverage rows are left standing and unverified for that reason rather than retired, so the divergence stays visible to whoever revises the specification.', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', NULL, NULL, '2026-08-31T15:19:02.683Z', '2026-09-01T16:28:30.741Z', NULL, NULL);
INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M1C6E3XG8EVENPG8P74RHGGA', 'epic', 'child', NULL, 5, 'v1-walk', 'The v1 walk', 'complete', 'All three stories complete, none retired. The epic ran against a real OpenCode 1.18.25 throughout and each story found something no green test could see: story 1 the host survey, story 2 that neither plugin entry loaded — three stacked defects behind 1185 passing tests — and story 3 that the README''s Permissions section recommended a configuration v1 refuses to start on. Two changes of recorded intent were ruled on by Chris along the way: C2 superseded, and the install surface moved from "two entries, embedded skills" to `plugin` + `skills`.', '01M1BJS4H76EB2K3Z98YPNG17B', 'spec', NULL, NULL, '2026-08-31T15:19:04.367Z', '2026-09-02T09:17:00.630Z', NULL, NULL);
