INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9BQV8PX2RVJ5MJ5JGB3DN', '01M1C99W8SPDHE5RTF76GGVRKP', 3, 'Split the entry into two registrars behind the predicate', 'Restructures `src/plugin/index.ts`, keeping the exported shape a host loads unchanged and the v2 behaviour identical.', 'complete', NULL, 2);
