INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9CFEKFAZ55KRRCFT0EFAJ', '01M1C99XSZNHY02M8TZRVMPWQT', 1, 'Warn, under v1 only, that the tool surface must be configured by hand', 'The v1 registrar registers no MCP server and emits one warning naming the `mcp` block to add and the executable path it should run. Reads the server entry story 2 already computed, so the path in the message is the same one v2 registers rather than a second construction. Scope is the warning; the skills are story 4.', 'superseded', 'Written when story 3 was re-scoped to skills-without-tools, and undone by the v1-only retarget on 2026-08-31. It was implemented — `manualServerNotice` and a `registerV1` that reported it — and then reverted with `src/plugin/registrars.ts`, because a v1 load now registers its MCP server and the notice would be false. Replaced by task 3.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9CGXJ53WQGM59GPWJP8AQ', '01M1C99XSZNHY02M8TZRVMPWQT', 2, 'Write tests for Register the MCP server under v1', 'Covers the three `unit` criteria and the `integration` no-config-write criterion, whose control is the planted write.', 'complete', '`tests/v1-registrar.test.js` rewritten for the config hook — 7 tests, all passing. Also carries the two must-NOTs with their planted controls, and the module-shape check that keeps the two v1 protocols in two files.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9D5KH48RJEDP3QYGWP6EN', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 1, 'Write the single skills-path module with its unsupported marker', 'One module owns the undocumented key, per ADR 02-03. The marker states the dependency and the recovery, not the history.', 'superseded', 'There is no undocumented key to own. `config.skills.paths` is not the route: `skill.transform` takes embedded sources carrying the computed skill, which is typed and published. Replaced by task 4.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9D7309DFRQ00F6XPZBVA1', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 2, 'Implement the post-registration check and its refusal', 'Addresses the failure path the undocumented key creates: registration that silently does nothing. Scope is detection and the loud report, not a fallback mechanism.', 'superseded', 'The failure mode it detected does not exist on this route. A configuration key the host silently normalises away registers nothing while appearing to work; `draft.source` decodes what it is handed and throws on a shape it does not accept. The alarm that survives is a different one — FR5''s clash report — and it is task 4''s.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9D8P75KKZQ01C0EHVHCCJ', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 3, 'Write tests for Register the skills under v1, fenced and alarmed', 'Covers the three `unit` criteria and the `integration` no-project-write criterion, whose control is the planted write.', 'complete', '`tests/v1-skills.test.js` — 7 tests, all passing, covering the four re-scoped criteria with their controls. Added to suite-integrity''s ADDED list.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9DQQYFSQ37T2CXGA4D25X', '01M1C9A10T12G36GD9PC17DTYX', 1, 'Write the cross-registrar integration test', 'Exercises one load per host stub and asserts the whole configuration each produces. Distinct from the per-story tests, which each assert one registrar''s own key.', 'superseded', 'Written for one entry loaded under two host stubs. There is one host and two entries, and the integration check found a defect the test has to cover: the registered MCP command cannot start under v1. Replaced by tasks 2–4.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9QAM8QR2F9GKF8KVNAS07', '01M1C9NH4G73B75EAPFTR1E46T', 1, 'Rename the twenty-three skill directories to dpm-*', 'Directory names only. Every path constant that follows from them belongs to story 3.', 'complete', NULL, 0);
