INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1C9QPJ5NJW9P7PHD4AEGJEE', '01M1C9NM656AR8N6H2ESMCD6P6', 1, 'Move tests/support/skills.js off the unprefixed names', 'The shared helper roughly forty test files import. Scope is the helper, so those files need no edit of their own.', 'complete', 'Two support-module edits (`skills.js`''s PREFIX + tolerant `skillSource`, `body-reads.js`''s `prefixed` applied to CLASSIFICATION on construction) covered thirty-five files plus six body-test failures. Seven files holding a hand-kept name registry were edited: `body-reads.test.js` (REPORTED_CLEAN and two site keys), `skill-port.test.js`, `skill-reference-input.test.js`, `skills-resume.test.js`, `skills-gates.test.js`, `skill-epics.test.js`, `skill-spec.test.js`. One predicate had to move with them — `SEVEN`''s literal-check regex was `[a-z]+`, which would have gone on matching nothing.', 0);
