INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CA4VCE9YBH5J1MQ5RFJD6H', '01M1CA41FG02G8MZT4AP76Z341', 1, 'Bring the README''s account onto the one supported host, Status included', 'Retitled and rescoped at the epic''s change moment. Was "Rewrite install, first run, guard symlink and the refusal section in both host forms — four sections, each gaining a v1 form beside its v2 one." Epic 02-01 story 5 already rewrote those four for v1 and its coverage row is verified, so the residue is narrower and sits in two places: the Status section, which Chris folded into this story and which still says the fork was built for a host it no longer runs on and lists only spec 01''s epics; and the `<package path>` placeholder, which names a packaged install that no longer exists and is defined four sections after its first use, in a section a reader arriving from a guard refusal never opens.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CA4X4KM1FM6BVX4MPRFVDP', '01M1CA41FG02G8MZT4AP76Z341', 2, 'Write tests for The README covers both hosts', 'Covers the three criteria tagged `unit`. Every check reports by heading or by line, so a failure names where.', 'complete', 'tests/readme-host.test.js, 8 cases over the three amended criteria, each with its control. Added to suite-integrity.test.js''s ADDED list.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CA4YNBYK15S9DFYQB4CH4M', '01M1CA434SC66WN2SQV8MWBZGD', 1, 'State the recommended rule and what each host matches on', 'One rule, two explanations of why it matches. Addresses the guidance, not the rename that makes it true — that is epic 02-02.', 'complete', 'Two edits to README''s Permissions section: the opening paragraph, which still told every reader that one rule was worth setting whatever their configuration looked like — epic 02-03 removed that rule and left its framing; and a new paragraph after the two-axis table stating that the id a `skill` rule matches is the `name` in the skill''s own front matter, naming the file to open, and saying why a prefix applied at registration instead would be a rule that silently matches nothing.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CA50CYPKBJ5B1FK88BDTCW', '01M1CA434SC66WN2SQV8MWBZGD', 2, 'Write tests for Permission guidance per host', 'Covers the two criteria tagged `unit`, with the empty-match-set control on the recommended rule.', 'complete', 'Five cases added to tests/permission-entries.test.js rather than a new file — it already owns the transcribed glob matcher and the fenced-block reader, and a second file would have been a second copy of both, which is the four-manifests shape retro 06 recorded. No suite-integrity entry needed; the file is already listed.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB3Y88WR3AAPY3KTZFGBPR', '01M1CB27C7DJJ88XTNPGP3A4QM', 1, 'Build the cross-server dump comparison', 'Two server processes over one database, not two sessions — which is what makes this reachable without a model provider.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB40DMBZCCTBM15T4PE4Z6', '01M1CB27C7DJJ88XTNPGP3A4QM', 2, 'Run the full suite with neither host binary on PATH', 'Addresses ENVX1 directly. The failure it looks for is a test that silently depends on a binary being installed.', 'complete', 'Run with a stripped PATH and a HOME holding no `.opencode`: 1185 tests, 1183 pass, 0 fail, 2 skipped. The two are `installed-runtime.test.js` and `v1-integration.test.js`, each of which already declared ENVX1 as its warrant and left a companion control that runs regardless — so the silent binary dependency this task went looking for is not present. What was missing is any record that there are exactly two, which `suite-integrity.test.js` now holds as a named exact set.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB422FEDNNC12JH8S4AM7A', '01M1CB27C7DJJ88XTNPGP3A4QM', 3, 'Write tests for Host-independent artefacts, without models', 'Covers the two `unit` criteria and the `integration` cross-server comparison, with the planted host identifier as the sweep''s control.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB44SD7E16ASBX97SYDXT1', '01M1CB28ZZ9ESQY6FR4BSNJDSH', 1, 'Verify both CLI versions against the SDKs they are typed to', 'Confirms the CLI and the types the registrar is checked against are the same release, for each host.', 'complete', 'Scope narrowed from "for each host" to the one host, following the change moment that superseded C2 — epic 02-01 dropped the second host by decision. Verified: `opencode --version` reports 1.18.25, and node_modules/@opencode-ai/plugin-v1 resolves to @opencode-ai/plugin@1.18.25 — read from the installed tree rather than the manifest alone. Beyond the version match, the SDK types and the running host were found to DISAGREE: the SDK''s v2/promise Plugin is `{id, setup}` and 1.18.25''s loader for the `plugin` config key requires a function export or a default `{id, server()}`. The route that does accept `{id, setup}` is fed by a `plugins` config key the host strips as "cannot be represented in V1". So a version match is not a compatibility check, which is the finding this task turned up.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB46RMKXNFXJ1G35VFXMJ1', '01M1CB28ZZ9ESQY6FR4BSNJDSH', 2, 'Install into a throwaway project under each host and observe the server connect', 'Scratch projects outside the checkout, deleted after. Reaching connected state with the skills advertised is the observation; the walk itself is story 3.', 'complete', 'Scope narrowed to the one host, as task 1. Done in a throwaway project outside the checkout with a fresh XDG_CACHE_HOME per run (v1 caches plugin loading per project; a stale entry silently skips a route). The observation the task asked for took four rounds because the first three found defects rather than a connection: (1) neither entry loaded — index.ts had a non-function export and 1.18.25 refuses a module on the first export that is not a plugin; (2) with that fixed, skills-entry.ts still failed, and reading the loader out of the CLI binary showed why — its route is fed by a `plugins` config key the host strips; (3) with the skills moved to the `skills` config key, the server registered but reported `server unavailable key=dpm status=failed`, because RUNTIME is the bare string `node` resolved off the HOST''s PATH, where node was 22.18.0 and dpm''s own version guard refused. FINAL READING, node 24 on PATH, `opencode serve` against the current tree: 0 ERROR lines, 0 compatibility diagnostics, /mcp = {"dpm":{"status":"connected"}}, `node .../bin/dpm-mcp.ts` running as a child process, /skill = 54 skills of which 23 are dpm-*. Control: the same host without the `skills` key reported 31 skills, 0 of them dpm''s.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB48S1B7NA9VH6YY49G3YS', '01M1CB2AHDAQ1JRMMJYB23QH4P', 1, 'Drive the v1 walk end to end and record the evidence', 'One session covering invocation, conventions, a written row and an accepted commit. The evidence is the row, the regenerated projection and the commit — not the transcript.', 'complete', 'Driven end to end against 1.18.25 in a throwaway project outside this checkout. A real session invoked `dpm-quick` through the skill tool, called `dpm_read_shared_document` for the conventions, wrote a session row, a quick document, three criteria and an observation, closed the quick, and the guard accepted the commit that carried the projection and `.dpm/dpm.sql`. Evidence: session row `dpm:quick`/`complete`, `docs/quick/01-quick-deploy-verbose-flag.md`, commit 7d2a28a with `.dpm/dpm.db` correctly excluded by the `.dpm/.gitignore` the first tool call wrote. The commit was first attempted with nothing published, as the control: the guard refused and named both missing artefacts and the absolute publish command.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB4B5F5VMCRNEVRNZ59T83', '01M1CB2AHDAQ1JRMMJYB23QH4P', 2, 'Walk the README''s v1 instructions and the stale-projection refusal', 'Followed verbatim rather than adapted — the point is whether the written instructions work, not whether the installer knows what they meant.', 'complete', 'Followed verbatim, and the install and hook halves held: the two config keys produced a session with the MCP server connected and 23 `dpm-*` skills, `ln -s <clone>/hooks/pre-commit .git/hooks/pre-commit` resolved, `git config core.hooksPath` printed nothing, and a hand-edited line in the generated document was refused by name with the edit left in place. The Permissions half did not: it was written in OpenCode 2''s `permissions` array, which 1.18.25 refuses the whole configuration over — `Error: Configuration is invalid ... V2 permissions are not supported by OpenCode V1`. Rewritten onto v1''s singular `permission` object and re-verified live.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CB4D0GG4YR28303SQNHCYM', '01M1CB2AHDAQ1JRMMJYB23QH4P', 3, 'Exercise the permission deny rule in both directions', 'With the rule and without it. The second run is the control: a block that would have happened anyway proves nothing.', 'complete', 'Both directions, same prompt, same project, one line of config apart. With `"permission": { "skill": { "dpm-*": "deny" } }` the skill tool refused and printed the ruleset that stopped it; with the entry removed the identical call returned the body of `dpm-templates`. Two further readings taken while establishing the shape: a tool key is accepted where the host''s own key list has no entry for it, and denying one removes the tool from the model''s set entirely rather than refusing at call time — `"dpm_*": "deny"` yields a session that reports having no dpm tools at all. The README''s recommended allow-list was then run as written: skill body loaded, 184 dpm tools present, `dpm_publish: "ask"` accepted alongside `dpm_*: "allow"`.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CQAJ3QN33EG6Q9JCQNMZVJ', '01M1C99XSZNHY02M8TZRVMPWQT', 3, 'Register the MCP server through v1''s config hook', '`src/plugin/index.ts` becomes the callable route: a named `server` export, no default, returning `Hooks.config` which sets `config.mcp.dpm` to the entry `localServer` builds. The user''s own `mcp` block is spread rather than replaced, and each load is handed its own copy of the command array. `src/plugin/registration.ts` splits into `serverEntry` and `skillSources` so a skill-body failure cannot take down the MCP registration. `host.ts` and `registrars.ts` are deleted.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CQP6ZTWNKW1NGKSF369CDM', '01M1C99ZKVV6FGAB9QS4YA5JPJ', 4, 'Register the skills as embedded sources, with the prefix on name and a clash report', '`src/plugin/skills-entry.ts` is the object route: default `{id, setup}` calling `skill.transform` and handing the draft one `{type:''embedded'', skill}` per discovered skill. `registration.ts` puts the `dpm-` prefix on `name` — the only field v1 keeps — which is the fence FR5 asks for and also makes the README''s `dpm-*` permission rule match under v1 (FR7). Before registering, the draft is read for names already claimed by other embedded sources and any dpm is about to shadow is reported on stderr; the notice states its own reach, since a clash behind a directory or url source is not visible at that point.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CTKY9WKCKM2ZCXYTZC2EQH', '01M1C9A10T12G36GD9PC17DTYX', 2, 'Register a runtime a v1 host can actually spawn', '`localServer`''s bun branch hands the host its own binary in bun mode, on the recorded belief that bun carries `node:sqlite`. That held for v2''s bun and does not hold for v1''s (Bun 1.3.14): the server dies on `No such built-in module: node:sqlite` and the host blocks waiting for it. Register `node` instead, and say in the doc comment which bun the old rationale was true of.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CTM3TY9BJG962DKP0X60PX', '01M1C9A10T12G36GD9PC17DTYX', 3, 'Write the cross-entry integration test', 'One pass loads both entries against the recorded v1 context and asserts the whole result: `mcp.dpm` present, twenty-three embedded skill sources present, and both resolved from the same package root. Plus the startability reading and its control, which is what the per-story tests could not see — each asserted its own registrar''s key and neither asked whether the command would run.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M1CTM9ZVTF2100BYDTXXKG51', '01M1C9A10T12G36GD9PC17DTYX', 4, 'Document the v1 install the epic actually delivers — FR6', 'The README names `opencode2 plugin add github:ninthspace/opencode-dpm` and one entry. Under v1 that install cannot supply tools at all: v1 unpacks plugins under `node_modules`, where Node refuses to strip types. What works is a checkout with both entry paths in `plugin`. FR6 is unowned by any story and the install route changed under this epic, so it is documented here rather than left describing something that cannot work.', 'complete', 'Reached further than scoped. The install section was one of five places built on the packaged model — the link instructions, the shell functions, the `external_directory` permission entry, the out-of-date-guard section and the develop-DPM-itself section all named a package cache — and two test files guarded that model. All were converted; `package-cache.test.js` and its fixture became `readme-symlink.test.js` and `support/dpm-clone.js`.', 3);
