INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HHSM71NN98QT8VJEQ18T', '01M1BNA64G8R17416TT8JB50J3', 'the one appropriate to the host runs for the host that loaded it', '01M1C9B3FR9TCS7YFXNV02SN1Q', 0, '2026-08-31T18:45:00.000Z', 'fa208bb18da21b7b36f66a941bcdc9221ec0d96803c6ea2361fe05aaf7c2e0e2', '2026-08-31T21:20:00.000Z', 'The criterion this bound was superseded: Overtaken by Chris''s decision on 2026-08-31 to target OpenCode v1 alone ("given we can''t currently work with a v2 of opencode, let''s concentrate on v1"), taken at an explicit gate that named this story''s verified work as the cost. With one host there is no host to classify: `src/plugin/host.ts` and its `hostOf` predicate are deleted, and so is the two-registrar dispatch this criterion measured. What replaced it is two modules, one per v1 protocol, both loaded unconditionally — nothing classifies anything at run time. The criterion is not merely unmet, it names a mechanism that no longer exists.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HK76W0KFSGH7VENPHKV3', '01M1BNA64G8R17416TT8JB50J3', 'the one appropriate to the host runs for the host that loaded it', '01M1C9B51VC1D91R1ZRCPGS88X', 1, '2026-08-31T18:45:00.000Z', 'f5c286e4b5b7a91e005738fe22c8109050abfad1f9763bc7922f90778c519415', '2026-08-31T21:20:00.000Z', 'The criterion this bound was superseded: Superseded with 01M1C9B3FR9TCS7YFXNV02SN1Q, whose predicate it was the control on. A control on a classification that no longer happens has nothing to be a control on.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HNG49VY8BJ4MDPM6MTNQ', '01M1BNA64G8R17416TT8JB50J3', 'the user does not choose a registrar', '01M1C9B9G2ZS5ND1ZC3SBBHFM2', 2, '2026-08-31T18:45:00.000Z', '09b921860de57f2fa94f6c55bd0b3565f2fb000dcc449635210b131305866d58', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HPX1ETVHHX6RMVHZTHJH', '01M1BNA64G8R17416TT8JB50J3', 'all twenty-three skills advertised', '01M1C9CPMG8Q81F4YRHTF1A43X', 3, NULL, NULL, '2026-08-31T21:45:00.000Z', 'The criterion this bound was superseded: `config.skills.paths` is not the route, and does not need to be. Probing v1 1.18.25 found `skill.transform` on the object-route context, whose draft takes `{type:''embedded'', skill}` sources carrying the computed skill rather than a path to it — a typed, published API where `skills.paths` is absent from both the SDK types and the live schema. The replacement criterion measures the same outcome, twenty-three skills each resolving inside the installed package, against the mechanism actually used.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HRQZMM6382G7ZNPW3FJ6', '01M1BNA64G8R17416TT8JB50J3', 'The package registers itself with a v1 host', '01M1C9DF7A3F1VBR95AW7MR06A', 4, NULL, NULL, '2026-08-31T23:00:00.000Z', 'The criterion this bound was superseded: Names `skills.paths`, which is not the route. v1 registers skills through `skill.transform`''s embedded sources, and the two registrations come from two modules rather than one load. Replaced by the criterion that asserts both entries resolving from one package root.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HTTPDYJ6N8RPK6AP5PB2', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'Registration goes through v1''s `config` hook, setting a local server entry whose command runs the packaged executable', '01M1C9C16CF1HKKNM8TZ304BF9', 0, NULL, NULL, '2026-08-31T19:03:30.620Z', 'The criterion it binds was superseded. Probes against opencode 1.18.25 establish that v1''s `config` hook is reachable only from a module with NO default export: with a default present v1 calls `default.setup(context)` and never looks at the named `server` export (observed, with the default''s own call as the control in the same run). v2 requires a default export object and ignores a callable one entirely. So the mechanism FR2 names cannot coexist with v2 support in one entry file. Chris decided on 2026-08-31, twice and with FR2''s text in front of him, that v1 registers skills and not tools. FR2 is therefore left undischarged rather than bound to a criterion that cannot be met, and amending FR2 is a separate decision outside this run.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HWYA9QMXJ7C4AP7NMM43', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'the same `{type:"local", command, environment?}` shape the v2 registrar already builds', '01M1C9C2JVQ99QVD2B54G1FQFB', 1, NULL, NULL, '2026-08-31T19:03:37.783Z', 'The criterion it binds was superseded alongside 01M1C9C16CF1HKKNM8TZ304BF9. With no MCP server registered under v1 there is no v1-built local-server entry to compare against the v2 one, so the fragment has nothing left to bind to. The shape claim itself survives untouched in story 2: `registrationInputs` computes ONE server entry above the host branch and hands the same object to whichever registrar runs, which is verified by coverage row 01M1C9J4DRYB598ZF5H5ZG4R1S.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9HYCNCAW3Q1KAQ2JV3K39', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'no host-specific tool exists', '01M1C9C433GZSJYWA47WA53SNF', 2, '2026-08-31T21:30:00.000Z', 'b4fb59ff42ccdd2324108a57ef7a574817868d3f33daad48a7f7409811e2a159', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9J0720JSDDRHQK41SXBN5', '01M1BNABQBYGFEQY397MNZHK96', 'each skill resolves with its `location` inside the installed package', '01M1C9CPMG8Q81F4YRHTF1A43X', 0, NULL, NULL, '2026-08-31T21:45:00.000Z', 'The criterion this bound was superseded: `config.skills.paths` is not the route, and does not need to be. Probing v1 1.18.25 found `skill.transform` on the object-route context, whose draft takes `{type:''embedded'', skill}` sources carrying the computed skill rather than a path to it — a typed, published API where `skills.paths` is absent from both the SDK types and the live schema. The replacement criterion measures the same outcome, twenty-three skills each resolving inside the installed package, against the mechanism actually used.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9J2B3VAD5JWX4T2H7Y1WF', '01M1BPMGZXZB58QP8GVR9M2MGG', 'host-specific code is confined to the registration layer', '01M1C9B81E9XT1ND7TT6ZGFWC5', 0, '2026-08-31T18:45:00.000Z', '71f5129d3b5b75eb98f009c26eba5516c05d784ce34a61bbe3c60943460462c4', '2026-08-31T21:20:00.000Z', 'The criterion this bound was superseded: Superseded with the predicate it names. `hostOf` is deleted, so a rule about where its identifier may appear has no subject. NFR1''s underlying claim — that host-specific code is confined to the registration layer — is not lost: it moves to story 3''s must-NOT sweep, which reads the same corpus with the same planted control and now carries the NFR1 binding.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9J4DRYB598ZF5H5ZG4R1S', '01M1BPMGZXZB58QP8GVR9M2MGG', 'Skill bodies, tool schemas, the MCP server, the guard and the database are shared verbatim between hosts', '01M1C9B6J1PTGJ3P0P6XKCX68Z', 1, '2026-08-31T18:45:00.000Z', '663452a8c2ff5e47d77950b98ee8a776a37211eeb4b3e0c3d563b1d8f4212d6f', '2026-08-31T21:20:00.000Z', 'The criterion this bound was superseded: Superseded by the v1-only retarget. There are no registrars to give one thing to: dpm now ships two plugin modules, one per v1 protocol, and they register different things — the tools module a server entry, the skills module a skill list. The claim worth keeping from this criterion is narrower and survives in `src/plugin/registration.ts`, where both modules resolve the same package root through `packageRoot`, and it is verified by story 3''s criterion on the registered entry being the one `localServer` builds.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9J61XBVQD98V294DT1S10', '01M1BPMGZXZB58QP8GVR9M2MGG', 'One codebase, no per-host fork', '01M1C9DGTHEHZZ0BDT3XH4Z504', 2, NULL, NULL, '2026-08-31T23:00:00.000Z', 'The criterion this bound was superseded: Measures behaviour under a v2 context. v2 was dropped from this epic by explicit decision, so there is no second host to compare against. Replaced by the criterion that the registered MCP command is one a v1 host can actually spawn — the defect this story''s integration check found.');
