INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9JE465ENE0DGK41R8X36S', '01M1BPMQ9D1KJKY0VY1AZYM90N', 'from exactly one place, named as unsupported where a maintainer will read it', '01M1C9CR08ZB1164JA14S99FEF', 0, NULL, NULL, '2026-08-31T21:45:00.000Z', 'The criterion this bound was superseded: There is no undocumented key to fence. NFR3 required `config.skills.paths` to be written from exactly one module and marked as unsupported; the embedded-source route means it is written from none. The requirement''s premise dissolved rather than being satisfied, which is reported at the epic roll-up rather than claimed as coverage.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1C9JFM3CQJK4STKK15HEQ8B', '01M1BPMQ9D1KJKY0VY1AZYM90N', 'with a check that fails when it stops working', '01M1C9CSDYS6MC1QEWMRNPCHGZ', 1, NULL, NULL, '2026-08-31T21:45:00.000Z', 'The criterion this bound was superseded: The post-registration check existed because a configuration key the host silently normalises away registers nothing while appearing to work. `skill.transform` fails at the call instead: the draft''s `source` decodes what it is given and throws on a shape it does not accept, which is how the embedded variant was established in the first place. There is no silent-no-op failure mode left for a check to detect.');
