INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CA51ZY5R10N7KRWQ81KEGW', '01M1BNAMK908YZGSX62CN3XYA8', 'README install, first run, guard symlink and "when the guard refuses" cover v1 and v2', '01M1CA47HB76P2MMC5DKXCH5CT', 0, NULL, NULL, '2026-09-03T12:16:37.632Z', 'The fragment quotes FR6''s two-host text, which Chris''s ruling at epic 02-04''s change moment overtook: the delivered README states there is no other host dpm runs under, and `readme-host.test.js` now forbids it naming one. Epic 02-04 left this row standing and unverified rather than retiring it, so the divergence would stay visible to whoever revised the spec — this pivot is that revision. FR6 itself is left as the record of what was specified; the binding is what goes.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CA53F4RTJ75K0ZZ4Y02RDV', '01M1BNAMK908YZGSX62CN3XYA8', 'with the plugin-package location correct for each host rather than one location presented as the location', '01M1CA4960YYC007SZK6C5TJ7M', 1, NULL, NULL, '2026-09-03T12:16:40.113Z', 'The fragment''s "correct for each host" has no second member once the README documents one host, so the criterion it binds cannot discharge it as written. Left standing and unverified by epic 02-04 as a marker for the spec revision; retired here rather than verified, because verifying it would record the README as covering a host its own must-NOT forbids it from naming.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CA552G2FHMD2ZR2F3Q3ER5', '01M1BNAMK908YZGSX62CN3XYA8', 'rather than one location presented as the location', '01M1CA4AS46KMS7W359SAXF2G4', 2, NULL, NULL, '2026-09-03T12:16:41.968Z', 'Same ruling as the two rows beside it: "rather than one location presented as the location" is the per-host contrast, and there is one host in the delivered documentation. Retired as part of the same marker set epic 02-04 left for this revision.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CA56NVY2NEDGH4H306SZD7', '01M1BNAQEHN5PVRC0H8K2RBAGD', 'The recommended entries are stated per host, against what that host actually matches on', '01M1CA4CBZ3SAQFNS7NGZ1AENN', 0, NULL, NULL, NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CA587FDRSBWCZW014GZM7R', '01M1BNAQEHN5PVRC0H8K2RBAGD', 'v1''s permission engine evaluates the `skill` action against the unprefixed front-matter name', '01M1CA4E2EEVBV0KVJCZ6G901G', 1, NULL, NULL, '2026-09-03T12:18:08.268Z', 'The fragment quotes FR7''s premise that the engine matches "the unprefixed front-matter name". Epic 02-02 put the `dpm-` prefix into the front matter and dissolved that premise, and this pivot rewrote FR7 to say what the engine actually matches — so the fragment is no longer a substring of the requirement it binds. Epic 02-04 left the row unverified deliberately, as the marker for this revision.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CB5892K3VWJ8MY1BXTZ45E', '01M1BNASYFZ7EN67Z2DWJXEPR8', 'A session starts a dpm skill by its documented invocation, the skill reads its conventions, a dpm tool writes a row, and the guard accepts the resulting commit', '01M1CB2WS1XBHX79CZNJ3GEVGC', 0, '2026-09-02T09:30:00Z', '472e7659c3fbbc0cce3cf6e1c8bb10fb4786560fa064b56c0d3c2d2d4dc41d3a', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CB5A6MVYBNF2RKZ90QNWBA', '01M1BNAF4SK9RY6GEWY1B755T1', 'The requirement is satisfied when a real session reads the file, not when a path exists', '01M1CB2YA8GZ9AMGN2QC0RB1ZD', 5, '2026-09-02T09:30:00Z', 'd446d0a1c2ccccd40c1f7966a6e83a54da127074001a580b09c3279009a85f7a', NULL, NULL);
