INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CB5PZAE90A5M0TTQWNZS5V', '01M1BPX8BFXTSJRXFTKV9P55B3', '`opencode2 --version` reporting a `0.0.0-beta-*` build matching the v2 SDK', '01M1CB2P6HF8E1EZ4KZ4MKFT11', 0, NULL, NULL, '2026-09-02T06:46:03Z', 'The criterion this bound was superseded: Retired at epic 02-05''s change moment. It pinned the second host''s build against the v2 SDK, and epic 02-01 dropped that host by decision — see its status_note. The property it was a mechanism for, that the CLI run and the SDK types checked against are the same release, is already carried whole by this story''s first criterion for the host DPM does target. Amending it to the v1 property would have produced a duplicate of that criterion rather than a second measure.');
