INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQ9SCX9Q2A4VN673KEX3TE', '01M1BNA64G8R17416TT8JB50J3', 'A single documented install route', '01M1CQ9702QK3TB7TVB98YBDYC', 0, NULL, NULL, '2026-08-31T20:14:02.470Z', 'Bound in error. The criterion establishes the two modules'' export shapes, which is what makes two entries necessary; it does not establish that the route is documented. FR1''s install-route fragment needs the README, which still says `opencode2 plugin add` and names one entry.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQN9KJ9N6RAT5PM9JR8J7X', '01M1BNABQBYGFEQY397MNZHK96', 'each skill resolves with its `location` inside the installed package', '01M1CQFJYA7ANXR45Q3Q0WYR00', 0, NULL, NULL, '2026-09-03T12:18:11.103Z', 'The criterion bound here asserts the skills module registers twenty-three skills as `embedded` sources through `skill.transform`. Epic 02-05 story 2 established that v1''s plugin `Hooks` has no skill member and deleted that entry; the mechanism does not exist, so the binding cannot be re-verified and FR3 now says in as many words that there is no v1 skills registrar.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQNBPCF3J4NWJQRXB2XNE2', '01M1BNABQBYGFEQY397MNZHK96', 'registered rather than copied — holds unchanged under v1', '01M1CQFJYA7ANXR45Q3Q0WYR00', 1, NULL, NULL, '2026-09-03T12:18:14.573Z', 'Same criterion as the row above, and gone for the same reason: it names the `skill.transform` registration epic 02-05 deleted. The property the fragment quotes — registered rather than copied — still holds under the `skills` configuration key, but nothing live asserts it, which is the gap this retirement makes visible instead of hiding.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQNDWZD9Q5JPJNHQ9JQTMG', '01M1BNAJDWSKAWRJ2SJMMX8KBH', 'dpm''s skills survive v1''s flat name keyspace', '01M1CQFMY37V5QHRJ2FAS68GCY', 0, '2026-08-31T22:00:00.000Z', 'c3d95a3e40d5ff370fbb4d48a924327b1be1db3bde4633afd2312899eeed563e', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQNG5N8A0JVEP7BKJFWETH', '01M1BNAJDWSKAWRJ2SJMMX8KBH', 'a collision is not silent', '01M1CQFQNT1SK75RRFAX20A0KR', 1, '2026-08-31T22:00:00.000Z', '662f8608393d753d82a43ba793608b7d07b4d2fc253090e40e5449e5f3e19260', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CQNNHBMCS6KCY44XKC3NNN', '01M1BNABQBYGFEQY397MNZHK96', 'so directory-based skills keep their supporting files', '01M1CQFT8PHQEP732X6ZSSW63Y', 2, NULL, NULL, '2026-09-03T12:18:19.237Z', 'The criterion asserts every `dpm/shared/*.md` reference is rewritten to an absolute path at registration. ADR 02-01 replaced that rewrite with the shared-document MCP tool and epic 02-03 story 3 deleted `resolveSupportingPaths`, so the criterion names a registration-time transform the package no longer performs.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CVBXTCG7S2ZDBHGG83FKTM', '01M1BNA64G8R17416TT8JB50J3', 'the MCP server registered and connected, all twenty-three skills advertised, and nothing further for the user to copy into the project', '01M1CTJKPFR5GRZZJM7FD6C01W', 0, '2026-08-31T23:45:00.000Z', '915d706833184607d391eed126617d9d23484677ad428519960daee0563544bc', NULL, NULL);
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CVC30NDPVK59SM0KNPQA51', '01M1BNABQBYGFEQY397MNZHK96', 'each skill resolves with its `location` inside the installed package so directory-based skills keep their supporting files', '01M1CTJKPFR5GRZZJM7FD6C01W', 1, NULL, NULL, '2026-09-03T12:18:17.309Z', 'The criterion asserts one load of *both* plugin entries produces a skill registry of twenty-three embedded sources. The second entry was deleted in epic 02-05 story 2 — there is no arrangement of exports by which a v1 plugin registers a skill — so the criterion describes a load that cannot happen.');
INSERT INTO "coverage" ("id", "requirement_id", "spec_fragment", "story_criterion_id", "position", "verified_at", "binding_hash", "retired_at", "retired_reason") VALUES ('01M1CVC8T78SG9R34C9WM7WD6V', '01M1BNA8VH5EFC9KYCZJHZSSTG', 'setting a local server entry whose command runs the packaged executable', '01M1CTJS1KB95H0N3ZHKGR9VWQ', 2, '2026-08-31T23:45:00.000Z', 'c4a303cdb37fbe15755b2cdbd1c1b8a80bedca612354e7c311cdad0328bc8d05', NULL, NULL);
